// Package cmdapi implements the command line interface of the tool.
package cmdapi

import (
	"fmt"
	"os"

	"github.com/spf13/cobra"
)

const (
	versionText = `atlas unofficial version - development
https://github.com/ariga/atlas/releases/latest
To download an official version, visit: https://atlasgo.io/getting-started#installation
`
	licenseText = `LICENSE
Atlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.
`
	// operatorVersion is the version string recorded in the revisions table.
	operatorVersion = "Atlas CLI - development"
)

// Root returns the root command of the CLI with all sub-commands attached.
func Root() *cobra.Command {
	root := &cobra.Command{
		Use:          "atlas",
		Short:        "Manage your database schema as code",
		SilenceUsage: true,
	}
	root.AddCommand(
		versionCmd(),
		licenseCmd(),
		schemaCmd(),
		migrateCmd(),
	)
	return root
}

// Main runs the CLI with the given arguments and returns the exit code.
func Main(args []string) int {
	root := Root()
	root.SetArgs(args)
	err := root.Execute()
	flushNotices()
	if err != nil {
		suggestOfficial()
		return 1
	}
	return 0
}

func versionCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "version",
		Short: "Prints this Atlas CLI version information.",
		Run: func(cmd *cobra.Command, _ []string) {
			fmt.Fprint(cmd.OutOrStdout(), versionText)
		},
	}
}

func licenseCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "license",
		Short: "Display license information",
		Run: func(cmd *cobra.Command, _ []string) {
			fmt.Fprint(cmd.OutOrStdout(), licenseText)
		},
	}
}

// exitErr is an error that already printed its message and only carries the exit code.
type exitErr struct{ code int }

func (e exitErr) Error() string { return fmt.Sprintf("exit %d", e.code) }

var stderr = os.Stderr
EOF
echo ok"}

