	"fmt"
	"os"
	"path/filepath"
	"time"
)

const (
	communityNotice = `Notice: This Atlas edition lacks support for features such as checkpoints,
testing, down migrations, and more. Additionally, advanced database objects such as views, 
triggers, and stored procedures are not supported. To read more: https://atlasgo.io/community-edition

To install the non-community version of Atlas, use the following command:

	curl -sSf https://atlasgo.sh | sh

Or, visit the website to see all installation options:

	https://atlasgo.io/docs#installation

`
	officialSuggestion = `You're running the community build of Atlas, which may differ from the official version.
If this error persists, try installing the official version as a troubleshooting step:

  curl -sSf https://atlasgo.sh | sh

More installation options: https://atlasgo.io/docs#installation
`
)

// stateDir returns the directory used to persist CLI state.
func stateDir() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".atlas"), nil
}

// readStamp reads the timestamp stored under key in the given state file.
func readStamp(file, key string) (time.Time, bool) {
	dir, err := stateDir()
	if err != nil {
		return time.Time{}, false
	}
	b, err := os.ReadFile(filepath.Join(dir, file))
	if err != nil {
		return time.Time{}, false
	}
	var m map[string]string
	if err := json.Unmarshal(b, &m); err != nil {
		return time.Time{}, false
	}
	s, ok := m[key]
	if !ok {
		return time.Time{}, false
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

// writeStamp stores the current time under key in the given state file.
func writeStamp(file, key string) {
	dir, err := stateDir()
	if err != nil {
		return
	}
	if err := os.MkdirAll(dir, 0755); err != nil {
		return
	}
	b, err := json.Marshal(map[string]string{key: time.Now().UTC().Format(time.RFC3339Nano)})
	if err != nil {
		return
	}
	_ = os.WriteFile(filepath.Join(dir, file), b, 0644)
}

// shouldNotify reports whether the notice identified by file/key should be printed again.
func shouldNotify(file, key string, every time.Duration) bool {
	last, ok := readStamp(file, key)
	if !ok {
		return true
	}
	return time.Since(last) >= every
}

// communityNoticed guards against printing the community notice twice in one run.
var communityNoticed bool

// communityEditionNotice prints the community-edition notice (at most once a week).
func communityEditionNotice() {
	if communityNoticed {
		return
	}
	communityNoticed = true
	if !shouldNotify("local-community.json", "v1.us", 7*24*time.Hour) {
		return
	}
	fmt.Fprint(stderr, communityNotice)
	writeStamp("local-community.json", "v1.us")
}

// suggestOfficial prints the suggestion to install the official build after an error
// (at most once a day).
func suggestOfficial() {
	if !shouldNotify("community_error.json", "last_suggested", 24*time.Hour) {
		return
	}
	fmt.Fprint(stderr, officialSuggestion)
	writeStamp("community_error.json", "last_suggested")
}

func flushNotices() {}
EOF
echo done

