	flagFrom            = "from"
	flagDevURL          = "dev-url"
	flagSchema          = "schema"
	flagExclude         = "exclude"
	flagInclude         = "include"
	flagDryRun          = "dry-run"
	flagAutoApprove     = "auto-approve"
	flagFormat          = "format"
	flagTxMode          = "tx-mode"
	flagPlan            = "plan"
	flagEdit            = "edit"
	flagLockTimeout     = "lock-timeout"
	flagDir             = "dir"
	flagDirFormat       = "dir-format"
	flagRevisionsSchema = "revisions-schema"
	flagBaseline        = "baseline"
	flagExecOrder       = "exec-order"
	flagAllowDirty      = "allow-dirty"
	flagQualifier       = "qualifier"
	flagLatest          = "latest"
	flagGitBase         = "git-base"
	flagGitDir          = "git-dir"
	flagConfig          = "config"
	flagEnv             = "env"
	flagVar             = "var"
)

// Vars holds the input variables provided with the --var flag.
type Vars map[string][]string

// String implements pflag.Value.
func (v Vars) String() string {
	keys := make([]string, 0, len(v))
	for k := range v {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, k := range keys {
		parts = append(parts, k+":"+strings.Join(v[k], ","))
	}
	return "[" + strings.Join(parts, " ") + "]"
}

// Set implements pflag.Value.
func (v *Vars) Set(s string) error {
	kv := strings.SplitN(s, "=", 2)
	if len(kv) != 2 {
		return fmt.Errorf("variables must be format as key=value, got: %q", s)
	}
	if *v == nil {
		*v = make(Vars)
	}
	(*v)[kv[0]] = append((*v)[kv[0]], kv[1])
	return nil
}

// Type implements pflag.Value.
func (v Vars) Type() string { return "<name>=<value>" }

// globalFlags holds the values of the persistent (project) flags.
type globalFlags struct {
	ConfigURL string
	Env       string
	Vars      Vars
}

func addGlobalFlags(cmd *cobra.Command, g *globalFlags) {
	cmd.PersistentFlags().StringVarP(&g.ConfigURL, flagConfig, "c", "file://atlas.hcl", "select config (project) file using URL format")
	cmd.PersistentFlags().StringVar(&g.Env, flagEnv, "", "set which env from the config file to use")
	cmd.PersistentFlags().Var(&g.Vars, flagVar, "input variables")
}

func addFlagURL(set *pflag.FlagSet, target *string) {
	set.StringVarP(target, flagURL, "u", "", "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
}

func addFlagToURLs(set *pflag.FlagSet, target *[]string) {
	set.StringSliceVar(target, flagTo, nil, "[driver://username:password@address/dbname?param=value] select a desired state using the URL format")
}

func addFlagFromURLs(set *pflag.FlagSet, target *[]string) {
	set.StringSliceVarP(target, flagFrom, "f", nil, "[driver://username:password@address/dbname?param=value] select a resource using the URL format")
}

func addFlagDevURL(set *pflag.FlagSet, target *string) {
	set.StringVar(target, flagDevURL, "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
}

func addFlagSchemas(set *pflag.FlagSet, target *[]string) {
	set.StringSliceVarP(target, flagSchema, "s", nil, "set schema names")
}

func addFlagExclude(set *pflag.FlagSet, target *[]string) {
	set.StringSliceVar(target, flagExclude, nil, "list of glob patterns used to filter resources from applying")
}

func addFlagInclude(set *pflag.FlagSet, target *[]string) {
	set.StringSliceVar(target, flagInclude, nil, "list of glob patterns used to select which resources to keep in inspection")
}

func addFlagDryRun(set *pflag.FlagSet, target *bool) {
	set.BoolVar(target, flagDryRun, false, "print SQL without executing it")
}

func addFlagAutoApprove(set *pflag.FlagSet, target *bool) {
	set.BoolVar(target, flagAutoApprove, false, "apply changes without prompting for approval")
}

func addFlagFormat(set *pflag.FlagSet, target *string) {
	set.StringVar(target, flagFormat, "", "Go template to use to format the output")
}

func addFlagLockTimeout(set *pflag.FlagSet, target *time.Duration) {
	set.DurationVar(target, flagLockTimeout, 10*time.Second, "set how long to wait for the database lock")
}

func addFlagDirURL(set *pflag.FlagSet, target *string) {
	set.StringVar(target, flagDir, "file://migrations", "select migration directory using URL format")
}

func addFlagDirFormat(set *pflag.FlagSet, target *string) {
	set.StringVar(target, flagDirFormat, "atlas", "select migration file format")
}

func addFlagRevisionSchema(set *pflag.FlagSet, target *string) {
	set.StringVar(target, flagRevisionsSchema, "", "name of the schema the revisions table resides in")
}
EOF
echo ok"}

