		s.emit(TokenComment, start)
		return
	case s.hasPrefix("/*"):
		s.advance(2)
		for !s.eof() && !s.hasPrefix("*/") {
			s.advance(1)
		}
		if !s.eof() {
			s.advance(2)
		}
		s.emit(TokenComment, start)
		return
	case c == '"':
		s.advance(1)
		s.emit(TokenOQuote, start)
		s.push(scanFrame{mode: modeTemplate})
		return
	case s.hasPrefix("<<"):
		if s.scanHeredocOpen() {
			return
		}
		s.advance(1)
		s.emit(TokenLessThan, start)
		return
	case isDigit(c):
		s.scanNumber()
		return
	}
	r, size := utf8.DecodeRune(s.src[s.pos.Byte:])
	if r == utf8.RuneError && size == 1 {
		s.advance(1)
		s.emit(TokenBadUTF8, start)
		return
	}
	if isIdentStart(r) {
		s.advance(size)
		for !s.eof() {
			r, size := utf8.DecodeRune(s.src[s.pos.Byte:])
			if !isIdentContinue(r) {
				break
			}
			s.advance(size)
		}
		s.emit(TokenIdent, start)
		return
	}
	// Operators and punctuation.
	type op struct {
		lit string
		typ TokenType
	}
	ops := []op{
		{"...", TokenEllipsis}, {"==", TokenEqualOp}, {"!=", TokenNotEqual}, {"<=", TokenLessThanEq},
		{">=", TokenGreaterThanEq}, {"&&", TokenAnd}, {"||", TokenOr}, {"::", TokenDoubleColon},
		{"=>", TokenFatArrow}, {"**", TokenStarStar},
		{"{", TokenOBrace}, {"}", TokenCBrace}, {"[", TokenOBrack}, {"]", TokenCBrack},
		{"(", TokenOParen}, {")", TokenCParen}, {"*", TokenStar}, {"/", TokenSlash},
		{"+", TokenPlus}, {"-", TokenMinus}, {"%", TokenPercent}, {"=", TokenEqual},
		{"<", TokenLessThan}, {">", TokenGreaterThan}, {"!", TokenBang}, {".", TokenDot},
		{",", TokenComma}, {"?", TokenQuestion}, {":", TokenColon},
		{"&", TokenBitwiseAnd}, {"|", TokenBitwiseOr}, {"~", TokenBitwiseNot}, {"^", TokenBitwiseXor},
		{"'", TokenApostrophe}, {"`", TokenBacktick}, {";", TokenSemicolon},
	}
	for _, o := range ops {
		if s.hasPrefix(o.lit) {
			f := s.frame()
			switch o.typ {
			case TokenOBrace:
				f.depth++
			case TokenCBrace:
				if f.depth == 0 && len(s.stack) > 1 {
					// End of a template interpolation sequence.
					if s.hasPrefix("~}") {
						s.advance(2)
