		n := 1
		if d := s.peekAt(1); d == '+' || d == '-' {
			n = 2
		}
		if isDigit(s.peekAt(n)) {
			s.advance(n)
			for !s.eof() && isDigit(s.peek()) {
				s.advance(1)
			}
		}
	}
	s.emit(TokenNumberLit, start)
