// scanHeredocOpen tries to scan a heredoc introducer at the current position.
func (s *Scanner) scanHeredocOpen() bool {
	rest := s.src[s.pos.Byte:]
	i := 2
	if i < len(rest) && rest[i] == '-' {
		i++
	}
	j := i
	for j < len(rest) {
		r, size := utf8.DecodeRune(rest[j:])
		if j == i && !isIdentStart(r) || j > i && !isIdentContinue(r) {
			break
		}
		j += size
	}
	if j == i {
		return false
	}
	marker := rest[i:j]
	k := j
	if k < len(rest) && rest[k] == '\r' {
		k++
	}
	if k >= len(rest) || rest[k] != '\n' {
		return false
	}
	k++
	start := s.pos
	s.advance(k)
	s.emit(TokenOHeredoc, start)
	s.push(scanFrame{mode: modeHeredoc, marker: marker, lineStart: true})
	return true
}

func (s *Scanner) scanTemplate() {
	start := s.pos
	c := s.peek()
