			s.advance(3)
		} else {
			s.advance(2)
		}
		s.emit(TokenTemplateControl, start)
		s.push(scanFrame{mode: modeNormal})
		return
	}
	for !s.eof() {
		if s.hasPrefix("${") || s.hasPrefix("%{") {
			break
		}
