package hcl

import (
	"bytes"
	"unicode"
	"unicode/utf8"
)

type scanMode int

const (
	modeNormal scanMode = iota
	modeTemplate
	modeHeredoc
)

type scanFrame struct {
	mode scanMode
	// depth counts the open braces within an interpolation sequence so
	// that the matching closing brace can be recognised as the end of the
	// sequence.
	depth int
	// marker is the heredoc end marker (heredoc mode only).
	marker []byte
	// lineStart reports that the heredoc scanner is at the start of a line.
	lineStart bool
}

// Scanner tokenizes HCL source.
type Scanner struct {
	src      []byte
	filename string
	pos      Pos
	stack    []scanFrame
	tokens   Tokens
}

// Lex scans the given source and returns all tokens, including comments and
// newlines, terminated by an EOF token.
func Lex(src []byte, filename string) Tokens {
	s := &Scanner{src: src, filename: filename, pos: Pos{Line: 1, Column: 1}}
	s.stack = []scanFrame{{mode: modeNormal}}
	s.run()
	return s.tokens
}

func (s *Scanner) frame() *scanFrame { return &s.stack[len(s.stack)-1] }

func (s *Scanner) push(f scanFrame) { s.stack = append(s.stack, f) }

func (s *Scanner) pop() {
	if len(s.stack) > 1 {
		s.stack = s.stack[:len(s.stack)-1]
	}
}

func (s *Scanner) eof() bool { return s.pos.Byte >= len(s.src) }

func (s *Scanner) peek() byte {
	if s.eof() {
		return 0
	}
	return s.src[s.pos.Byte]
}

func (s *Scanner) peekAt(n int) byte {
	if s.pos.Byte+n >= len(s.src) {
		return 0
	}
	return s.src[s.pos.Byte+n]
}

func (s *Scanner) hasPrefix(p string) bool {
	return bytes.HasPrefix(s.src[s.pos.Byte:], []byte(p))
}

// advance moves the position forward by n bytes, updating line/column info.
func (s *Scanner) advance(n int) {
	end := s.pos.Byte + n
	if end > len(s.src) {
		end = len(s.src)
	}
	for s.pos.Byte < end {
		r, size := utf8.DecodeRune(s.src[s.pos.Byte:])
		if r == '\n' {
			s.pos.Line++
			s.pos.Column = 1
		} else {
			s.pos.Column++
		}
		s.pos.Byte += size
	}
}

func (s *Scanner) emit(typ TokenType, start Pos) {
	s.tokens = append(s.tokens, &Token{
		Type:  typ,
		Bytes: s.src[start.Byte:s.pos.Byte],
		Range: Range{Filename: s.filename, Start: start, End: s.pos},
	})
}

func (s *Scanner) run() {
	for !s.eof() {
		switch s.frame().mode {
		case modeNormal:
			s.scanNormal()
		case modeTemplate:
			s.scanTemplate()
		case modeHeredoc:
			s.scanHeredoc()
		}
	}
	s.emit(TokenEOF, s.pos)
}

func isIdentStart(r rune) bool {
	return r == '_' || unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_ID_Start, r)
}

func isIdentContinue(r rune) bool {
	return isIdentStart(r) || r == '-' || unicode.IsDigit(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Mc, r) || unicode.Is(unicode.Pc, r) || unicode.Is(unicode.Other_ID_Continue, r)
}

func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func (s *Scanner) scanNormal() {
	start := s.pos
	c := s.peek()
	switch {
	case c == ' ' || c == '\t' || c == '\r' && s.peekAt(1) != '\n':
		s.advance(1)
		return
	case c == '\r' && s.peekAt(1) == '\n':
		s.advance(2)
		s.emit(TokenNewline, start)
		return
	case c == '\n':
		s.advance(1)
		s.emit(TokenNewline, start)
		return
	case c == '#' || s.hasPrefix("//"):
