					s.advance(2)
					s.emit(TokenTemplateSeqEnd, start)
					s.pop()
					return
				}
			}
			s.advance(len(o.lit))
			s.emit(o.typ, start)
			return
		}
	}
	s.advance(size)
	s.emit(TokenInvalid, start)
}

func (s *Scanner) scanNumber() {
	start := s.pos
	for !s.eof() && isDigit(s.peek()) {
		s.advance(1)
	}
