{"command":"cat > /workspace/internal/hcl/format.go <<'EOF'
package hcl

import (
	"bytes"
	"unicode/utf8"
)

// Format returns a canonically formatted copy of the given source. The
// formatting only adjusts whitespace between tokens.
func Format(src []byte) []byte {
	tokens := Lex(src, "")
	// Compute the whitespace preceding each token.
	last := 0
	for _, tok := range tokens {
		tok.SpacesBefore = tok.Range.Start.Byte - last
		last = tok.Range.End.Byte
	}
	formatTokens(tokens)
	var buf bytes.Buffer
	for _, tok := range tokens {
		if tok.Type == TokenEOF {
			break
		}
		for i := 0; i < tok.SpacesBefore; i++ {
			buf.WriteByte(' ')
		}
		buf.Write(tok.Bytes)
	}
	return buf.Bytes()
}

type formatLine struct {
	lead    Tokens
	assign  Tokens
	comment Tokens
}

func formatTokens(tokens Tokens) {
	lines := linesForFormat(tokens)
	formatIndent(lines)
	formatSpaces(lines)
	formatCells(lines)
}

func tokenIsNewline(tok *Token) bool {
	if tok.Type == TokenNewline {
		return true
	}
	if tok.Type == TokenComment && len(tok.Bytes) > 0 && tok.Bytes[len(tok.Bytes)-1] == '\n' {
		return true
	}
	return false
}

func tokenBracketChange(tok *Token) int {
	switch tok.Type {
	case TokenOBrace, TokenOBrack, TokenOParen, TokenTemplateControl, TokenTemplateInterp:
		return 1
	case TokenCBrace, TokenCBrack, TokenCParen, TokenTemplateSeqEnd:
		return -1
	}
	return 0
}

func linesForFormat(tokens Tokens) []formatLine {
	if len(tokens) == 0 {
		return nil
	}
	lineCount := 1
	for _, tok := range tokens {
		if tokenIsNewline(tok) {
			lineCount++
		}
	}
	lines := make([]formatLine, lineCount)
	li := 0
	lineStart := 0
	for i, tok := range tokens {
		if tok.Type == TokenEOF {
			lines[li].lead = tokens[lineStart:i]
			break
		}
		if tokenIsNewline(tok) {
			lines[li].lead = tokens[lineStart : i+1]
			lineStart = i + 1
			li++
		}
	}
	if lineStart < len(tokens) && lines[li].lead == nil {
		lines[li].lead = tokens[lineStart:]
		if l := lines[li].lead; len(l) > 0 && l[len(l)-1].Type == TokenEOF {
			lines[li].lead = l[:len(l)-1]
		}
	}
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if len(line.lead) > 1 && line.lead[len(line.lead)-1].Type == TokenComment {
			line.comment = line.lead[len(line.lead)-1:]
			line.lead = line.lead[:len(line.lead)-1]
		}
		for i, tok := range line.lead {
			if i > 0 && tok.Type == TokenEqual {
				// Only move the tokens into "assign" if the RHS seems to be a
				// whole expression (balanced brackets).
				netBrackets := 0
				for _, t := range line.lead[i:] {
					netBrackets += tokenBracketChange(t)
				}
				if netBrackets == 0 {
					line.assign = line.lead[i:]
					line.lead = line.lead[:i]
				}
				break
			}
		}
	}
	return lines
}

func formatIndent(lines []formatLine) {
	indents := make([]int, 0, 10)
	inHeredoc := false
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if inHeredoc {
			for _, tok := range line.lead {
				if tok.Type == TokenCHeredoc {
					inHeredoc = false
				}
			}
			continue
		}
		if line.lead[0].Type == TokenNewline {
			line.lead[0].SpacesBefore = 0
			continue
		}
		netBrackets := 0
		for _, tok := range line.lead {
			netBrackets += tokenBracketChange(tok)
			if tok.Type == TokenOHeredoc {
				inHeredoc = true
			}
		}
		for _, tok := range line.assign {
			netBrackets += tokenBracketChange(tok)
			if tok.Type == TokenOHeredoc {
				inHeredoc = true
			}
		}
		switch {
		case netBrackets > 0:
			line.lead[0].SpacesBefore = 2 * len(indents)
			indents = append(indents, netBrackets)
		case netBrackets < 0:
			closed := -netBrackets
			for closed > 0 && len(indents) > 0 {
				switch {
				case closed > indents[len(indents)-1]:
					closed -= indents[len(indents)-1]
					indents = indents[:len(indents)-1]
				case closed < indents[len(indents)-1]:
					indents[len(indents)-1] -= closed
					closed = 0
