	case "for", "in", "if", "else", "endif", "endfor", "true", "false", "null":
		return true
	}
	return false
}

func spaceAfterToken(subject, before, after *Token) bool {
	switch {
	case after.Type == TokenNewline || after.Type == TokenNil:
		return false
	case isKeyword(subject, "if") && after.Type == TokenOParen:
		return true
	case subject.Type == TokenIdent && after.Type == TokenOParen:
		// Don't split a function name from the open paren in a call.
		return false
	case subject.Type == TokenDot || after.Type == TokenDot:
		return false
	case after.Type == TokenComma || after.Type == TokenEllipsis:
		return false
	case subject.Type == TokenComma:
		return true
	case subject.Type == TokenQuotedLit || subject.Type == TokenStringLit || subject.Type == TokenOQuote || subject.Type == TokenOHeredoc ||
		after.Type == TokenQuotedLit || after.Type == TokenStringLit || after.Type == TokenCQuote || after.Type == TokenCHeredoc:
		return false
	case subject.Type == TokenMinus:
		switch before.Type {
		case TokenNil:
			return false
		case TokenOParen, TokenOBrace, TokenOBrack, TokenEqual, TokenColon, TokenComma, TokenQuestion:
			return false
		case TokenPlus, TokenStar, TokenSlash, TokenPercent, TokenMinus:
			return false
		case TokenEqualOp, TokenNotEqual, TokenGreaterThan, TokenGreaterThanEq, TokenLessThan, TokenLessThanEq:
			return false
		case TokenAnd, TokenOr, TokenBang:
			return false
		default:
			return true
		}
	case subject.Type == TokenBang:
		return false
	case subject.Type == TokenOParen || after.Type == TokenCParen:
		return false
	case subject.Type == TokenOBrack || after.Type == TokenCBrack:
		return false
	case after.Type == TokenOBrack && (subject.Type == TokenIdent && !isAnyKeyword(subject) || subject.Type == TokenCBrack || subject.Type == TokenCParen || subject.Type == TokenCQuote):
