		return false
	case subject.Type == TokenOBrace || after.Type == TokenCBrace:
		return true
	case subject.Type == TokenTemplateInterp || subject.Type == TokenTemplateControl || after.Type == TokenTemplateSeqEnd:
		return false
	default:
		return true
	}
}

// columns returns the number of character columns the tokens occupy.
func (ts Tokens) columns() int {
	ret := 0
	for _, tok := range ts {
		ret += tok.SpacesBefore
		ret += utf8.RuneCount(tok.Bytes)
	}
	return ret
}

func formatCells(lines []formatLine) {
	chainStart := -1
	maxColumns := 0
	closeAssignChain := func(i int) {
		for _, chainLine := range lines[chainStart:i] {
			columns := chainLine.lead.columns()
			spaces := (maxColumns - columns) + 1
			chainLine.assign[0].SpacesBefore = spaces
		}
		chainStart = -1
		maxColumns = 0
	}
	for i, line := range lines {
		if line.assign == nil {
			if chainStart != -1 {
				closeAssignChain(i)
			}
		} else {
			if chainStart == -1 {
				chainStart = i
			}
			columns := line.lead.columns()
			if columns > maxColumns {
				maxColumns = columns
			}
		}
	}
	if chainStart != -1 {
		closeAssignChain(len(lines))
	}

	closeCommentChain := func(i int) {
		for _, chainLine := range lines[chainStart:i] {
			columns := chainLine.lead.columns() + chainLine.assign.columns()
			spaces := (maxColumns - columns) + 1
			chainLine.comment[0].SpacesBefore = spaces
		}
		chainStart = -1
		maxColumns = 0
	}
	for i, line := range lines {
		if line.comment == nil {
			if chainStart != -1 {
				closeCommentChain(i)
			}
		} else {
			if chainStart == -1 {
				chainStart = i
			}
			columns := line.lead.columns() + line.assign.columns()
			if columns > maxColumns {
				maxColumns = columns
			}
		}
	}
	if chainStart != -1 {
		closeCommentChain(len(lines))
	}
}
