	if tok.Type == TokenComment && len(tok.Bytes) > 0 && tok.Bytes[len(tok.Bytes)-1] == '\n' {
		return true
	}
	return false
}

func tokenBracketChange(tok *Token) int {
	switch tok.Type {
	case TokenOBrace, TokenOBrack, TokenOParen, TokenTemplateControl, TokenTemplateInterp:
		return 1
	case TokenCBrace, TokenCBrack, TokenCParen, TokenTemplateSeqEnd:
		return -1
	}
	return 0
}

func linesForFormat(tokens Tokens) []formatLine {
	if len(tokens) == 0 {
		return nil
	}
	lineCount := 1
	for _, tok := range tokens {
		if tokenIsNewline(tok) {
			lineCount++
		}
	}
	lines := make([]formatLine, lineCount)
	li := 0
	lineStart := 0
	for i, tok := range tokens {
		if tok.Type == TokenEOF {
			lines[li].lead = tokens[lineStart:i]
			break
		}
		if tokenIsNewline(tok) {
			lines[li].lead = tokens[lineStart : i+1]
			lineStart = i + 1
			li++
		}
	}
	if lineStart < len(tokens) && lines[li].lead == nil {
		lines[li].lead = tokens[lineStart:]
		if l := lines[li].lead; len(l) > 0 && l[len(l)-1].Type == TokenEOF {
			lines[li].lead = l[:len(l)-1]
		}
	}
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if len(line.lead) > 1 && line.lead[len(line.lead)-1].Type == TokenComment {
			line.comment = line.lead[len(line.lead)-1:]
			line.lead = line.lead[:len(line.lead)-1]
