package hcl

import "fmt"

// Severity of a diagnostic.
type Severity int

// Diagnostic severities.
const (
	DiagError Severity = iota
	DiagWarning
)

// Diagnostic describes a problem found while processing HCL.
type Diagnostic struct {
	Severity Severity
	Summary  string
	Detail   string
	Subject  *Range
}

// Error implements error.
func (d *Diagnostic) Error() string {
	if d.Subject == nil {
		return fmt.Sprintf("%s; %s", d.Summary, d.Detail)
	}
	return fmt.Sprintf("%s: %s; %s", d.Subject, d.Summary, d.Detail)
}

// Diagnostics is a list of diagnostics.
type Diagnostics []*Diagnostic

// Error implements error.
func (d Diagnostics) Error() string {
	switch len(d) {
	case 0:
		return "no diagnostics"
	case 1:
		return d[0].Error()
	default:
		return fmt.Sprintf("%s, and %d other diagnostic(s)", d[0].Error(), len(d)-1)
	}
}

// HasErrors reports whether the list contains an error-severity diagnostic.
func (d Diagnostics) HasErrors() bool {
	for _, x := range d {
		if x.Severity == DiagError {
			return true
		}
	}
	return false
}

// Append adds diagnostics to the list.
func (d Diagnostics) Append(more ...*Diagnostic) Diagnostics {
	return append(d, more...)
}

// Extend adds all diagnostics of other to the list.
func (d Diagnostics) Extend(other Diagnostics) Diagnostics {
	return append(d, other...)
}

// ErrOrNil returns the diagnostics as an error, or nil if there are no errors.
func (d Diagnostics) ErrOrNil() error {
	if d.HasErrors() {
		return d
	}
	return nil
}

func errDiag(summary, detail string, rng Range) *Diagnostic {
	return &Diagnostic{Severity: DiagError, Summary: summary, Detail: detail, Subject: rng.Ptr()}
}
