	Body  *Body
	Bytes []byte
	Name  string
}

// Body is the content of a file or a block.
type Body struct {
	Attributes []*Attribute
	Blocks     []*Block
	// Items preserves the source order of attributes and blocks.
	Items    []Node
	SrcRange Range
	EndRange Range
}

// Range implements Node.
func (b *Body) Range() Range { return b.SrcRange }

// Attribute returns the attribute with the given name, if any.
func (b *Body) Attribute(name string) *Attribute {
	for _, a := range b.Attributes {
		if a.Name == name {
			return a
		}
	}
	return nil
}

// BlocksOfType returns all blocks of the given type.
func (b *Body) BlocksOfType(typ string) []*Block {
	var out []*Block
	for _, blk := range b.Blocks {
		if blk.Type == typ {
			out = append(out, blk)
		}
	}
	return out
}

// Attribute is a `name = expr` definition.
type Attribute struct {
	Name        string
