{"command":"cat > /workspace/internal/hcl/value.go <<'EOF'
package hcl

import (
	"fmt"
	"math/big"
	"sort"
	"strconv"
	"strings"
)

// Kind is the dynamic kind of a Value.
type Kind int

// Value kinds.
const (
	KindNull Kind = iota
	KindBool
	KindNumber
	KindString
	KindTuple  // ordered list of values (also used for lists/sets)
	KindObject // string keyed map (also used for maps)
	KindRef    // reference to a named resource, e.g. schema.main
	KindType   // a type expression such as varchar(255)
	KindRaw    // raw expression such as sql("...")
	KindFunc   // an unapplied function reference (rare)
	KindUnknown
)

// Value is a dynamically typed HCL value.
type Value struct {
	kind Kind
	b    bool
	n    *big.Float
	s    string
	list []Value
	keys []string
	obj  map[string]Value
	ref  *Ref
	typ  *TypeVal
	// isList marks a tuple produced by a list/set constraint so that
	// type-name reporting is more accurate.
	isList bool
	// isMap marks an object produced by a map constraint.
	isMap bool
}

// Ref is a reference to another resource: $table.users.$column.id.
type Ref struct {
	Path string
}

// TypeVal is a type expression such as varchar(255) or int.
type TypeVal struct {
	Name string
	Args []Value
	// Raw holds the SQL for sql("...") expressions used as types.
	Raw string
}

// Constructors.

// NullVal is the null value.
var NullVal = Value{kind: KindNull}

// UnknownVal is an unknown value.
var UnknownVal = Value{kind: KindUnknown}

// BoolVal returns a boolean value.
func BoolVal(b bool) Value { return Value{kind: KindBool, b: b} }

// StringVal returns a string value.
func StringVal(s string) Value { return Value{kind: KindString, s: s} }

// NumberIntVal returns a number value from an integer.
func NumberIntVal(i int64) Value {
	return Value{kind: KindNumber, n: new(big.Float).SetPrec(512).SetInt64(i)}
}

// NumberFloatVal returns a number value from a float.
func NumberFloatVal(f float64) Value {
	return Value{kind: KindNumber, n: new(big.Float).SetPrec(512).SetFloat64(f)}
}

// NumberVal returns a number value from a big.Float.
func NumberVal(f *big.Float) Value { return Value{kind: KindNumber, n: f} }

// ParseNumberVal parses a numeric literal.
func ParseNumberVal(s string) (Value, error) {
	f, _, err := big.ParseFloat(s, 10, 512, big.ToNearestEven)
	if err != nil {
		return NullVal, err
	}
	return Value{kind: KindNumber, n: f}, nil
}

// TupleVal returns a tuple value.
func TupleVal(vals []Value) Value {
	if vals == nil {
		vals = []Value{}
	}
	return Value{kind: KindTuple, list: vals}
}

// ListVal returns a list value.
func ListVal(vals []Value) Value {
	v := TupleVal(vals)
	v.isList = true
	return v
}

// ObjectVal returns an object value with the given key order.
func ObjectVal(keys []string, m map[string]Value) Value {
	if m == nil {
		m = map[string]Value{}
	}
	if keys == nil {
		keys = make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
	}
	return Value{kind: KindObject, keys: keys, obj: m}
}

// MapVal returns a map value (keys sorted).
func MapVal(m map[string]Value) Value {
	v := ObjectVal(nil, m)
	v.isMap = true
	return v
}

// RefVal returns a reference value.
func RefVal(path string) Value { return Value{kind: KindRef, ref: &Ref{Path: path}} }

// TypeValue returns a type value.
func TypeValue(t *TypeVal) Value { return Value{kind: KindType, typ: t} }

// RawVal returns a raw SQL expression value.
func RawVal(s string) Value { return Value{kind: KindRaw, s: s} }

// Accessors.

// Kind returns the kind of the value.
func (v Value) Kind() Kind { return v.kind }

// IsNull reports whether the value is null.
func (v Value) IsNull() bool { return v.kind == KindNull }

// IsKnown reports whether the value is known.
func (v Value) IsKnown() bool { return v.kind != KindUnknown }

// True reports the boolean value.
func (v Value) True() bool { return v.kind == KindBool && v.b }

// AsString returns the string value.
func (v Value) AsString() string { return v.s }

// AsBigFloat returns the numeric value.
func (v Value) AsBigFloat() *big.Float {
	if v.n == nil {
		return new(big.Float)
	}
	return v.n
}

// AsInt64 returns the numeric value as an int64 and whether it is integral.
func (v Value) AsInt64() (int64, bool) {
	if v.kind != KindNumber {
		return 0, false
	}
	if !v.n.IsInt() {
		return 0, false
	}
	i, acc := v.n.Int64()
	return i, acc == big.Exact
}

// AsFloat64 returns the numeric value as a float64.
func (v Value) AsFloat64() float64 {
	f, _ := v.AsBigFloat().Float64()
	return f
}

// Elements returns the elements of a tuple/list value.
func (v Value) Elements() []Value { return v.list }

// Keys returns the ordered keys of an object value.
func (v Value) Keys() []string { return v.keys }

// Get returns the attribute of an object value.
func (v Value) Get(key string) (Value, bool) {
	if v.kind != KindObject {
		return NullVal, false
	}
	x, ok := v.obj[key]
	return x, ok
}

// Ref returns the reference of a ref value.
func (v Value) Ref() *Ref { return v.ref }

// Type returns the type of a type value.
func (v Value) Type() *TypeVal { return v.typ }

// Len returns the number of elements/attributes.
func (v Value) Len() int {
	switch v.kind {
	case KindTuple:
		return len(v.list)
	case KindObject:
		return len(v.keys)
	case KindString:
		return len([]rune(v.s))
	}
	return 0
}

// TypeName returns a human readable type name used in error messages.
func (v Value) TypeName() string {
	switch v.kind {
	case KindNull:
		return "dynamic"
	case KindBool:
		return "bool"
	case KindNumber:
		return "number"
	case KindString:
		return "string"
	case KindTuple:
		if v.isList {
			if len(v.list) > 0 {
				return "list of " + v.list[0].TypeName()
			}
			return "list of dynamic"
		}
		return "tuple"
	case KindObject:
		if v.isMap {
			if len(v.keys) > 0 {
				return "map of " + v.obj[v.keys[0]].TypeName()
			}
			return "map of dynamic"
		}
		return "object"
	case KindRef:
		return "reference"
	case KindType:
		return "type"
	case KindRaw:
		return "raw expression"
	}
	return "dynamic"
}

// NumberString formats a number the way HCL does in string conversions.
func NumberString(f *big.Float) string {
	return f.Text('f', -1)
}

// GoString renders a value for debugging.
func (v Value) GoString() string {
	switch v.kind {
	case KindNull:
		return "null"
	case KindBool:
		return strconv.FormatBool(v.b)
	case KindNumber:
		return NumberString(v.n)
	case KindString:
		return strconv.Quote(v.s)
	case KindTuple:
		parts := make([]string, len(v.list))
		for i, e := range v.list {
			parts[i] = e.GoString()
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case KindObject:
		parts := make([]string, len(v.keys))
		for i, k := range v.keys {
			parts[i] = k + " = " + v.obj[k].GoString()
		}
		return "{" + strings.Join(parts, ", ") + "}"
	case KindRef:
		return v.ref.Path
	case KindType:
		return v.typ.String()
	case KindRaw:
		return fmt.Sprintf("sql(%q)", v.s)
	}
	return "unknown"
}

// String renders a type expression.
func (t *TypeVal) String() string {
	if t.Raw != "" {
		return fmt.Sprintf("sql(%q)", t.Raw)
	}
	if len(t.Args) == 0 {
		return t.Name
	}
	parts := make([]string, len(t.Args))
	for i, a := range t.Args {
		parts[i] = a.GoString()
	}
	return t.Name + "(" + strings.Join(parts, ",") + ")"
}

// Equals reports whether two values are equal.
func (v Value) Equals(o Value) bool {
	if v.kind != o.kind {
		return false
	}
	switch v.kind {
	case KindNull, KindUnknown:
		return true
	case KindBool:
		return v.b == o.b
	case KindNumber:
		return v.n.Cmp(o.n) == 0
	case KindString, KindRaw:
		return v.s == o.s
	case KindTuple:
		if len(v.list) != len(o.list) {
			return false
		}
		for i := range v.list {
			if !v.list[i].Equals(o.list[i]) {
				return false
			}
		}
		return true
	case KindObject:
		if len(v.keys) != len(o.keys) {
			return false
		}
		for _, k := range v.keys {
			ov, ok := o.obj[k]
			if !ok || !v.obj[k].Equals(ov) {
				return false
			}
		}
		return true
	case KindRef:
		return v.ref.Path == o.ref.Path
	case KindType:
		return v.typ.String() == o.typ.String()
	}
	return false
}

// ConvertError describes a failed conversion.
type ConvertError struct{ Msg string }

func (e *ConvertError) Error() string { return e.Msg }

// TypeConstraint describes a target type for conversion.
type TypeConstraint struct {
	Kind Kind // KindString, KindNumber, KindBool, KindTuple (list), KindObject (map), KindNull=any
	Elem *TypeConstraint
	// Attrs is set for object type constraints.
	Attrs map[string]*TypeConstraint
	Set   bool
