		}
		return "list of " + t.Elem.String()
	case KindObject:
		if t.Attrs != nil {
			return "object"
		}
		return "map of " + t.Elem.String()
	}
	return "dynamic"
}

// Convert converts a value to the given type constraint.
func Convert(v Value, t *TypeConstraint) (Value, error) {
	if t == nil || t.Kind == KindNull {
