func (v Value) AsBigFloat() *big.Float {
	if v.n == nil {
		return new(big.Float)
	}
	return v.n
}

// AsInt64 returns the numeric value as an int64 and whether it is integral.
func (v Value) AsInt64() (int64, bool) {
	if v.kind != KindNumber {
		return 0, false
	}
	if !v.n.IsInt() {
		return 0, false
	}
	i, acc := v.n.Int64()
	return i, acc == big.Exact
}

// AsFloat64 returns the numeric value as a float64.
func (v Value) AsFloat64() float64 {
	f, _ := v.AsBigFloat().Float64()
	return f
}

// Elements returns the elements of a tuple/list value.
func (v Value) Elements() []Value { return v.list }

// Keys returns the ordered keys of an object value.
func (v Value) Keys() []string { return v.keys }

// Get returns the attribute of an object value.
func (v Value) Get(key string) (Value, bool) {
	if v.kind != KindObject {
