	return x, ok
}

// Ref returns the reference of a ref value.
func (v Value) Ref() *Ref { return v.ref }

// Type returns the type of a type value.
func (v Value) Type() *TypeVal { return v.typ }

// Len returns the number of elements/attributes.
func (v Value) Len() int {
	switch v.kind {
	case KindTuple:
		return len(v.list)
	case KindObject:
		return len(v.keys)
	case KindString:
		return len([]rune(v.s))
	}
	return 0
}

// TypeName returns a human readable type name used in error messages.
func (v Value) TypeName() string {
	switch v.kind {
