package hcl

// peeker provides lookahead over a token stream, skipping comments and
// optionally newlines.
type peeker struct {
	tokens          Tokens
	nextIndex       int
	includeComments bool
	includeNewlines []bool
}

func newPeeker(tokens Tokens, includeComments bool) *peeker {
	return &peeker{tokens: tokens, includeComments: includeComments, includeNewlines: []bool{true}}
}

func (p *peeker) Peek() *Token {
	ret, _ := p.nextToken()
	return ret
}

func (p *peeker) Read() *Token {
	ret, nextIdx := p.nextToken()
	p.nextIndex = nextIdx
	return ret
}

func (p *peeker) NextRange() Range { return p.Peek().Range }

func (p *peeker) PrevRange() Range {
	if p.nextIndex == 0 {
		return p.NextRange()
	}
	return p.tokens[p.nextIndex-1].Range
}

func (p *peeker) nextToken() (*Token, int) {
	for i := p.nextIndex; i < len(p.tokens); i++ {
		tok := p.tokens[i]
		switch tok.Type {
		case TokenComment:
			if !p.includeComments {
				// Single-line comment tokens include their terminating newline,
				// which must be treated as a newline token by the parser.
				if p.includeNewlines[len(p.includeNewlines)-1] && len(tok.Bytes) > 0 && tok.Bytes[len(tok.Bytes)-1] == '\n' {
					fakeNewline := &Token{
						Type:  TokenNewline,
						Bytes: tok.Bytes[len(tok.Bytes)-1:],
						Range: Range{
							Filename: tok.Range.Filename,
							Start: Pos{
								Line:   tok.Range.End.Line - 1,
								Column: tok.Range.End.Column,
								Byte:   tok.Range.End.Byte - 1,
							},
							End: tok.Range.End,
						},
					}
					return fakeNewline, i + 1
				}
				continue
			}
		case TokenNewline:
			if !p.includeNewlines[len(p.includeNewlines)-1] {
				continue
			}
		}
		return tok, i + 1
	}
	// EOF
	return p.tokens[len(p.tokens)-1], len(p.tokens)
}

func (p *peeker) PushIncludeNewlines(include bool) {
	p.includeNewlines = append(p.includeNewlines, include)
}

func (p *peeker) PopIncludeNewlines() bool {
	stack := p.includeNewlines
	remain, ret := stack[:len(stack)-1], stack[len(stack)-1]
	p.includeNewlines = remain
	return ret
}
EOF
