		p.Read()
	} else {
		if !p.recovery {
			diags = append(diags, errDiag("Missing newline after block definition", "A block definition must end with a newline.", eol.Range))
		}
		p.recoverAfterBodyItem()
	}
	if body == nil {
		body = &Body{SrcRange: RangeBetween(oBrace.Range, cBraceRange), EndRange: cBraceRange}
	}
	return &Block{
		Type:            blockType,
		Labels:          labels,
		Body:            body,
		TypeRange:       ident.Range,
		LabelRanges:     labelRanges,
		OpenBraceRange:  oBrace.Range,
		CloseBraceRange: cBraceRange,
	}, diags
}

// ParseExpression parses a full expression.
func (p *parser) ParseExpression() (Expression, Diagnostics) {
	return p.parseTernaryConditional()
}

func (p *parser) parseTernaryConditional() (Expression, Diagnostics) {
	var diags Diagnostics
	startRange := p.NextRange()
	var condExpr, trueExpr, falseExpr Expression

	condExpr, condDiags := p.parseBinaryOps(binaryOps)
	diags = append(diags, condDiags...)
	if p.recovery && condDiags.HasErrors() {
		return condExpr, diags
	}
	questionMark := p.Peek()
	if questionMark.Type != TokenQuestion {
		return condExpr, diags
	}
	p.Read()
	trueExpr, trueDiags := p.ParseExpression()
	diags = append(diags, trueDiags...)
	if p.recovery && trueDiags.HasErrors() {
		return condExpr, diags
	}
	colon := p.Peek()
	if colon.Type != TokenColon {
		diags = append(diags, errDiag("Missing false expression in conditional", "The conditional operator (...?...:...) requires a false expression, delimited by a colon.", colon.Range))
		return condExpr, diags
	}
	p.Read()
	falseExpr, falseDiags := p.ParseExpression()
	diags = append(diags, falseDiags...)
	if p.recovery && falseDiags.HasErrors() {
		return condExpr, diags
	}
	return &ConditionalExpr{
		Condition:   condExpr,
		TrueResult:  trueExpr,
		FalseResult: falseExpr,
		SrcRange:    RangeBetween(startRange, falseExpr.Range()),
	}, diags
}

var binaryOps = []map[TokenType]bool{
	{TokenOr: true},
	{TokenAnd: true},
	{TokenEqualOp: true, TokenNotEqual: true},
	{TokenGreaterThan: true, TokenGreaterThanEq: true, TokenLessThan: true, TokenLessThanEq: true},
	{TokenPlus: true, TokenMinus: true},
	{TokenStar: true, TokenSlash: true, TokenPercent: true},
}

func (p *parser) parseBinaryOps(ops []map[TokenType]bool) (Expression, Diagnostics) {
	if len(ops) == 0 {
		return p.parseExpressionWithTraversals()
	}
	thisLevel := ops[0]
	remaining := ops[1:]
	var lhs, rhs Expression
	var diags Diagnostics
	lhs, lhsDiags := p.parseBinaryOps(remaining)
	diags = append(diags, lhsDiags...)
	if p.recovery && lhsDiags.HasErrors() {
		return lhs, diags
	}
	next := p.Peek()
	if !thisLevel[next.Type] {
		return lhs, diags
	}
	op := next.Type
	p.Read()
	rhs, rhsDiags := p.parseBinaryOps(ops)
	diags = append(diags, rhsDiags...)
	if p.recovery && rhsDiags.HasErrors() {
		return lhs, diags
	}
	return &BinaryOpExpr{
		LHS:      lhs,
		Op:       op,
		RHS:      rhs,
		SrcRange: RangeBetween(lhs.Range(), rhs.Range()),
	}, diags
}

func (p *parser) parseExpressionWithTraversals() (Expression, Diagnostics) {
	term, diags := p.parseExpressionTerm()
	ret, moreDiags := p.parseExpressionTraversals(term)
	diags = append(diags, moreDiags...)
	return ret, diags
}

func makeRelativeTraversal(expr Expression, next Traverser, rng Range) Expression {
	switch texpr := expr.(type) {
	case *ScopeTraversalExpr:
		texpr.Traversal = append(texpr.Traversal, next)
		texpr.SrcRange = RangeBetween(texpr.SrcRange, rng)
		return texpr
	case *RelativeTraversalExpr:
		texpr.Traversal = append(texpr.Traversal, next)
		texpr.SrcRange = RangeBetween(texpr.SrcRange, rng)
		return texpr
	default:
		return &RelativeTraversalExpr{
			Source:    expr,
			Traversal: Traversal{next},
			SrcRange:  RangeBetween(expr.Range(), rng),
		}
	}
}

func (p *parser) parseExpressionTraversals(from Expression) (Expression, Diagnostics) {
