				rng := RangeBetween(open.Range, close.Range)
				if lit, ok := keyExpr.(*LiteralValueExpr); ok {
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: lit.Val, SrcRange: rng}, rng)
				} else if tmpl, ok := keyExpr.(*TemplateExpr); ok && tmpl.IsStringLiteral() {
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: tmpl.Parts[0].(*LiteralValueExpr).Val, SrcRange: rng}, rng)
				} else {
					ret = &IndexExpr{
						Collection:   ret,
						Key:          keyExpr,
						SrcRange:     RangeBetween(from.Range(), rng),
						OpenRange:    open.Range,
						BracketRange: rng,
					}
				}
			}
		default:
			break Traversal
		}
	}
	return ret, diags
}

func (p *parser) parseExpressionTerm() (Expression, Diagnostics) {
	start := p.Peek()
	switch start.Type {
	case TokenOParen:
		oParen := p.Read()
		p.PushIncludeNewlines(false)
		expr, diags := p.ParseExpression()
		close := p.Peek()
		if close.Type != TokenCParen {
			if !p.recovery {
				diags = append(diags, errDiag("Unbalanced parentheses", "Expected a closing parenthesis to terminate the expression.", close.Range))
			}
			p.setRecovery()
		}
		cParen := p.Read()
		p.PopIncludeNewlines()
		return &ParenthesesExpr{Expression: expr, SrcRange: RangeBetween(oParen.Range, cParen.Range)}, diags
	case TokenOBrace:
		return p.parseObjectCons()
	case TokenOBrack:
		return p.parseTupleCons()
	case TokenNumberLit:
		tok := p.Read()
		numVal, diags := numberLitValue(tok)
		return &LiteralValueExpr{Val: numVal, SrcRange: tok.Range}, diags
	case TokenIdent:
		tok := p.Read()
		if p.Peek().Type == TokenOParen || p.Peek().Type == TokenDoubleColon {
			return p.finishParsingFunctionCall(tok)
		}
		name := string(tok.Bytes)
		switch name {
		case "true":
			return &LiteralValueExpr{Val: BoolVal(true), SrcRange: tok.Range}, nil
		case "false":
			return &LiteralValueExpr{Val: BoolVal(false), SrcRange: tok.Range}, nil
		case "null":
			return &LiteralValueExpr{Val: NullVal, SrcRange: tok.Range}, nil
		default:
			return &ScopeTraversalExpr{
				Traversal: Traversal{TraverseRoot{Name: name, SrcRange: tok.Range}},
				SrcRange:  tok.Range,
			}, nil
		}
	case TokenOQuote, TokenOHeredoc:
		open := p.Read()
		closer := p.oppositeBracket(open.Type)
		exprs, passthru, _, diags := p.parseTemplateInner(closer, tokenOpensFlushHeredoc(open))
		closeRange := p.PrevRange()
		if passthru {
			return &TemplateWrapExpr{Wrapped: exprs[0], SrcRange: RangeBetween(open.Range, closeRange)}, diags
		}
		return &TemplateExpr{Parts: exprs, SrcRange: RangeBetween(open.Range, closeRange)}, diags
	case TokenMinus:
		tok := p.Read()
		operand, diags := p.parseExpressionWithTraversals()
		return &UnaryOpExpr{Op: TokenMinus, Val: operand, SrcRange: RangeBetween(tok.Range, operand.Range()), SymbolRange: tok.Range}, diags
	case TokenBang:
		tok := p.Read()
		operand, diags := p.parseExpressionWithTraversals()
		return &UnaryOpExpr{Op: TokenBang, Val: operand, SrcRange: RangeBetween(tok.Range, operand.Range()), SymbolRange: tok.Range}, diags
	default:
		var diags Diagnostics
		if !p.recovery {
			diags = append(diags, errDiag("Invalid expression", "Expected the start of an expression, but found an invalid expression token.", start.Range))
		}
		p.setRecovery()
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: start.Range}, diags
	}
}

func numberLitValue(tok *Token) (Value, Diagnostics) {
	v, err := ParseNumberVal(string(tok.Bytes))
	if err != nil {
		return UnknownVal, Diagnostics{errDiag("Invalid number literal", "Failed to recognize the value of this number literal.", tok.Range)}
	}
	return v, nil
}

func (p *parser) finishParsingFunctionCall(tok *Token) (Expression, Diagnostics) {
	var diags Diagnostics
	name := string(tok.Bytes)
	nameRange := tok.Range
	for p.Peek().Type == TokenDoubleColon {
		p.Read()
		next := p.Read()
		if next.Type != TokenIdent {
			if !p.recovery {
				diags = append(diags, errDiag("Missing function name", "Function scope resolution symbol :: must be followed by a function name in this scope.", next.Range))
			}
			p.setRecovery()
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: next.Range}, diags
		}
		name += "::" + string(next.Bytes)
		nameRange = RangeBetween(nameRange, next.Range)
	}
	openTok := p.Read()
	if openTok.Type != TokenOParen {
		diags = append(diags, errDiag("Missing open parenthesis", "Function selector must be followed by an open parenthesis to begin the function call.", openTok.Range))
		p.setRecovery()
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: openTok.Range}, diags
	}
	var args []Expression
	var expandFinal bool
	var closeTok *Token
	p.PushIncludeNewlines(false)
Token:
	for {
		tok := p.Peek()
		if tok.Type == TokenCParen {
			closeTok = p.Read()
			break Token
		}
		arg, argDiags := p.ParseExpression()
		args = append(args, arg)
		diags = append(diags, argDiags...)
		if p.recovery && argDiags.HasErrors() {
			closeTok = p.recover(TokenCParen)
			break Token
		}
		sep := p.Read()
		if sep.Type == TokenCParen {
			closeTok = sep
			break Token
		}
		if sep.Type == TokenEllipsis {
			expandFinal = true
			if p.Peek().Type != TokenCParen {
				if !p.recovery {
					diags = append(diags, errDiag("Missing closing parenthesis", "An expanded function argument (with ...) must be immediately followed by closing parentheses.", sep.Range))
				}
				closeTok = p.recover(TokenCParen)
			} else {
				closeTok = p.Read()
			}
			break Token
		}
		if sep.Type != TokenComma {
			switch sep.Type {
			case TokenEOF:
				diags = append(diags, errDiag("Unterminated function call", "There is no closing parenthesis for this function call before the end of the file. This may be caused by incorrect parenthesis nesting elsewhere in this file.", openTok.Range))
			default:
				diags = append(diags, errDiag("Missing argument separator", "A comma is required to separate each function argument from the next.", sep.Range))
			}
			closeTok = p.recover(TokenCParen)
			break Token
		}
		if p.Peek().Type == TokenCParen {
			// A trailing comma is allowed.
			closeTok = p.Read()
			break Token
		}
	}
	p.PopIncludeNewlines()
	return &FunctionCallExpr{
		Name:            name,
		Args:            args,
		ExpandFinal:     expandFinal,
		NameRange:       nameRange,
		OpenParenRange:  openTok.Range,
		CloseParenRange: closeTok.Range,
	}, diags
}

func (p *parser) parseTupleCons() (Expression, Diagnostics) {
	open := p.Read()
	p.PushIncludeNewlines(false)
	defer p.PopIncludeNewlines()
	if forKeyword.TokenMatches(p.Peek()) {
		return p.finishParsingForExpr(open)
	}
	var close *Token
	var diags Diagnostics
	var exprs []Expression
	for {
		next := p.Peek()
		if next.Type == TokenCBrack {
			close = p.Read()
			break
		}
		if next.Type == TokenEOF {
			if !p.recovery {
				diags = append(diags, errDiag("Unterminated tuple constructor expression", "There is no corresponding closing bracket before the end of the file. This may be caused by incorrect bracket nesting elsewhere in this file.", open.Range))
			}
			close = p.recover(TokenCBrack)
			break
		}
		expr, exprDiags := p.ParseExpression()
		exprs = append(exprs, expr)
		diags = append(diags, exprDiags...)
		if p.recovery && exprDiags.HasErrors() {
			close = p.recover(TokenCBrack)
			break
		}
		next = p.Peek()
		if next.Type == TokenCBrack {
			close = p.Read()
			break
		}
		if next.Type != TokenComma {
			if !p.recovery {
				diags = append(diags, errDiag("Missing item separator", "Expected a comma to mark the beginning of the next item.", next.Range))
			}
			close = p.recover(TokenCBrack)
			break
		}
		p.Read()
	}
	return &TupleConsExpr{Exprs: exprs, SrcRange: RangeBetween(open.Range, close.Range), OpenRange: open.Range}, diags
}

func (p *parser) parseObjectCons() (Expression, Diagnostics) {
	open := p.Read()
	p.PushIncludeNewlines(true)
	defer p.PopIncludeNewlines()
	if forKeyword.TokenMatches(p.Peek()) {
		p.PushIncludeNewlines(false)
		defer p.PopIncludeNewlines()
		return p.finishParsingForExpr(open)
	}
	var close *Token
	var diags Diagnostics
	var items []ObjectConsItem
	for {
		next := p.Peek()
		if next.Type == TokenNewline {
			p.Read()
			continue
		}
		if next.Type == TokenCBrace {
			close = p.Read()
			break
		}
		if next.Type == TokenEOF {
			if !p.recovery {
				diags = append(diags, errDiag("Unterminated object constructor expression", "There is no corresponding closing brace before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", open.Range))
			}
			close = p.recover(TokenCBrace)
			break
		}
		var key Expression
		var keyDiags Diagnostics
		key, keyDiags = p.ParseExpression()
		diags = append(diags, keyDiags...)
		if p.recovery && keyDiags.HasErrors() {
			close = p.recover(TokenCBrace)
			break
		}
		key = &ObjectConsKeyExpr{Wrapped: key}
		next = p.Peek()
		if next.Type != TokenEqual && next.Type != TokenColon {
			if !p.recovery {
				switch next.Type {
				case TokenNewline, TokenComma:
					diags = append(diags, errDiag("Missing attribute value", "Expected an attribute value, introduced by an equals sign (\"=\").", next.Range))
				case TokenIdent:
					diags = append(diags, errDiag("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value. If you intended to given an attribute name containing periods or spaces, write the name in quotes to create a string literal.", next.Range))
				case TokenOQuote, TokenOBrack, TokenNumberLit:
					diags = append(diags, errDiag("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.", next.Range))
				default:
					diags = append(diags, errDiag("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.", next.Range))
				}
			}
			close = p.recover(TokenCBrace)
			break
		}
		p.Read()
		value, valueDiags := p.ParseExpression()
		diags = append(diags, valueDiags...)
		if p.recovery && valueDiags.HasErrors() {
			close = p.recover(TokenCBrace)
			break
		}
		items = append(items, ObjectConsItem{KeyExpr: key, ValueExpr: value})
		next = p.Peek()
		if next.Type == TokenCBrace {
			close = p.Read()
			break
		}
		if next.Type != TokenComma && next.Type != TokenNewline {
			if !p.recovery {
				switch next.Type {
				case TokenEOF:
					diags = append(diags, errDiag("Unterminated object constructor expression", "There is no corresponding closing brace before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", open.Range))
				default:
					diags = append(diags, errDiag("Missing attribute separator", "Expected a newline or comma to mark the beginning of the next attribute.", next.Range))
				}
			}
			close = p.recover(TokenCBrace)
			break
		}
		p.Read()
	}
	return &ObjectConsExpr{Items: items, SrcRange: RangeBetween(open.Range, close.Range), OpenRange: open.Range}, diags
}

// keyword helpers.
type keyword string

const (
	forKeyword keyword = "for"
	inKeyword  keyword = "in"
	ifKeyword  keyword = "if"
	elseKeyword keyword = "else"
	endifKeyword keyword = "endif"
	endforKeyword keyword = "endfor"
)

func (k keyword) TokenMatches(tok *Token) bool {
	return tok.Type == TokenIdent && string(tok.Bytes) == string(k)
}

func (p *parser) finishParsingForExpr(open *Token) (Expression, Diagnostics) {
	p.PushIncludeNewlines(false)
	defer p.PopIncludeNewlines()
	introducer := p.Read()
	if !forKeyword.TokenMatches(introducer) {
		return nil, Diagnostics{errDiag("Invalid for expression", "Expected the \"for\" keyword.", introducer.Range)}
	}
	var diags Diagnostics
	var keyName, valName string
	if p.Peek().Type != TokenIdent {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires variable name after 'for'.", p.Peek().Range))
		}
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	valName = string(p.Read().Bytes)
	if p.Peek().Type == TokenComma {
		p.Read()
		if p.Peek().Type != TokenIdent {
			if !p.recovery {
				diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires value variable name after comma.", p.Peek().Range))
			}
			close := p.recover(p.oppositeBracket(open.Type))
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
		keyName = valName
		valName = string(p.Read().Bytes)
	}
	if !inKeyword.TokenMatches(p.Peek()) {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires the 'in' keyword after its name declarations.", p.Peek().Range))
		}
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	p.Read()
	collExpr, collDiags := p.ParseExpression()
	diags = append(diags, collDiags...)
	if p.recovery && collDiags.HasErrors() {
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	if p.Peek().Type != TokenColon {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires a colon after the collection expression.", p.Peek().Range))
		}
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	p.Read()
	var keyExpr, valExpr Expression
	var group bool
	first, firstDiags := p.ParseExpression()
	diags = append(diags, firstDiags...)
	if p.recovery && firstDiags.HasErrors() {
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	if open.Type == TokenOBrace {
		if p.Peek().Type != TokenFatArrow {
			if !p.recovery {
				diags = append(diags, errDiag("Invalid 'for' expression", "For expression in braces requires a key expression, followed by \"=>\", and then a value expression.", p.Peek().Range))
			}
			close := p.recover(TokenCBrace)
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
		p.Read()
		keyExpr = first
		var valDiags Diagnostics
		valExpr, valDiags = p.ParseExpression()
		diags = append(diags, valDiags...)
		if p.recovery && valDiags.HasErrors() {
			close := p.recover(TokenCBrace)
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
		if p.Peek().Type == TokenEllipsis {
			p.Read()
			group = true
		}
	} else {
		valExpr = first
	}
	var condExpr Expression
	if ifKeyword.TokenMatches(p.Peek()) {
		p.Read()
		var condDiags Diagnostics
		condExpr, condDiags = p.ParseExpression()
		diags = append(diags, condDiags...)
		if p.recovery && condDiags.HasErrors() {
			close := p.recover(p.oppositeBracket(open.Type))
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
	}
	var close *Token
	if p.Peek().Type == p.oppositeBracket(open.Type) {
		close = p.Read()
	} else {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "Extra characters after the end of the 'for' expression.", p.Peek().Range))
		}
		close = p.recover(p.oppositeBracket(open.Type))
	}
	return &ForExpr{
		KeyVar:    keyName,
		ValVar:    valName,
		CollExpr:  collExpr,
		KeyExpr:   keyExpr,
		ValExpr:   valExpr,
		CondExpr:  condExpr,
		Group:     group,
		SrcRange:  RangeBetween(open.Range, close.Range),
		OpenRange: open.Range,
	}, diags
}

// parseQuotedStringLiteral parses a quoted string that must not contain
// interpolations (used for block labels).
func (p *parser) parseQuotedStringLiteral() (string, Range, Diagnostics) {
	oQuote := p.Read()
	if oQuote.Type != TokenOQuote {
		return "", oQuote.Range, Diagnostics{errDiag("Invalid string literal", "A quoted string is required here.", oQuote.Range)}
	}
	var diags Diagnostics
	var ret strings.Builder
	var endRange Range
Token:
	for {
		tok := p.Read()
		switch tok.Type {
		case TokenCQuote:
			endRange = tok.Range
			break Token
		case TokenQuotedLit:
			s, sDiags := ParseStringLiteralToken(tok)
			diags = append(diags, sDiags...)
			ret.WriteString(s)
		case TokenTemplateControl, TokenTemplateInterp:
			which := "$"
			if tok.Type == TokenTemplateControl {
				which = "%"
			}
			diags = append(diags, errDiag("Invalid string literal", fmt.Sprintf("Template sequences are not allowed in this string. To include a literal %q, double it (as \"%s%s\") to escape it.", which, which, which), tok.Range))
			p.recover(TokenTemplateSeqEnd)
		case TokenEOF:
			diags = append(diags, errDiag("Unterminated string literal", "Unable to find the closing quote mark before the end of the file.", tok.Range))
			endRange = tok.Range
			break Token
		case TokenQuotedNewline:
			diags = append(diags, errDiag("Invalid multi-line string", "Quoted strings may not be split over multiple lines. To produce a multi-line string, either use the \\n escape to represent a newline character or use the \"heredoc\" multi-line template syntax.", tok.Range))
		default:
			diags = append(diags, errDiag("Invalid string literal", "This item is not valid in a string literal.", tok.Range))
			p.recover(TokenCQuote)
			endRange = tok.Range
			break Token
		}
	}
	return ret.String(), RangeBetween(oQuote.Range, endRange), diags
}

// ParseStringLiteralToken decodes the escape sequences of a string literal token.
func ParseStringLiteralToken(tok *Token) (string, Diagnostics) {
	var quoted bool
	switch tok.Type {
	case TokenQuotedLit:
		quoted = true
	case TokenStringLit:
		quoted = false
	default:
		return "", Diagnostics{errDiag("Invalid string literal", "A string literal token is required here.", tok.Range)}
	}
	var diags Diagnostics
	ret := make([]byte, 0, len(tok.Bytes))
	src := tok.Bytes
	for i := 0; i < len(src); {
		c := src[i]
		switch {
		case c == '\\' && quoted:
			if i+1 >= len(src) {
				diags = append(diags, errDiag("Invalid escape sequence", "Backslash must be followed by an escape sequence selector character.", tok.Range))
				i++
				continue
			}
			e := src[i+1]
			switch e {
			case 'n':
				ret = append(ret, '\n')
				i += 2
			case 'r':
				ret = append(ret, '\r')
				i += 2
			case 't':
				ret = append(ret, '\t')
				i += 2
			case '"':
				ret = append(ret, '"')
				i += 2
			case '\\':
				ret = append(ret, '\\')
				i += 2
			case 'u', 'U':
				n := 4
				if e == 'U' {
					n = 8
				}
				if i+2+n > len(src) {
					diags = append(diags, errDiag("Invalid escape sequence", fmt.Sprintf("The %q escape sequence must be followed by %d hexadecimal digits.", string(e), n), tok.Range))
					i = len(src)
					continue
				}
				var r rune
				ok := true
				for _, h := range src[i+2 : i+2+n] {
					var d byte
					switch {
					case h >= '0' && h <= '9':
						d = h - '0'
					case h >= 'a' && h <= 'f':
						d = h - 'a' + 10
					case h >= 'A' && h <= 'F':
						d = h - 'A' + 10
					default:
						ok = false
					}
					r = r*16 + rune(d)
				}
				if !ok {
					diags = append(diags, errDiag("Invalid escape sequence", fmt.Sprintf("The %q escape sequence must be followed by %d hexadecimal digits.", string(e), n), tok.Range))
				}
				var buf [utf8.UTFMax]byte
				l := utf8.EncodeRune(buf[:], r)
				ret = append(ret, buf[:l]...)
				i += 2 + n
			default:
				diags = append(diags, errDiag("Invalid escape sequence", fmt.Sprintf("The symbol %q is not a valid escape sequence selector.", string(e)), tok.Range))
				ret = append(ret, e)
				i += 2
			}
		case c == '$' && i+2 < len(src) && src[i+1] == '$' && src[i+2] == '{':
			ret = append(ret, '$', '{')
			i += 3
		case c == '%' && i+2 < len(src) && src[i+1] == '%' && src[i+2] == '{':
			ret = append(ret, '%', '{')
			i += 3
		default:
			ret = append(ret, c)
			i++
		}
	}
	return string(ret), diags
}

func tokenOpensFlushHeredoc(tok *Token) bool {
	if tok.Type != TokenOHeredoc {
		return false
	}
	return len(tok.Bytes) > 2 && tok.Bytes[2] == '-'
}
EOF
echo ok"}

actions.command:
cat > /workspace/internal/hcl/parser.go <<'EOF'
package hcl

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

type parser struct {
	*peeker
	recovery bool
}

// ParseConfig parses the given HCL source into a File.
func ParseConfig(src []byte, filename string) (*File, Diagnostics) {
	tokens := Lex(src, filename)
	diags := checkInvalidTokens(tokens)
	p := &parser{peeker: newPeeker(tokens, false)}
	body, bodyDiags := p.ParseBody(TokenEOF)
	diags = append(diags, bodyDiags...)
	return &File{Body: body, Bytes: src, Name: filename}, diags
}

// ParseExpressionString parses a standalone expression.
func ParseExpressionString(src []byte, filename string) (Expression, Diagnostics) {
	tokens := Lex(src, filename)
	diags := checkInvalidTokens(tokens)
	p := &parser{peeker: newPeeker(tokens, false)}
	expr, exprDiags := p.ParseExpression()
	diags = append(diags, exprDiags...)
	next := p.Peek()
	if next.Type != TokenEOF && !p.recovery {
		diags = append(diags, errDiag("Extra characters after expression", "An expression was successfully parsed, but extra characters were found after it.", next.Range))
	}
	return expr, diags
}

func checkInvalidTokens(tokens Tokens) Diagnostics {
	var diags Diagnostics
	toldBitwise, toldExponent, toldBacktick, toldApostrophe, toldSemicolon, toldTabs, toldBadUTF8 := 0, 0, 0, 0, 0, 0, 0
	for _, tok := range tokens {
		tokRange := func() *Range { r := tok.Range; return &r }
		switch tok.Type {
		case TokenBitwiseAnd, TokenBitwiseOr, TokenBitwiseXor, TokenBitwiseNot:
			if toldBitwise < 4 {
				var suggestion string
				switch tok.Type {
				case TokenBitwiseAnd:
					suggestion = " Did you mean boolean AND (\"&&\")?"
				case TokenBitwiseOr:
					suggestion = " Did you mean boolean OR (\"||\")?"
				case TokenBitwiseNot:
					suggestion = " Did you mean boolean NOT (\"!\")?"
				}
				diags = append(diags, errDiag("Unsupported operator", fmt.Sprintf("Bitwise operators are not supported.%s", suggestion), *tokRange()))
				toldBitwise++
			}
		case TokenStarStar:
			if toldExponent < 1 {
				diags = append(diags, errDiag("Unsupported operator", "\"**\" is not a supported operator. Exponentiation is not supported as an operator.", *tokRange()))
				toldExponent++
			}
		case TokenBacktick:
			if toldBacktick <= 2 {
				diags = append(diags, errDiag("Invalid character", "The \"`\" character is not valid. To create a multi-line string, use the \"heredoc\" syntax, like \"<<EOT\".", *tokRange()))
				toldBacktick++
			}
		case TokenApostrophe:
			if toldApostrophe <= 2 {
				diags = append(diags, errDiag("Invalid character", "Single quotes are not valid. Use double quotes (\") to enclose strings.", *tokRange()))
				toldApostrophe++
			}
		case TokenSemicolon:
			if toldSemicolon < 1 {
				diags = append(diags, errDiag("Invalid character", "The \";\" character is not valid. Use newlines to separate arguments and blocks, and commas to separate items in collection values.", *tokRange()))
				toldSemicolon++
			}
		case TokenTabs:
			if toldTabs < 1 {
				diags = append(diags, errDiag("Invalid character", "Tab characters may not be used. The recommended indentation style is two spaces per indent.", *tokRange()))
				toldTabs++
			}
		case TokenBadUTF8:
			if toldBadUTF8 < 1 {
				diags = append(diags, errDiag("Invalid character encoding", "All input files must be UTF-8 encoded. Ensure that UTF-8 encoding is selected in your editor.", *tokRange()))
				toldBadUTF8++
			}
		case TokenQuotedNewline:
			// Reported by the template parser.
		case TokenInvalid:
			diags = append(diags, errDiag("Invalid character", "This character is not used within the language.", *tokRange()))
		}
	}
	return diags
}

func (p *parser) setRecovery() { p.recovery = true }

func (p *parser) oppositeBracket(ty TokenType) TokenType {
	switch ty {
	case TokenOBrace:
		return TokenCBrace
	case TokenOBrack:
		return TokenCBrack
	case TokenOParen:
		return TokenCParen
	case TokenOQuote:
		return TokenCQuote
	case TokenOHeredoc:
		return TokenCHeredoc
	case TokenCBrace:
		return TokenOBrace
	case TokenCBrack:
		return TokenOBrack
	case TokenCParen:
		return TokenOParen
	case TokenCQuote:
		return TokenOQuote
	case TokenCHeredoc:
		return TokenOHeredoc
	case TokenTemplateControl, TokenTemplateInterp:
		return TokenTemplateSeqEnd
	case TokenTemplateSeqEnd:
		return TokenTemplateInterp
	}
	return TokenNil
}

func (p *parser) recover(end TokenType) *Token {
	start := p.oppositeBracket(end)
	p.recovery = true
	nest := 0
	for {
		tok := p.Read()
		ty := tok.Type
		if end == TokenTemplateSeqEnd && ty == TokenTemplateControl {
			ty = TokenTemplateInterp
		}
		switch ty {
		case start:
			nest++
		case end:
			if nest < 1 {
				return tok
			}
			nest--
		case TokenEOF:
			return tok
		}
	}
}

func (p *parser) recoverAfterBodyItem() {
	p.recovery = true
	var open []TokenType
Token:
	for {
		tok := p.Read()
		switch tok.Type {
		case TokenNewline:
			if len(open) == 0 {
				break Token
			}
		case TokenEOF:
			break Token
		case TokenOBrace, TokenOBrack, TokenOParen, TokenOQuote, TokenOHeredoc, TokenTemplateInterp, TokenTemplateControl:
			open = append(open, tok.Type)
		case TokenCBrace, TokenCBrack, TokenCParen, TokenCQuote, TokenCHeredoc:
			opener := p.oppositeBracket(tok.Type)
			for len(open) > 0 && open[len(open)-1] != opener {
				open = open[:len(open)-1]
			}
			if len(open) > 0 {
				open = open[:len(open)-1]
			}
		case TokenTemplateSeqEnd:
			for len(open) > 0 && open[len(open)-1] != TokenTemplateInterp && open[len(open)-1] != TokenTemplateControl {
				open = open[:len(open)-1]
			}
			if len(open) > 0 {
				open = open[:len(open)-1]
			}
		}
	}
}

// ParseBody parses body content until the given end token.
func (p *parser) ParseBody(end TokenType) (*Body, Diagnostics) {
	body := &Body{}
	var diags Diagnostics
	startRange := p.PrevRange()
	var endRange Range
	seen := map[string]*Attribute{}
Token:
	for {
		next := p.Peek()
		if next.Type == end {
			endRange = p.NextRange()
			p.Read()
			break Token
		}
		switch next.Type {
		case TokenNewline:
			p.Read()
			continue
		case TokenIdent:
			item, itemDiags := p.ParseBodyItem()
			diags = append(diags, itemDiags...)
			switch titem := item.(type) {
			case *Block:
				body.Blocks = append(body.Blocks, titem)
				body.Items = append(body.Items, titem)
			case *Attribute:
				if existing, ok := seen[titem.Name]; ok {
					diags = append(diags, errDiag("Attribute redefined",
						fmt.Sprintf("The argument %q was already set at %s. Each argument may be set only once.", titem.Name, existing.NameRange.String()),
						titem.NameRange))
				} else {
					seen[titem.Name] = titem
					body.Attributes = append(body.Attributes, titem)
					body.Items = append(body.Items, titem)
				}
			default:
				continue
			}
		default:
			bad := p.Read()
			if !p.recovery {
				switch bad.Type {
				case TokenOQuote:
					diags = append(diags, errDiag("Invalid argument name", "Argument names must not be quoted.", bad.Range))
				case TokenEOF:
					switch end {
					case TokenCBrace:
						diags = append(diags, errDiag("Unclosed configuration block", "There is no closing brace for this block before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", startRange))
					default:
						diags = append(diags, errDiag("Unclosed configuration body", "Found end of file before the end of this configuration body.", startRange))
					}
				default:
					diags = append(diags, errDiag("Argument or block definition required", "An argument or block definition is required here.", bad.Range))
				}
			}
			endRange = p.PrevRange()
			p.recover(end)
			break Token
		}
	}
	body.SrcRange = RangeBetween(startRange, endRange)
	body.EndRange = Range{Filename: endRange.Filename, Start: endRange.End, End: endRange.End}
	return body, diags
}

// ParseBodyItem parses a single attribute or block.
func (p *parser) ParseBodyItem() (Node, Diagnostics) {
	ident := p.Read()
	if ident.Type != TokenIdent {
		p.recoverAfterBodyItem()
		return nil, Diagnostics{errDiag("Argument or block definition required", "An argument or block definition is required here.", ident.Range)}
	}
	next := p.Peek()
	switch next.Type {
	case TokenEqual:
		return p.finishParsingBodyAttribute(ident, false)
	case TokenOQuote, TokenOBrace, TokenIdent:
		return p.finishParsingBodyBlock(ident)
	default:
		p.recoverAfterBodyItem()
		return nil, Diagnostics{errDiag("Argument or block definition required", "An argument or block definition is required here.", ident.Range)}
	}
}

func (p *parser) finishParsingBodyAttribute(ident *Token, singleLine bool) (Node, Diagnostics) {
	eqTok := p.Read()
	var endRange Range
	expr, diags := p.ParseExpression()
	if p.recovery && diags.HasErrors() {
		endRange = p.PrevRange()
		p.recoverAfterBodyItem()
	} else {
		endRange = p.PrevRange()
		if !singleLine {
			end := p.Peek()
			if end.Type != TokenNewline && end.Type != TokenEOF {
				if !p.recovery {
					summary := "Missing newline after argument"
					detail := "An argument definition must end with a newline."
					if end.Type == TokenComma {
						summary = "Unexpected comma after argument"
						detail = "Argument definitions must be separated by newlines, not commas. " + detail
					}
					diags = append(diags, errDiag(summary, detail, end.Range))
				}
				endRange = p.PrevRange()
				p.recoverAfterBodyItem()
			} else {
				endRange = p.PrevRange()
				p.Read()
			}
		}
	}
	return &Attribute{
		Name:        string(ident.Bytes),
		Expr:        expr,
		SrcRange:    RangeBetween(ident.Range, endRange),
		NameRange:   ident.Range,
		EqualsRange: eqTok.Range,
	}, diags
}

func (p *parser) finishParsingBodyBlock(ident *Token) (Node, Diagnostics) {
	blockType := string(ident.Bytes)
	var (
		diags       Diagnostics
		labels      []string
		labelRanges []Range
		oBrace      *Token
	)
Token:
	for {
		tok := p.Peek()
		switch tok.Type {
		case TokenOBrace:
			oBrace = p.Read()
			break Token
		case TokenOQuote:
			label, labelRange, labelDiags := p.parseQuotedStringLiteral()
			diags = append(diags, labelDiags...)
			labels = append(labels, label)
			labelRanges = append(labelRanges, labelRange)
		case TokenIdent:
			tok = p.Read()
			labels = append(labels, string(tok.Bytes))
			labelRanges = append(labelRanges, tok.Range)
		default:
			switch tok.Type {
			case TokenEqual:
				diags = append(diags, errDiag("Invalid block definition", "The equals sign \"=\" indicates an argument definition, and must not be used when defining a block.", tok.Range))
			case TokenNewline:
				diags = append(diags, errDiag("Invalid block definition", "A block definition must have block content delimited by \"{\" and \"}\", starting on the same line as the block header.", tok.Range))
			default:
				if !p.recovery {
					diags = append(diags, errDiag("Invalid block definition", "Either a quoted string block label or an opening brace (\"{\") is expected here.", tok.Range))
				}
			}
			p.recoverAfterBodyItem()
			return &Block{
				Type:            blockType,
				Labels:          labels,
				Body:            &Body{SrcRange: ident.Range, EndRange: ident.Range},
				TypeRange:       ident.Range,
				LabelRanges:     labelRanges,
				OpenBraceRange:  ident.Range,
				CloseBraceRange: ident.Range,
			}, diags
		}
	}
	body, bodyDiags := p.ParseBody(TokenCBrace)
	diags = append(diags, bodyDiags...)
	cBraceRange := p.PrevRange()
	eol := p.Peek()
	if eol.Type == TokenNewline || eol.Type == TokenEOF {
		p.Read()
	} else {
		if !p.recovery {
			diags = append(diags, errDiag("Missing newline after block definition", "A block definition must end with a newline.", eol.Range))
		}
		p.recoverAfterBodyItem()
	}
	if body == nil {
		body = &Body{SrcRange: RangeBetween(oBrace.Range, cBraceRange), EndRange: cBraceRange}
	}
	return &Block{
		Type:            blockType,
		Labels:          labels,
		Body:            body,
		TypeRange:       ident.Range,
		LabelRanges:     labelRanges,
		OpenBraceRange:  oBrace.Range,
		CloseBraceRange: cBraceRange,
	}, diags
}

// ParseExpression parses a full expression.
func (p *parser) ParseExpression() (Expression, Diagnostics) {
	return p.parseTernaryConditional()
}

func (p *parser) parseTernaryConditional() (Expression, Diagnostics) {
	var diags Diagnostics
	startRange := p.NextRange()
	var condExpr, trueExpr, falseExpr Expression

	condExpr, condDiags := p.parseBinaryOps(binaryOps)
	diags = append(diags, condDiags...)
	if p.recovery && condDiags.HasErrors() {
		return condExpr, diags
	}
	questionMark := p.Peek()
	if questionMark.Type != TokenQuestion {
		return condExpr, diags
	}
	p.Read()
	trueExpr, trueDiags := p.ParseExpression()
	diags = append(diags, trueDiags...)
	if p.recovery && trueDiags.HasErrors() {
		return condExpr, diags
	}
	colon := p.Peek()
	if colon.Type != TokenColon {
		diags = append(diags, errDiag("Missing false expression in conditional", "The conditional operator (...?...:...) requires a false expression, delimited by a colon.", colon.Range))
		return condExpr, diags
	}
	p.Read()
	falseExpr, falseDiags := p.ParseExpression()
	diags = append(diags, falseDiags...)
	if p.recovery && falseDiags.HasErrors() {
		return condExpr, diags
	}
	return &ConditionalExpr{
		Condition:   condExpr,
		TrueResult:  trueExpr,
		FalseResult: falseExpr,
		SrcRange:    RangeBetween(startRange, falseExpr.Range()),
	}, diags
}

var binaryOps = []map[TokenType]bool{
	{TokenOr: true},
	{TokenAnd: true},
	{TokenEqualOp: true, TokenNotEqual: true},
	{TokenGreaterThan: true, TokenGreaterThanEq: true, TokenLessThan: true, TokenLessThanEq: true},
	{TokenPlus: true, TokenMinus: true},
	{TokenStar: true, TokenSlash: true, TokenPercent: true},
}

func (p *parser) parseBinaryOps(ops []map[TokenType]bool) (Expression, Diagnostics) {
	if len(ops) == 0 {
		return p.parseExpressionWithTraversals()
	}
	thisLevel := ops[0]
	remaining := ops[1:]
	var lhs, rhs Expression
	var diags Diagnostics
	lhs, lhsDiags := p.parseBinaryOps(remaining)
	diags = append(diags, lhsDiags...)
	if p.recovery && lhsDiags.HasErrors() {
		return lhs, diags
	}
	next := p.Peek()
	if !thisLevel[next.Type] {
		return lhs, diags
	}
	op := next.Type
	p.Read()
	rhs, rhsDiags := p.parseBinaryOps(ops)
	diags = append(diags, rhsDiags...)
	if p.recovery && rhsDiags.HasErrors() {
		return lhs, diags
	}
	return &BinaryOpExpr{
		LHS:      lhs,
		Op:       op,
		RHS:      rhs,
		SrcRange: RangeBetween(lhs.Range(), rhs.Range()),
	}, diags
}

func (p *parser) parseExpressionWithTraversals() (Expression, Diagnostics) {
	term, diags := p.parseExpressionTerm()
	ret, moreDiags := p.parseExpressionTraversals(term)
	diags = append(diags, moreDiags...)
	return ret, diags
}

func makeRelativeTraversal(expr Expression, next Traverser, rng Range) Expression {
	switch texpr := expr.(type) {
	case *ScopeTraversalExpr:
		texpr.Traversal = append(texpr.Traversal, next)
		texpr.SrcRange = RangeBetween(texpr.SrcRange, rng)
		return texpr
	case *RelativeTraversalExpr:
		texpr.Traversal = append(texpr.Traversal, next)
		texpr.SrcRange = RangeBetween(texpr.SrcRange, rng)
		return texpr
	default:
		return &RelativeTraversalExpr{
			Source:    expr,
			Traversal: Traversal{next},
			SrcRange:  RangeBetween(expr.Range(), rng),
		}
	}
}

func (p *parser) parseExpressionTraversals(from Expression) (Expression, Diagnostics) {
	var diags Diagnostics
	ret := from
Traversal:
	for {
		next := p.Peek()
		switch next.Type {
		case TokenDot:
			dot := p.Read()
			attrTok := p.Peek()
			switch attrTok.Type {
			case TokenIdent:
				attrTok = p.Read()
				name := string(attrTok.Bytes)
				rng := RangeBetween(dot.Range, attrTok.Range)
				step := TraverseAttr{Name: name, SrcRange: rng}
				ret = makeRelativeTraversal(ret, step, rng)
			case TokenNumberLit:
				numTok := p.Read()
				numVal, numDiags := numberLitValue(numTok)
				diags = append(diags, numDiags...)
				rng := RangeBetween(dot.Range, numTok.Range)
				step := TraverseIndex{Key: numVal, SrcRange: rng}
				ret = makeRelativeTraversal(ret, step, rng)
			case TokenStar:
				// Attribute-only splat.
				marker := p.Read()
				trav := make(Traversal, 0, 1)
				var firstRange, lastRange Range
				firstRange = p.NextRange()
				lastRange = marker.Range
				for p.Peek().Type == TokenDot {
					dot := p.Read()
					if p.Peek().Type == TokenNumberLit {
						numTok := p.Read()
						numVal, numDiags := numberLitValue(numTok)
						diags = append(diags, numDiags...)
						trav = append(trav, TraverseIndex{Key: numVal, SrcRange: RangeBetween(dot.Range, numTok.Range)})
						lastRange = numTok.Range
						continue
					}
					if p.Peek().Type != TokenIdent {
						if !p.recovery {
							if p.Peek().Type == TokenStar {
								diags = append(diags, errDiag("Nested splat expression not allowed", "A splat expression (*) cannot be used inside another attribute-only splat expression.", p.Peek().Range))
							} else {
								diags = append(diags, errDiag("Invalid attribute name", "An attribute name is required after a dot.", p.Peek().Range))
							}
						}
						p.setRecovery()
						continue Traversal
					}
					attrTok := p.Read()
					trav = append(trav, TraverseAttr{Name: string(attrTok.Bytes), SrcRange: RangeBetween(dot.Range, attrTok.Range)})
					lastRange = attrTok.Range
				}
				itemExpr := &AnonSymbolExpr{SrcRange: RangeBetween(dot.Range, marker.Range)}
				var travExpr Expression
				if len(trav) == 0 {
					travExpr = itemExpr
				} else {
					travExpr = &RelativeTraversalExpr{Source: itemExpr, Traversal: trav, SrcRange: RangeBetween(firstRange, lastRange)}
				}
				ret = &SplatExpr{
					Source:      ret,
					Each:        travExpr,
					Item:        itemExpr,
					SrcRange:    RangeBetween(from.Range(), lastRange),
					MarkerRange: RangeBetween(dot.Range, marker.Range),
				}
			default:
				diags = append(diags, errDiag("Invalid attribute name", "An attribute name is required after a dot.", attrTok.Range))
				p.setRecovery()
				break Traversal
			}
		case TokenOBrack:
			open := p.Read()
			switch p.Peek().Type {
			case TokenStar:
				marker := p.Read()
				close := p.Read()
				if close.Type != TokenCBrack && !p.recovery {
					diags = append(diags, errDiag("Missing close bracket on splat", "The star for a full splat operator must be immediately followed by a closing bracket (\"]\").", close.Range))
					close = p.recover(TokenCBrack)
				}
				trav := make(Traversal, 0, 1)
				var firstRange, lastRange Range
				firstRange = p.NextRange()
				lastRange = close.Range
				for {
					if p.Peek().Type == TokenDot {
						dot := p.Read()
						if p.Peek().Type == TokenNumberLit {
							numTok := p.Read()
							numVal, numDiags := numberLitValue(numTok)
							diags = append(diags, numDiags...)
							trav = append(trav, TraverseIndex{Key: numVal, SrcRange: RangeBetween(dot.Range, numTok.Range)})
							lastRange = numTok.Range
							continue
						}
						if p.Peek().Type != TokenIdent {
							if !p.recovery {
								diags = append(diags, errDiag("Invalid attribute name", "An attribute name is required after a dot.", p.Peek().Range))
							}
							p.setRecovery()
							continue Traversal
						}
						attrTok := p.Read()
						trav = append(trav, TraverseAttr{Name: string(attrTok.Bytes), SrcRange: RangeBetween(dot.Range, attrTok.Range)})
						lastRange = attrTok.Range
					} else if p.Peek().Type == TokenOBrack {
						open := p.Read()
						p.PushIncludeNewlines(false)
						keyExpr, keyDiags := p.ParseExpression()
						diags = append(diags, keyDiags...)
						close := p.Read()
						if close.Type != TokenCBrack && !p.recovery {
							diags = append(diags, errDiag("Missing close bracket on index", "The index operator must end with a closing bracket (\"]\").", close.Range))
							close = p.recover(TokenCBrack)
						}
						p.PopIncludeNewlines()
						rng := RangeBetween(open.Range, close.Range)
						if lit, ok := keyExpr.(*LiteralValueExpr); ok {
							trav = append(trav, TraverseIndex{Key: lit.Val, SrcRange: rng})
						} else if tmpl, ok := keyExpr.(*TemplateExpr); ok && tmpl.IsStringLiteral() {
							trav = append(trav, TraverseIndex{Key: tmpl.Parts[0].(*LiteralValueExpr).Val, SrcRange: rng})
						} else {
							// Dynamic index inside a splat is unsupported; stop here.
							break
						}
						lastRange = close.Range
					} else {
						break
					}
				}
				itemExpr := &AnonSymbolExpr{SrcRange: RangeBetween(open.Range, close.Range)}
				var travExpr Expression
				if len(trav) == 0 {
					travExpr = itemExpr
				} else {
					travExpr = &RelativeTraversalExpr{Source: itemExpr, Traversal: trav, SrcRange: RangeBetween(firstRange, lastRange)}
				}
				ret = &SplatExpr{
					Source:      ret,
					Each:        travExpr,
					Item:        itemExpr,
					SrcRange:    RangeBetween(from.Range(), lastRange),
					MarkerRange: RangeBetween(open.Range, marker.Range),
				}
			default:
				var close *Token
				p.PushIncludeNewlines(false)
				keyExpr, keyDiags := p.ParseExpression()
				diags = append(diags, keyDiags...)
				if p.recovery && keyDiags.HasErrors() {
					close = p.recover(TokenCBrack)
				} else {
					close = p.Read()
					if close.Type != TokenCBrack && !p.recovery {
						diags = append(diags, errDiag("Missing close bracket on index", "The index operator must end with a closing bracket (\"]\").", close.Range))
						close = p.recover(TokenCBrack)
					}
				}
				p.PopIncludeNewlines()
				rng := RangeBetween(open.Range, close.Range)
				if lit, ok := keyExpr.(*LiteralValueExpr); ok {
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: lit.Val, SrcRange: rng}, rng)
				} else if tmpl, ok := keyExpr.(*TemplateExpr); ok && tmpl.IsStringLiteral() {
					ret = makeRelativeTraversal(ret, TraverseIndex{Key: tmpl.Parts[0].(*LiteralValueExpr).Val, SrcRange: rng}, rng)
				} else {
					ret = &IndexExpr{
						Collection:   ret,
						Key:          keyExpr,
						SrcRange:     RangeBetween(from.Range(), rng),
						OpenRange:    open.Range,
						BracketRange: rng,
					}
				}
			}
		default:
			break Traversal
		}
	}
	return ret, diags
}

func (p *parser) parseExpressionTerm() (Expression, Diagnostics) {
	start := p.Peek()
	switch start.Type {
	case TokenOParen:
		oParen := p.Read()
		p.PushIncludeNewlines(false)
		expr, diags := p.ParseExpression()
		close := p.Peek()
		if close.Type != TokenCParen {
			if !p.recovery {
				diags = append(diags, errDiag("Unbalanced parentheses", "Expected a closing parenthesis to terminate the expression.", close.Range))
			}
			p.setRecovery()
		}
		cParen := p.Read()
		p.PopIncludeNewlines()
		return &ParenthesesExpr{Expression: expr, SrcRange: RangeBetween(oParen.Range, cParen.Range)}, diags
	case TokenOBrace:
		return p.parseObjectCons()
	case TokenOBrack:
		return p.parseTupleCons()
	case TokenNumberLit:
		tok := p.Read()
		numVal, diags := numberLitValue(tok)
		return &LiteralValueExpr{Val: numVal, SrcRange: tok.Range}, diags
	case TokenIdent:
		tok := p.Read()
		if p.Peek().Type == TokenOParen || p.Peek().Type == TokenDoubleColon {
			return p.finishParsingFunctionCall(tok)
		}
		name := string(tok.Bytes)
		switch name {
		case "true":
			return &LiteralValueExpr{Val: BoolVal(true), SrcRange: tok.Range}, nil
		case "false":
			return &LiteralValueExpr{Val: BoolVal(false), SrcRange: tok.Range}, nil
		case "null":
			return &LiteralValueExpr{Val: NullVal, SrcRange: tok.Range}, nil
		default:
			return &ScopeTraversalExpr{
				Traversal: Traversal{TraverseRoot{Name: name, SrcRange: tok.Range}},
				SrcRange:  tok.Range,
			}, nil
		}
	case TokenOQuote, TokenOHeredoc:
		open := p.Read()
		closer := p.oppositeBracket(open.Type)
		exprs, passthru, _, diags := p.parseTemplateInner(closer, tokenOpensFlushHeredoc(open))
		closeRange := p.PrevRange()
		if passthru {
			return &TemplateWrapExpr{Wrapped: exprs[0], SrcRange: RangeBetween(open.Range, closeRange)}, diags
		}
		return &TemplateExpr{Parts: exprs, SrcRange: RangeBetween(open.Range, closeRange)}, diags
	case TokenMinus:
		tok := p.Read()
		operand, diags := p.parseExpressionWithTraversals()
		return &UnaryOpExpr{Op: TokenMinus, Val: operand, SrcRange: RangeBetween(tok.Range, operand.Range()), SymbolRange: tok.Range}, diags
	case TokenBang:
		tok := p.Read()
		operand, diags := p.parseExpressionWithTraversals()
		return &UnaryOpExpr{Op: TokenBang, Val: operand, SrcRange: RangeBetween(tok.Range, operand.Range()), SymbolRange: tok.Range}, diags
	default:
		var diags Diagnostics
		if !p.recovery {
			diags = append(diags, errDiag("Invalid expression", "Expected the start of an expression, but found an invalid expression token.", start.Range))
		}
		p.setRecovery()
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: start.Range}, diags
	}
}

func numberLitValue(tok *Token) (Value, Diagnostics) {
	v, err := ParseNumberVal(string(tok.Bytes))
	if err != nil {
		return UnknownVal, Diagnostics{errDiag("Invalid number literal", "Failed to recognize the value of this number literal.", tok.Range)}
	}
	return v, nil
}

func (p *parser) finishParsingFunctionCall(tok *Token) (Expression, Diagnostics) {
	var diags Diagnostics
	name := string(tok.Bytes)
	nameRange := tok.Range
	for p.Peek().Type == TokenDoubleColon {
		p.Read()
		next := p.Read()
		if next.Type != TokenIdent {
			if !p.recovery {
				diags = append(diags, errDiag("Missing function name", "Function scope resolution symbol :: must be followed by a function name in this scope.", next.Range))
			}
			p.setRecovery()
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: next.Range}, diags
		}
		name += "::" + string(next.Bytes)
		nameRange = RangeBetween(nameRange, next.Range)
	}
	openTok := p.Read()
	if openTok.Type != TokenOParen {
		diags = append(diags, errDiag("Missing open parenthesis", "Function selector must be followed by an open parenthesis to begin the function call.", openTok.Range))
		p.setRecovery()
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: openTok.Range}, diags
	}
	var args []Expression
	var expandFinal bool
	var closeTok *Token
	p.PushIncludeNewlines(false)
Token:
	for {
		tok := p.Peek()
		if tok.Type == TokenCParen {
			closeTok = p.Read()
			break Token
		}
		arg, argDiags := p.ParseExpression()
		args = append(args, arg)
		diags = append(diags, argDiags...)
		if p.recovery && argDiags.HasErrors() {
			closeTok = p.recover(TokenCParen)
			break Token
		}
		sep := p.Read()
		if sep.Type == TokenCParen {
			closeTok = sep
			break Token
		}
		if sep.Type == TokenEllipsis {
			expandFinal = true
			if p.Peek().Type != TokenCParen {
				if !p.recovery {
					diags = append(diags, errDiag("Missing closing parenthesis", "An expanded function argument (with ...) must be immediately followed by closing parentheses.", sep.Range))
				}
				closeTok = p.recover(TokenCParen)
			} else {
				closeTok = p.Read()
			}
			break Token
		}
		if sep.Type != TokenComma {
			switch sep.Type {
			case TokenEOF:
				diags = append(diags, errDiag("Unterminated function call", "There is no closing parenthesis for this function call before the end of the file. This may be caused by incorrect parenthesis nesting elsewhere in this file.", openTok.Range))
			default:
				diags = append(diags, errDiag("Missing argument separator", "A comma is required to separate each function argument from the next.", sep.Range))
			}
			closeTok = p.recover(TokenCParen)
			break Token
		}
		if p.Peek().Type == TokenCParen {
			// A trailing comma is allowed.
			closeTok = p.Read()
			break Token
		}
	}
	p.PopIncludeNewlines()
	return &FunctionCallExpr{
		Name:            name,
		Args:            args,
		ExpandFinal:     expandFinal,
		NameRange:       nameRange,
		OpenParenRange:  openTok.Range,
		CloseParenRange: closeTok.Range,
	}, diags
}

func (p *parser) parseTupleCons() (Expression, Diagnostics) {
	open := p.Read()
	p.PushIncludeNewlines(false)
	defer p.PopIncludeNewlines()
	if forKeyword.TokenMatches(p.Peek()) {
		return p.finishParsingForExpr(open)
	}
	var close *Token
	var diags Diagnostics
	var exprs []Expression
	for {
		next := p.Peek()
		if next.Type == TokenCBrack {
			close = p.Read()
			break
		}
		if next.Type == TokenEOF {
			if !p.recovery {
				diags = append(diags, errDiag("Unterminated tuple constructor expression", "There is no corresponding closing bracket before the end of the file. This may be caused by incorrect bracket nesting elsewhere in this file.", open.Range))
			}
			close = p.recover(TokenCBrack)
			break
		}
		expr, exprDiags := p.ParseExpression()
		exprs = append(exprs, expr)
		diags = append(diags, exprDiags...)
		if p.recovery && exprDiags.HasErrors() {
			close = p.recover(TokenCBrack)
			break
		}
		next = p.Peek()
		if next.Type == TokenCBrack {
			close = p.Read()
			break
		}
		if next.Type != TokenComma {
			if !p.recovery {
				diags = append(diags, errDiag("Missing item separator", "Expected a comma to mark the beginning of the next item.", next.Range))
			}
			close = p.recover(TokenCBrack)
			break
		}
		p.Read()
	}
	return &TupleConsExpr{Exprs: exprs, SrcRange: RangeBetween(open.Range, close.Range), OpenRange: open.Range}, diags
}

func (p *parser) parseObjectCons() (Expression, Diagnostics) {
	open := p.Read()
	p.PushIncludeNewlines(true)
	defer p.PopIncludeNewlines()
	if forKeyword.TokenMatches(p.Peek()) {
		p.PushIncludeNewlines(false)
		defer p.PopIncludeNewlines()
		return p.finishParsingForExpr(open)
	}
	var close *Token
	var diags Diagnostics
	var items []ObjectConsItem
	for {
		next := p.Peek()
		if next.Type == TokenNewline {
			p.Read()
			continue
		}
		if next.Type == TokenCBrace {
			close = p.Read()
			break
		}
		if next.Type == TokenEOF {
			if !p.recovery {
				diags = append(diags, errDiag("Unterminated object constructor expression", "There is no corresponding closing brace before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", open.Range))
			}
			close = p.recover(TokenCBrace)
			break
		}
		var key Expression
		var keyDiags Diagnostics
		key, keyDiags = p.ParseExpression()
		diags = append(diags, keyDiags...)
		if p.recovery && keyDiags.HasErrors() {
			close = p.recover(TokenCBrace)
			break
		}
		key = &ObjectConsKeyExpr{Wrapped: key}
		next = p.Peek()
		if next.Type != TokenEqual && next.Type != TokenColon {
			if !p.recovery {
				switch next.Type {
				case TokenNewline, TokenComma:
					diags = append(diags, errDiag("Missing attribute value", "Expected an attribute value, introduced by an equals sign (\"=\").", next.Range))
				case TokenIdent:
					diags = append(diags, errDiag("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value. If you intended to given an attribute name containing periods or spaces, write the name in quotes to create a string literal.", next.Range))
				case TokenOQuote, TokenOBrack, TokenNumberLit:
					diags = append(diags, errDiag("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.", next.Range))
				default:
					diags = append(diags, errDiag("Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.", next.Range))
				}
			}
			close = p.recover(TokenCBrace)
			break
		}
		p.Read()
		value, valueDiags := p.ParseExpression()
		diags = append(diags, valueDiags...)
		if p.recovery && valueDiags.HasErrors() {
			close = p.recover(TokenCBrace)
			break
		}
		items = append(items, ObjectConsItem{KeyExpr: key, ValueExpr: value})
		next = p.Peek()
		if next.Type == TokenCBrace {
			close = p.Read()
			break
		}
		if next.Type != TokenComma && next.Type != TokenNewline {
			if !p.recovery {
				switch next.Type {
				case TokenEOF:
					diags = append(diags, errDiag("Unterminated object constructor expression", "There is no corresponding closing brace before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.", open.Range))
				default:
					diags = append(diags, errDiag("Missing attribute separator", "Expected a newline or comma to mark the beginning of the next attribute.", next.Range))
				}
			}
			close = p.recover(TokenCBrace)
			break
		}
		p.Read()
	}
	return &ObjectConsExpr{Items: items, SrcRange: RangeBetween(open.Range, close.Range), OpenRange: open.Range}, diags
}

// keyword helpers.
type keyword string

const (
	forKeyword keyword = "for"
	inKeyword  keyword = "in"
	ifKeyword  keyword = "if"
	elseKeyword keyword = "else"
	endifKeyword keyword = "endif"
	endforKeyword keyword = "endfor"
)

func (k keyword) TokenMatches(tok *Token) bool {
	return tok.Type == TokenIdent && string(tok.Bytes) == string(k)
}

func (p *parser) finishParsingForExpr(open *Token) (Expression, Diagnostics) {
	p.PushIncludeNewlines(false)
	defer p.PopIncludeNewlines()
	introducer := p.Read()
	if !forKeyword.TokenMatches(introducer) {
		return nil, Diagnostics{errDiag("Invalid for expression", "Expected the \"for\" keyword.", introducer.Range)}
	}
	var diags Diagnostics
	var keyName, valName string
	if p.Peek().Type != TokenIdent {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires variable name after 'for'.", p.Peek().Range))
		}
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	valName = string(p.Read().Bytes)
	if p.Peek().Type == TokenComma {
		p.Read()
		if p.Peek().Type != TokenIdent {
			if !p.recovery {
				diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires value variable name after comma.", p.Peek().Range))
			}
			close := p.recover(p.oppositeBracket(open.Type))
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
		keyName = valName
		valName = string(p.Read().Bytes)
	}
	if !inKeyword.TokenMatches(p.Peek()) {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires the 'in' keyword after its name declarations.", p.Peek().Range))
		}
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	p.Read()
	collExpr, collDiags := p.ParseExpression()
	diags = append(diags, collDiags...)
	if p.recovery && collDiags.HasErrors() {
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	if p.Peek().Type != TokenColon {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "For expression requires a colon after the collection expression.", p.Peek().Range))
		}
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	p.Read()
	var keyExpr, valExpr Expression
	var group bool
	first, firstDiags := p.ParseExpression()
	diags = append(diags, firstDiags...)
	if p.recovery && firstDiags.HasErrors() {
		close := p.recover(p.oppositeBracket(open.Type))
		return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
	}
	if open.Type == TokenOBrace {
		if p.Peek().Type != TokenFatArrow {
			if !p.recovery {
				diags = append(diags, errDiag("Invalid 'for' expression", "For expression in braces requires a key expression, followed by \"=>\", and then a value expression.", p.Peek().Range))
			}
			close := p.recover(TokenCBrace)
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
		p.Read()
		keyExpr = first
		var valDiags Diagnostics
		valExpr, valDiags = p.ParseExpression()
		diags = append(diags, valDiags...)
		if p.recovery && valDiags.HasErrors() {
			close := p.recover(TokenCBrace)
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
		if p.Peek().Type == TokenEllipsis {
			p.Read()
			group = true
		}
	} else {
		valExpr = first
	}
	var condExpr Expression
	if ifKeyword.TokenMatches(p.Peek()) {
		p.Read()
		var condDiags Diagnostics
		condExpr, condDiags = p.ParseExpression()
		diags = append(diags, condDiags...)
		if p.recovery && condDiags.HasErrors() {
			close := p.recover(p.oppositeBracket(open.Type))
			return &LiteralValueExpr{Val: UnknownVal, SrcRange: RangeBetween(open.Range, close.Range)}, diags
		}
	}
	var close *Token
	if p.Peek().Type == p.oppositeBracket(open.Type) {
		close = p.Read()
	} else {
		if !p.recovery {
			diags = append(diags, errDiag("Invalid 'for' expression", "Extra characters after the end of the 'for' expression.", p.Peek().Range))
		}
		close = p.recover(p.oppositeBracket(open.Type))
	}
	return &ForExpr{
		KeyVar:    keyName,
		ValVar:    valName,
		CollExpr:  collExpr,
		KeyExpr:   keyExpr,
		ValExpr:   valExpr,
		CondExpr:  condExpr,
		Group:     group,
		SrcRange:  RangeBetween(open.Range, close.Range),
		OpenRange: open.Range,
	}, diags
}

// parseQuotedStringLiteral parses a quoted string that must not contain
// interpolations (used for block labels).
func (p *parser) parseQuotedStringLiteral() (string, Range, Diagnostics) {
	oQuote := p.Read()
	if oQuote.Type != TokenOQuote {
		return "", oQuote.Range, Diagnostics{errDiag("Invalid string literal", "A quoted string is required here.", oQuote.Range)}
	}
	var diags Diagnostics
	var ret strings.Builder
	var endRange Range
Token:
	for {
		tok := p.Read()
		switch tok.Type {
		case TokenCQuote:
			endRange = tok.Range
			break Token
		case TokenQuotedLit:
			s, sDiags := ParseStringLiteralToken(tok)
			diags = append(diags, sDiags...)
			ret.WriteString(s)
		case TokenTemplateControl, TokenTemplateInterp:
			which := "$"
			if tok.Type == TokenTemplateControl {
				which = "%"
			}
			diags = append(diags, errDiag("Invalid string literal", fmt.Sprintf("Template sequences are not allowed in this string. To include a literal %q, double it (as \"%s%s\") to escape it.", which, which, which), tok.Range))
			p.recover(TokenTemplateSeqEnd)
		case TokenEOF:
			diags = append(diags, errDiag("Unterminated string literal", "Unable to find the closing quote mark before the end of the file.", tok.Range))
			endRange = tok.Range
			break Token
		case TokenQuotedNewline:
			diags = append(diags, errDiag("Invalid multi-line string", "Quoted strings may not be split over multiple lines. To produce a multi-line string, either use the \\n escape to represent a newline character or use the \"heredoc\" multi-line template syntax.", tok.Range))
		default:
			diags = append(diags, errDiag("Invalid string literal", "This item is not valid in a string literal.", tok.Range))
			p.recover(TokenCQuote)
			endRange = tok.Range
			break Token
		}
	}
	return ret.String(), RangeBetween(oQuote.Range, endRange), diags
}

// ParseStringLiteralToken decodes the escape sequences of a string literal token.
func ParseStringLiteralToken(tok *Token) (string, Diagnostics) {
	var quoted bool
	switch tok.Type {
	case TokenQuotedLit:
		quoted = true
	case TokenStringLit:
		quoted = false
	default:
		return "", Diagnostics{errDiag("Invalid string literal", "A string literal token is required here.", tok.Range)}
	}
	var diags Diagnostics
	ret := make([]byte, 0, len(tok.Bytes))
	src := tok.Bytes
	for i := 0; i < len(src); {
		c := src[i]
		switch {
		case c == '\\' && quoted:
			if i+1 >= len(src) {
				diags = append(diags, errDiag("Invalid escape sequence", "Backslash must be followed by an escape sequence selector character.", tok.Range))
				i++
				continue
			}
			e := src[i+1]
			switch e {
			case 'n':
				ret = append(ret, '\n')
				i += 2
			case 'r':
				ret = append(ret, '\r')
				i += 2
			case 't':
				ret = append(ret, '\t')
				i += 2
			case '"':
				ret = append(ret, '"')
				i += 2
			case '\\':
				ret = append(ret, '\\')
				i += 2
			case 'u', 'U':
				n := 4
				if e == 'U' {
					n = 8
				}
				if i+2+n > len(src) {
					diags = append(diags, errDiag("Invalid escape sequence", fmt.Sprintf("The %q escape sequence must be followed by %d hexadecimal digits.", string(e), n), tok.Range))
					i = len(src)
					continue
				}
				var r rune
				ok := true
				for _, h := range src[i+2 : i+2+n] {
					var d byte
					switch {
					case h >= '0' && h <= '9':
						d = h - '0'
					case h >= 'a' && h <= 'f':
						d = h - 'a' + 10
					case h >= 'A' && h <= 'F':
						d = h - 'A' + 10
					default:
						ok = false
					}
					r = r*16 + rune(d)
				}
				if !ok {
					diags = append(diags, errDiag("Invalid escape sequence", fmt.Sprintf("The %q escape sequence must be followed by %d hexadecimal digits.", string(e), n), tok.Range))
				}
				var buf [utf8.UTFMax]byte
				l := utf8.EncodeRune(buf[:], r)
				ret = append(ret, buf[:l]...)
				i += 2 + n
			default:
				diags = append(diags, errDiag("Invalid escape sequence", fmt.Sprintf("The symbol %q is not a valid escape sequence selector.", string(e)), tok.Range))
				ret = append(ret, e)
				i += 2
			}
		case c == '$' && i+2 < len(src) && src[i+1] == '$' && src[i+2] == '{':
			ret = append(ret, '$', '{')
			i += 3
		case c == '%' && i+2 < len(src) && src[i+1] == '%' && src[i+2] == '{':
			ret = append(ret, '%', '{')
			i += 3
		default:
			ret = append(ret, c)
			i++
		}
	}
	return string(ret), diags
}

func tokenOpensFlushHeredoc(tok *Token) bool {
	if tok.Type != TokenOHeredoc {
		return false
	}
	return len(tok.Bytes) > 2 && tok.Bytes[2] == '-'
}
