func flushHeredocTemplateParts(parts *templateParts) {
	if len(parts.Tokens) == 0 {
		return
	}
	// Find the minimum indentation across all lines.
	minSpaces := -1
	for _, tok := range parts.Tokens {
		lit, ok := tok.(*templateLiteralToken)
		if !ok {
			continue
		}
		lines := strings.Split(lit.Val, "\n")
		for i, line := range lines {
			if i == len(lines)-1 && line == "" {
				continue
			}
			if strings.TrimSpace(line) == "" {
				continue
			}
			spaces := 0
			for _, c := range line {
				if c == ' ' || c == '\t' {
					spaces++
				} else {
					break
				}
			}
			if minSpaces == -1 || spaces < minSpaces {
				minSpaces = spaces
			}
		}
	}
	if minSpaces <= 0 {
		return
	}
	atLineStart := true
	for _, tok := range parts.Tokens {
		lit, ok := tok.(*templateLiteralToken)
		if !ok {
			atLineStart = false
			continue
		}
		var b strings.Builder
		lines := strings.SplitAfter(lit.Val, "\n")
		for _, line := range lines {
			if atLineStart {
				trimmed := 0
				for trimmed < minSpaces && trimmed < len(line) && (line[trimmed] == ' ' || line[trimmed] == '\t') {
					trimmed++
				}
				line = line[trimmed:]
			}
			b.WriteString(line)
			atLineStart = strings.HasSuffix(line, "\n")
		}
		lit.Val = b.String()
	}
}

func meldConsecutiveStringLiterals(parts *templateParts) {
	if len(parts.Tokens) == 0 {
		return
	}
	var out []templateToken
	for _, tok := range parts.Tokens {
		lit, ok := tok.(*templateLiteralToken)
		if ok && len(out) > 0 {
			if prev, ok := out[len(out)-1].(*templateLiteralToken); ok {
				prev.Val += lit.Val
				prev.SrcRange = RangeBetween(prev.SrcRange, lit.SrcRange)
				continue
			}
		}
