type templateParser struct {
	Tokens   []templateToken
	SrcRange Range
	pos      int
}

func (p *templateParser) Peek() templateToken { return p.Tokens[p.pos] }
func (p *templateParser) Read() templateToken {
	ret := p.Peek()
	if _, end := ret.(*templateEndToken); !end {
		p.pos++
	}
	return ret
}

func (p *templateParser) parseRoot() ([]Expression, Diagnostics) {
	var exprs []Expression
	var diags Diagnostics
	for {
		next := p.Peek()
		if _, isEnd := next.(*templateEndToken); isEnd {
			break
		}
		expr, exprDiags := p.parseExpr()
		diags = append(diags, exprDiags...)
		exprs = append(exprs, expr)
	}
	return exprs, diags
}

func (p *templateParser) parseExpr() (Expression, Diagnostics) {
	next := p.Read()
	switch tok := next.(type) {
	case *templateLiteralToken:
		return &LiteralValueExpr{Val: StringVal(tok.Val), SrcRange: tok.SrcRange}, nil
	case *templateInterpToken:
		return tok.Expr, nil
	case *templateIfToken:
		return p.parseIf(tok)
	case *templateForToken:
		return p.parseFor(tok)
	case *templateEndToken:
		return &LiteralValueExpr{Val: StringVal(""), SrcRange: tok.SrcRange}, nil
	case *templateEndIfToken:
		return &LiteralValueExpr{Val: StringVal(""), SrcRange: tok.SrcRange}, Diagnostics{errDiag("Unexpected endif directive", "This endif directive has no matching if directive.", tok.SrcRange)}
	case *templateElseToken:
		return &LiteralValueExpr{Val: StringVal(""), SrcRange: tok.SrcRange}, Diagnostics{errDiag("Unexpected else directive", "This else directive has no matching if directive.", tok.SrcRange)}
	case *templateEndForToken:
		return &LiteralValueExpr{Val: StringVal(""), SrcRange: tok.SrcRange}, Diagnostics{errDiag("Unexpected endfor directive", "This endfor directive has no matching for directive.", tok.SrcRange)}
	}
	return &LiteralValueExpr{Val: StringVal("")}, nil
}

func (p *templateParser) parseIf(open *templateIfToken) (Expression, Diagnostics) {
	var diags Diagnostics
	var trueExprs, falseExprs []Expression
	var elseTok *templateElseToken
	var endRange Range
	collecting := &trueExprs
Token:
	for {
		next := p.Peek()
		switch tok := next.(type) {
		case *templateElseToken:
			p.Read()
			if elseTok != nil {
				diags = append(diags, errDiag("Unexpected else directive", "Already in the else clause for this if directive.", tok.SrcRange))
				continue
			}
			elseTok = tok
			collecting = &falseExprs
		case *templateEndIfToken:
			p.Read()
			endRange = tok.SrcRange
			break Token
		case *templateEndToken:
			diags = append(diags, errDiag("Unexpected end of template", "The control directives within this template are unbalanced.", tok.SrcRange))
			endRange = tok.SrcRange
			break Token
		default:
			expr, exprDiags := p.parseExpr()
			diags = append(diags, exprDiags...)
			*collecting = append(*collecting, expr)
		}
	}
	if len(trueExprs) == 0 {
		trueExprs = append(trueExprs, &LiteralValueExpr{Val: StringVal(""), SrcRange: open.SrcRange})
	}
	if len(falseExprs) == 0 {
		falseExprs = append(falseExprs, &LiteralValueExpr{Val: StringVal(""), SrcRange: endRange})
	}
	return &ConditionalExpr{
		Condition:   open.CondExpr,
		TrueResult:  &TemplateExpr{Parts: trueExprs, SrcRange: RangeBetween(open.SrcRange, endRange)},
		FalseResult: &TemplateExpr{Parts: falseExprs, SrcRange: RangeBetween(open.SrcRange, endRange)},
		SrcRange:    RangeBetween(open.SrcRange, endRange),
	}, diags
}

func (p *templateParser) parseFor(open *templateForToken) (Expression, Diagnostics) {
	var diags Diagnostics
	var exprs []Expression
	var endRange Range
Token:
	for {
		next := p.Peek()
		switch tok := next.(type) {
		case *templateEndForToken:
			p.Read()
			endRange = tok.SrcRange
			break Token
		case *templateEndToken:
			diags = append(diags, errDiag("Unexpected end of template", "The control directives within this template are unbalanced.", tok.SrcRange))
			endRange = tok.SrcRange
			break Token
		default:
			expr, exprDiags := p.parseExpr()
			diags = append(diags, exprDiags...)
			exprs = append(exprs, expr)
		}
	}
	if len(exprs) == 0 {
		exprs = append(exprs, &LiteralValueExpr{Val: StringVal(""), SrcRange: open.SrcRange})
	}
	return &TemplateJoinExpr{Tuple: &ForExpr{
		KeyVar:    open.KeyVar,
		ValVar:    open.ValVar,
		CollExpr:  open.CollExpr,
		ValExpr:   &TemplateExpr{Parts: exprs, SrcRange: RangeBetween(open.SrcRange, endRange)},
		SrcRange:  RangeBetween(open.SrcRange, endRange),
		OpenRange: open.SrcRange,
	}}, diags
}
