package hcl

import (
	"fmt"
	"math/big"
	"strings"
)

// Param describes a function parameter.
type Param struct {
	Name      string
	Type      *TypeConstraint
	AllowNull bool
	// AllowAny accepts any value kind without conversion.
	AllowAny bool
}

// Function is a callable function available to expressions.
type Function struct {
	Params   []Param
	VarParam *Param
	Impl     func(args []Value) (Value, error)
}

// EvalContext holds the variables and functions available to expressions.
type EvalContext struct {
	Variables map[string]Value
	Functions map[string]*Function
	parent    *EvalContext
	// ResolveRef, if set, resolves traversals whose root name is not a variable.
	ResolveRef func(trav Traversal, ctx *EvalContext) (Value, Diagnostics, bool)
	// ResolveFunc, if set, resolves calls to functions that are not defined.
	ResolveFunc func(name string) (*Function, bool)
}

// NewChild returns a child context inheriting from ctx.
func (ctx *EvalContext) NewChild() *EvalContext {
	return &EvalContext{parent: ctx}
}

// Parent returns the parent context.
func (ctx *EvalContext) Parent() *EvalContext { return ctx.parent }

func (ctx *EvalContext) lookupVar(name string) (Value, bool) {
	for c := ctx; c != nil; c = c.parent {
		if c.Variables != nil {
			if v, ok := c.Variables[name]; ok {
				return v, true
			}
		}
	}
	return NullVal, false
}

func (ctx *EvalContext) allVarNames() []string {
	var names []string
	for c := ctx; c != nil; c = c.parent {
		for k := range c.Variables {
			names = append(names, k)
		}
	}
	return names
}

func (ctx *EvalContext) lookupFunc(name string) (*Function, bool) {
	for c := ctx; c != nil; c = c.parent {
		if c.Functions != nil {
			if f, ok := c.Functions[name]; ok {
				return f, true
			}
		}
	}
	for c := ctx; c != nil; c = c.parent {
		if c.ResolveFunc != nil {
			if f, ok := c.ResolveFunc(name); ok {
				return f, true
			}
		}
	}
	return nil, false
}

func (ctx *EvalContext) allFuncNames() []string {
	var names []string
	for c := ctx; c != nil; c = c.parent {
		for k := range c.Functions {
			names = append(names, k)
		}
	}
	return names
}

func (ctx *EvalContext) resolveRef(trav Traversal) (Value, Diagnostics, bool) {
	for c := ctx; c != nil; c = c.parent {
		if c.ResolveRef != nil {
			return c.ResolveRef(trav, ctx)
		}
	}
	return NullVal, nil, false
}

// Eval evaluates an expression in the given context.
func Eval(expr Expression, ctx *EvalContext) (Value, Diagnostics) {
	switch e := expr.(type) {
	case *LiteralValueExpr:
		return e.Val, nil
	case *TemplateExpr:
		return evalTemplate(e, ctx)
	case *TemplateWrapExpr:
		return Eval(e.Wrapped, ctx)
	case *ScopeTraversalExpr:
		return evalScopeTraversal(e, ctx)
	case *RelativeTraversalExpr:
		src, diags := Eval(e.Source, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		v, moreDiags := applyTraversal(src, e.Traversal, ctx)
		return v, diags.Extend(moreDiags)
	case *FunctionCallExpr:
		return evalFunctionCall(e, ctx)
	case *ConditionalExpr:
		return evalConditional(e, ctx)
	case *IndexExpr:
		coll, diags := Eval(e.Collection, ctx)
		key, keyDiags := Eval(e.Key, ctx)
		diags = diags.Extend(keyDiags)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		v, idxDiags := indexValue(coll, key, e.BracketRange)
		return v, diags.Extend(idxDiags)
	case *BinaryOpExpr:
		return evalBinaryOp(e, ctx)
	case *UnaryOpExpr:
		return evalUnaryOp(e, ctx)
	case *TupleConsExpr:
		var diags Diagnostics
		vals := make([]Value, 0, len(e.Exprs))
		for _, x := range e.Exprs {
			v, d := Eval(x, ctx)
			diags = diags.Extend(d)
			vals = append(vals, v)
		}
		return TupleVal(vals), diags
	case *ObjectConsExpr:
		var diags Diagnostics
		keys := make([]string, 0, len(e.Items))
		m := make(map[string]Value, len(e.Items))
		for _, item := range e.Items {
			k, d := evalObjectKey(item.KeyExpr, ctx)
			diags = diags.Extend(d)
			v, vd := Eval(item.ValueExpr, ctx)
			diags = diags.Extend(vd)
			if d.HasErrors() {
				continue
			}
			if _, exists := m[k]; !exists {
				keys = append(keys, k)
			}
			m[k] = v
		}
		return ObjectVal(keys, m), diags
	case *ObjectConsKeyExpr:
		k, diags := evalObjectKey(e, ctx)
		return StringVal(k), diags
	case *ForExpr:
		return evalFor(e, ctx)
	case *ParenthesesExpr:
		return Eval(e.Expression, ctx)
	case *SplatExpr:
		return evalSplat(e, ctx)
	case *AnonSymbolExpr:
		if e.val == nil {
			return UnknownVal, Diagnostics{errDiag("Invalid splat item reference", "The splat item placeholder can only be used inside a splat expression.", e.SrcRange)}
		}
		return *e.val, nil
	case *TemplateJoinExpr:
		tuple, diags := Eval(e.Tuple, ctx)
		if diags.HasErrors() {
			return UnknownVal, diags
		}
		if tuple.Kind() != KindTuple {
			return UnknownVal, diags.Append(errDiag("Invalid template join", "A template for directive must produce a sequence.", e.Range()))
		}
		var b strings.Builder
		for _, el := range tuple.Elements() {
			s, err := Convert(el, &TypeConstraint{Kind: KindString})
			if err != nil {
				return UnknownVal, diags.Append(errDiag("Invalid template interpolation value", fmt.Sprintf("Cannot include the given value in a string template: %s.", err.Error()), e.Range()))
			}
			if s.IsNull() {
				continue
			}
			b.WriteString(s.AsString())
		}
		return StringVal(b.String()), diags
	}
	return UnknownVal, Diagnostics{errDiag("Unsupported expression", fmt.Sprintf("Expression of type %T is not supported.", expr), expr.Range())}
}

func evalObjectKey(expr Expression, ctx *EvalContext) (string, Diagnostics) {
	if k, ok := expr.(*ObjectConsKeyExpr); ok {
		// Bare identifiers are treated as literal key names.
		if st, ok := k.Wrapped.(*ScopeTraversalExpr); ok && len(st.Traversal) == 1 {
			return st.Traversal.RootName(), nil
		}
		expr = k.Wrapped
	}
	v, diags := Eval(expr, ctx)
	if diags.HasErrors() {
		return "", diags
	}
	if v.IsNull() {
		return "", diags.Append(errDiag("Null value as key", "Can't use a null value as a key.", expr.Range()))
	}
	s, err := Convert(v, &TypeConstraint{Kind: KindString})
	if err != nil {
		return "", diags.Append(errDiag("Incorrect key type", fmt.Sprintf("Can't use this value as a key: %s.", err.Error()), expr.Range()))
	}
	return s.AsString(), diags
}

func evalTemplate(e *TemplateExpr, ctx *EvalContext) (Value, Diagnostics) {
	var diags Diagnostics
	var b strings.Builder
	for _, part := range e.Parts {
		v, d := Eval(part, ctx)
		diags = diags.Extend(d)
		if d.HasErrors() {
			continue
		}
		if !v.IsKnown() {
			continue
		}
		if v.IsNull() {
			diags = diags.Append(errDiag("Invalid template interpolation value", "The expression result is null. Cannot include a null value in a string template.", part.Range()))
			continue
		}
		switch v.Kind() {
		case KindString, KindNumber, KindBool:
			s, _ := Convert(v, &TypeConstraint{Kind: KindString})
			b.WriteString(s.AsString())
		case KindRef:
			b.WriteString(v.Ref().Path)
		default:
			diags = diags.Append(errDiag("Invalid template interpolation value", "Cannot include the given value in a string template: string required.", part.Range()))
		}
	}
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	return StringVal(b.String()), diags
}

func nameSuggestion(given string, suggestions []string) string {
	for _, s := range suggestions {
		if levenshtein(given, s) < 3 {
			return s
		}
	}
	return ""
}

func levenshtein(a, b string) int {
	ra, rb := []rune(a), []rune(b)
	if len(ra) == 0 {
		return len(rb)
	}
	if len(rb) == 0 {
		return len(ra)
	}
	prev := make([]int, len(rb)+1)
	cur := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev, cur = cur, prev
	}
	return prev[len(rb)]
}

func min3(a, b, c int) int {
	if b < a {
		a = b
	}
	if c < a {
		a = c
	}
	return a
}

func evalScopeTraversal(e *ScopeTraversalExpr, ctx *EvalContext) (Value, Diagnostics) {
	root := e.Traversal[0].(TraverseRoot)
	v, ok := ctx.lookupVar(root.Name)
	if !ok {
		if rv, diags, handled := ctx.resolveRef(e.Traversal); handled {
			return rv, diags
		}
		summary := "Unknown variable"
		if root.Name == "local" {
			summary = "Unknown local"
		}
		suggestion := nameSuggestion(root.Name, ctx.allVarNames())
		if suggestion != "" {
			suggestion = fmt.Sprintf(" Did you mean %q?", suggestion)
		}
		return UnknownVal, Diagnostics{errDiag(summary, fmt.Sprintf("There is no variable named %q.%s", root.Name, suggestion), root.SrcRange)}
	}
	return applyTraversal(v, e.Traversal[1:], ctx)
}

func applyTraversal(v Value, trav Traversal, ctx *EvalContext) (Value, Diagnostics) {
	for _, step := range trav {
		switch s := step.(type) {
		case TraverseAttr:
			var diags Diagnostics
			v, diags = getAttr(v, s.Name, s.SrcRange)
			if diags.HasErrors() {
				return UnknownVal, diags
			}
		case TraverseIndex:
			var diags Diagnostics
			v, diags = indexValue(v, s.Key, s.SrcRange)
			if diags.HasErrors() {
				return UnknownVal, diags
			}
		}
	}
	return v, nil
}

func getAttr(v Value, name string, rng Range) (Value, Diagnostics) {
	if !v.IsKnown() {
		return UnknownVal, nil
	}
	switch v.Kind() {
	case KindNull:
		return UnknownVal, Diagnostics{errDiag("Attempt to get attribute from null value", "This value is null, so it does not have any attributes.", rng)}
	case KindObject:
		if a, ok := v.Get(name); ok {
			return a, nil
		}
		if v.isMap {
			return UnknownVal, Diagnostics{errDiag("Missing map element", fmt.Sprintf("This map does not have an element with the key %q.", name), rng)}
		}
		suggestion := nameSuggestion(name, v.Keys())
		if suggestion != "" {
			suggestion = fmt.Sprintf(" Did you mean %q?", suggestion)
		}
		return UnknownVal, Diagnostics{errDiag("Unsupported attribute", fmt.Sprintf("This object does not have an attribute named %q.%s", name, suggestion), rng)}
	case KindRef:
		return RefVal(v.Ref().Path + "." + name), nil
	case KindTuple:
		return UnknownVal, Diagnostics{errDiag("Unsupported attribute", "This value does not have any attributes.", rng)}
	default:
		return UnknownVal, Diagnostics{errDiag("Unsupported attribute", "This value does not have any attributes.", rng)}
	}
}

func indexValue(coll, key Value, rng Range) (Value, Diagnostics) {
	if !coll.IsKnown() || !key.IsKnown() {
		return UnknownVal, nil
	}
	if coll.IsNull() {
		return UnknownVal, Diagnostics{errDiag("Attempt to index null value", "This value is null, so it does not have any indices.", rng)}
	}
	if key.IsNull() {
		return UnknownVal, Diagnostics{errDiag("Invalid index", "Can't use a null value as an indexing key.", rng)}
	}
	switch coll.Kind() {
	case KindTuple:
		k, err := Convert(key, &TypeConstraint{Kind: KindNumber})
		if err != nil {
			return UnknownVal, Diagnostics{errDiag("Invalid index", "The given key does not identify an element in this collection value: a number is required.", rng)}
		}
		i, ok := k.AsInt64()
		if !ok {
			return UnknownVal, Diagnostics{errDiag("Invalid index", "The given key does not identify an element in this collection value: indexing a sequence requires a whole number, but the given index (%s) has a fractional part.", rng)}
		}
		if i < 0 || int(i) >= coll.Len() {
			return UnknownVal, Diagnostics{errDiag("Invalid index", "The given key does not identify an element in this collection value.", rng)}
		}
		return coll.Elements()[i], nil
	case KindObject:
		k, err := Convert(key, &TypeConstraint{Kind: KindString})
		if err != nil {
			return UnknownVal, Diagnostics{errDiag("Invalid index", "The given key does not identify an element in this collection value: string required.", rng)}
		}
		if v, ok := coll.Get(k.AsString()); ok {
			return v, nil
		}
		return UnknownVal, Diagnostics{errDiag("Invalid index", "The given key does not identify an element in this collection value.", rng)}
	case KindRef:
		k, _ := Convert(key, &TypeConstraint{Kind: KindString})
		return RefVal(fmt.Sprintf("%s[%q]", coll.Ref().Path, k.AsString())), nil
	}
	return UnknownVal, Diagnostics{errDiag("Invalid index", "This value does not have any indices.", rng)}
}

func evalFunctionCall(e *FunctionCallExpr, ctx *EvalContext) (Value, Diagnostics) {
	f, ok := ctx.lookupFunc(e.Name)
	if !ok {
		suggestion := nameSuggestion(e.Name, ctx.allFuncNames())
		if suggestion != "" {
			suggestion = fmt.Sprintf(" Did you mean %q?", suggestion)
		}
		return UnknownVal, Diagnostics{errDiag("Call to unknown function", fmt.Sprintf("There is no function named %q.%s", e.Name, suggestion), e.NameRange)}
	}
	var diags Diagnostics
	args := e.Args
	argVals := make([]Value, 0, len(args))
	if e.ExpandFinal && len(args) > 0 {
		expandExpr := args[len(args)-1]
		expandVal, d := Eval(expandExpr, ctx)
		diags = diags.Extend(d)
		if d.HasErrors() {
			return UnknownVal, diags
		}
		if expandVal.Kind() != KindTuple && expandVal.Kind() != KindObject {
			return UnknownVal, diags.Append(errDiag("Invalid expanding argument value", "The expanding argument (indicated by ...) must be of a tuple, list, or set type.", expandExpr.Range()))
		}
		newArgs := make([]Expression, 0, len(args)-1+expandVal.Len())
		newArgs = append(newArgs, args[:len(args)-1]...)
		if expandVal.Kind() == KindTuple {
			for _, el := range expandVal.Elements() {
				newArgs = append(newArgs, &LiteralValueExpr{Val: el, SrcRange: expandExpr.Range()})
			}
		} else {
			for _, k := range expandVal.Keys() {
				el, _ := expandVal.Get(k)
				newArgs = append(newArgs, &LiteralValueExpr{Val: el, SrcRange: expandExpr.Range()})
			}
		}
		args = newArgs
	}
	if len(args) < len(f.Params) {
		missing := f.Params[len(args)]
		qual := ""
		if f.VarParam != nil {
			qual = " at least"
		}
		return UnknownVal, diags.Append(errDiag("Not enough function arguments",
			fmt.Sprintf("Function %q expects%s %d argument(s). Missing value for %q.", e.Name, qual, len(f.Params), missing.Name), e.CloseParenRange))
	}
	if f.VarParam == nil && len(args) > len(f.Params) {
		return UnknownVal, diags.Append(errDiag("Too many function arguments",
			fmt.Sprintf("Function %q expects only %d argument(s).", e.Name, len(f.Params)), args[len(f.Params)].StartRange()))
	}
	for i, argExpr := range args {
		var param *Param
		if i < len(f.Params) {
			param = &f.Params[i]
		} else {
			param = f.VarParam
		}
		val, d := Eval(argExpr, ctx)
		diags = diags.Extend(d)
		if d.HasErrors() {
			continue
		}
		if !val.IsKnown() {
			argVals = append(argVals, val)
			continue
		}
		if val.IsNull() && !param.AllowNull {
			diags = diags.Append(errDiag("Invalid function argument", fmt.Sprintf("Invalid value for %q parameter: argument must not be null.", param.Name), argExpr.StartRange()))
			continue
		}
		if !param.AllowAny && !val.IsNull() {
			cv, err := Convert(val, param.Type)
			if err != nil {
				diags = diags.Append(errDiag("Invalid function argument", fmt.Sprintf("Invalid value for %q parameter: %s.", param.Name, err.Error()), argExpr.StartRange()))
				continue
			}
			val = cv
		}
		argVals = append(argVals, val)
	}
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	for _, v := range argVals {
		if !v.IsKnown() {
			return UnknownVal, diags
		}
	}
	result, err := f.Impl(argVals)
	if err != nil {
		if ae, ok := err.(*ArgError); ok {
			idx := ae.Index
			var rng Range
			if idx < len(args) {
				rng = args[idx].StartRange()
			} else {
				rng = e.Range()
			}
			name := "..."
			if idx < len(f.Params) {
				name = f.Params[idx].Name
			} else if f.VarParam != nil {
				name = f.VarParam.Name
			}
			return UnknownVal, diags.Append(errDiag("Invalid function argument", fmt.Sprintf("Invalid value for %q parameter: %s.", name, ae.Err.Error()), rng))
		}
		return UnknownVal, diags.Append(errDiag("Error in function call", fmt.Sprintf("Call to function %q failed: %s.", e.Name, err.Error()), e.StartRange()))
	}
	return result, diags
}

// ArgError reports a problem with a specific function argument.
type ArgError struct {
	Index int
	Err   error
}

func (e *ArgError) Error() string { return e.Err.Error() }

func evalConditional(e *ConditionalExpr, ctx *EvalContext) (Value, Diagnostics) {
	cond, diags := Eval(e.Condition, ctx)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if !cond.IsKnown() {
		return UnknownVal, diags
	}
	if cond.IsNull() {
		return UnknownVal, diags.Append(errDiag("Null condition", "The condition value is null. Conditions must either be true or false.", e.Condition.Range()))
	}
	cb, err := Convert(cond, &TypeConstraint{Kind: KindBool})
	if err != nil {
		return UnknownVal, diags.Append(errDiag("Incorrect condition type", fmt.Sprintf("The condition expression must be of type bool, but was %s.", cond.TypeName()), e.Condition.Range()))
	}
	trueV, td := Eval(e.TrueResult, ctx)
	falseV, fd := Eval(e.FalseResult, ctx)
	diags = diags.Extend(td).Extend(fd)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	// Unify primitive result types the way cty does.
	if trueV.Kind() != falseV.Kind() && isPrimitive(trueV) && isPrimitive(falseV) {
		tv, err1 := Convert(trueV, &TypeConstraint{Kind: KindString})
		fv, err2 := Convert(falseV, &TypeConstraint{Kind: KindString})
		if err1 == nil && err2 == nil {
			trueV, falseV = tv, fv
		}
	}
	if cb.True() {
		return trueV, diags
	}
	return falseV, diags
}

func isPrimitive(v Value) bool {
	switch v.Kind() {
	case KindString, KindNumber, KindBool:
		return true
	}
	return false
}

func evalBinaryOp(e *BinaryOpExpr, ctx *EvalContext) (Value, Diagnostics) {
	lhs, diags := Eval(e.LHS, ctx)
	rhs, rd := Eval(e.RHS, ctx)
	diags = diags.Extend(rd)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if !lhs.IsKnown() || !rhs.IsKnown() {
		return UnknownVal, diags
	}
	switch e.Op {
	case TokenEqualOp:
		return BoolVal(lhs.Equals(rhs)), diags
	case TokenNotEqual:
		return BoolVal(!lhs.Equals(rhs)), diags
	case TokenAnd, TokenOr:
		lb, err := Convert(lhs, &TypeConstraint{Kind: KindBool})
		if err != nil || lhs.IsNull() {
			return UnknownVal, diags.Append(errDiag("Invalid operand", "Unsuitable value for left operand: bool required.", e.LHS.Range()))
		}
		rb, err := Convert(rhs, &TypeConstraint{Kind: KindBool})
		if err != nil || rhs.IsNull() {
			return UnknownVal, diags.Append(errDiag("Invalid operand", "Unsuitable value for right operand: bool required.", e.RHS.Range()))
		}
		if e.Op == TokenAnd {
			return BoolVal(lb.True() && rb.True()), diags
		}
		return BoolVal(lb.True() || rb.True()), diags
	}
	// Numeric operators.
	ln, err := Convert(lhs, &TypeConstraint{Kind: KindNumber})
	if err != nil || lhs.IsNull() {
		return UnknownVal, diags.Append(errDiag("Invalid operand", "Unsuitable value for left operand: a number is required.", e.LHS.Range()))
	}
	rn, err := Convert(rhs, &TypeConstraint{Kind: KindNumber})
	if err != nil || rhs.IsNull() {
		return UnknownVal, diags.Append(errDiag("Invalid operand", "Unsuitable value for right operand: a number is required.", e.RHS.Range()))
	}
	a, b := ln.AsBigFloat(), rn.AsBigFloat()
	switch e.Op {
	case TokenPlus:
		return NumberVal(new(big.Float).SetPrec(512).Add(a, b)), diags
	case TokenMinus:
		return NumberVal(new(big.Float).SetPrec(512).Sub(a, b)), diags
	case TokenStar:
		return NumberVal(new(big.Float).SetPrec(512).Mul(a, b)), diags
	case TokenSlash:
		if b.Sign() == 0 {
			return UnknownVal, diags.Append(errDiag("Operation failed", "Error during operation: attempt to divide by zero.", e.Range()))
		}
		return NumberVal(new(big.Float).SetPrec(512).Quo(a, b)), diags
	case TokenPercent:
		if b.Sign() == 0 {
			return UnknownVal, diags.Append(errDiag("Operation failed", "Error during operation: attempt to divide by zero.", e.Range()))
		}
		q := new(big.Float).SetPrec(512).Quo(a, b)
		qi, _ := q.Int(nil)
		qf := new(big.Float).SetPrec(512).SetInt(qi)
		return NumberVal(new(big.Float).SetPrec(512).Sub(a, new(big.Float).SetPrec(512).Mul(qf, b))), diags
	case TokenGreaterThan:
		return BoolVal(a.Cmp(b) > 0), diags
	case TokenGreaterThanEq:
		return BoolVal(a.Cmp(b) >= 0), diags
	case TokenLessThan:
		return BoolVal(a.Cmp(b) < 0), diags
	case TokenLessThanEq:
		return BoolVal(a.Cmp(b) <= 0), diags
	}
	return UnknownVal, diags.Append(errDiag("Unsupported operator", "The operator is not supported.", e.Range()))
}

func evalUnaryOp(e *UnaryOpExpr, ctx *EvalContext) (Value, Diagnostics) {
	v, diags := Eval(e.Val, ctx)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if !v.IsKnown() {
		return UnknownVal, diags
	}
	switch e.Op {
	case TokenMinus:
		n, err := Convert(v, &TypeConstraint{Kind: KindNumber})
		if err != nil || v.IsNull() {
			return UnknownVal, diags.Append(errDiag("Invalid operand", "Unsuitable value for unary operand: a number is required.", e.Val.Range()))
		}
		return NumberVal(new(big.Float).SetPrec(512).Neg(n.AsBigFloat())), diags
	case TokenBang:
		b, err := Convert(v, &TypeConstraint{Kind: KindBool})
		if err != nil || v.IsNull() {
			return UnknownVal, diags.Append(errDiag("Invalid operand", "Unsuitable value for unary operand: bool required.", e.Val.Range()))
		}
		return BoolVal(!b.True()), diags
	}
	return UnknownVal, diags
}

func evalFor(e *ForExpr, ctx *EvalContext) (Value, Diagnostics) {
	coll, diags := Eval(e.CollExpr, ctx)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if !coll.IsKnown() {
		return UnknownVal, diags
	}
	if coll.IsNull() {
		return UnknownVal, diags.Append(errDiag("Iteration over null value", "A null value cannot be used as the collection in a 'for' expression.", e.CollExpr.Range()))
	}
	type kv struct {
		k Value
		v Value
	}
	var items []kv
	switch coll.Kind() {
	case KindTuple:
		for i, el := range coll.Elements() {
			items = append(items, kv{NumberIntVal(int64(i)), el})
		}
	case KindObject:
		for _, k := range coll.Keys() {
			v, _ := coll.Get(k)
			items = append(items, kv{StringVal(k), v})
		}
	default:
		return UnknownVal, diags.Append(errDiag("Iteration over non-iterable value", fmt.Sprintf("A value of type %s cannot be used as the collection in a 'for' expression.", coll.TypeName()), e.CollExpr.Range()))
	}
	child := ctx.NewChild()
	child.Variables = map[string]Value{}
	if e.KeyExpr != nil {
		keys := []string{}
		m := map[string]Value{}
		groups := map[string][]Value{}
		for _, it := range items {
			if e.KeyVar != "" {
				child.Variables[e.KeyVar] = it.k
			}
			child.Variables[e.ValVar] = it.v
			if e.CondExpr != nil {
				c, d := Eval(e.CondExpr, child)
				diags = diags.Extend(d)
				if d.HasErrors() {
					return UnknownVal, diags
				}
				cb, err := Convert(c, &TypeConstraint{Kind: KindBool})
				if err != nil || c.IsNull() {
					return UnknownVal, diags.Append(errDiag("Invalid 'for' condition", "The value of the 'if' clause must be a boolean.", e.CondExpr.Range()))
				}
				if !cb.True() {
					continue
				}
			}
			k, d := Eval(e.KeyExpr, child)
			diags = diags.Extend(d)
			if d.HasErrors() {
				return UnknownVal, diags
			}
			ks, err := Convert(k, &TypeConstraint{Kind: KindString})
			if err != nil || k.IsNull() {
				return UnknownVal, diags.Append(errDiag("Invalid object key", "Key expression in a 'for' expression must be a string.", e.KeyExpr.Range()))
			}
			v, d := Eval(e.ValExpr, child)
			diags = diags.Extend(d)
			if d.HasErrors() {
				return UnknownVal, diags
			}
			if e.Group {
				if _, ok := groups[ks.AsString()]; !ok {
					keys = append(keys, ks.AsString())
				}
				groups[ks.AsString()] = append(groups[ks.AsString()], v)
				continue
			}
			if _, exists := m[ks.AsString()]; exists {
				return UnknownVal, diags.Append(errDiag("Duplicate object key", fmt.Sprintf("Two different items produced the key %q in this 'for' expression. If duplicates are expected, use the ellipsis (...) after the value expression to enable grouping by key.", ks.AsString()), e.KeyExpr.Range()))
			}
			keys = append(keys, ks.AsString())
			m[ks.AsString()] = v
		}
		if e.Group {
			for k, vs := range groups {
				m[k] = TupleVal(vs)
			}
		}
		return ObjectVal(keys, m), diags
	}
	var vals []Value
	for _, it := range items {
		if e.KeyVar != "" {
			child.Variables[e.KeyVar] = it.k
		}
		child.Variables[e.ValVar] = it.v
		if e.CondExpr != nil {
			c, d := Eval(e.CondExpr, child)
			diags = diags.Extend(d)
			if d.HasErrors() {
				return UnknownVal, diags
			}
			cb, err := Convert(c, &TypeConstraint{Kind: KindBool})
			if err != nil || c.IsNull() {
				return UnknownVal, diags.Append(errDiag("Invalid 'for' condition", "The value of the 'if' clause must be a boolean.", e.CondExpr.Range()))
			}
			if !cb.True() {
				continue
			}
		}
		v, d := Eval(e.ValExpr, child)
		diags = diags.Extend(d)
		if d.HasErrors() {
			return UnknownVal, diags
		}
		vals = append(vals, v)
	}
	return TupleVal(vals), diags
}

func evalSplat(e *SplatExpr, ctx *EvalContext) (Value, Diagnostics) {
	src, diags := Eval(e.Source, ctx)
	if diags.HasErrors() {
		return UnknownVal, diags
	}
	if !src.IsKnown() {
		return UnknownVal, diags
	}
	var items []Value
	switch src.Kind() {
	case KindNull:
		return TupleVal(nil), diags
	case KindTuple:
		items = src.Elements()
	default:
		items = []Value{src}
	}
	var out []Value
	for _, it := range items {
		v := it
		e.Item.val = &v
		r, d := Eval(e.Each, ctx)
		e.Item.val = nil
		diags = diags.Extend(d)
		if d.HasErrors() {
			return UnknownVal, diags
		}
		out = append(out, r)
	}
	return TupleVal(out), diags
}
