func regexResult(re *regexp.Regexp, m []string) Value {
	names := re.SubexpNames()
	hasNamed := false
	for _, n := range names {
		if n != "" {
			hasNamed = true
		}
	}
	if len(m) == 1 {
		return StringVal(m[0])
	}
	if hasNamed {
		keys := []string{}
		obj := map[string]Value{}
		for i, n := range names {
			if i == 0 || n == "" {
				continue
			}
			keys = append(keys, n)
			obj[n] = StringVal(m[i])
		}
		return ObjectVal(keys, obj)
	}
	out := make([]Value, 0, len(m)-1)
	for _, s := range m[1:] {
		out = append(out, StringVal(s))
	}
	return ListVal(out)
}

func valueToInterface(v Value) interface{} {
	switch v.Kind() {
	case KindNull:
		return nil
	case KindBool:
		return v.True()
	case KindNumber:
		f := v.AsBigFloat()
		if f.IsInt() {
			i, _ := f.Int64()
			return i
		}
		x, _ := f.Float64()
		return x
	case KindString:
		return v.AsString()
	case KindTuple:
		out := make([]interface{}, 0, v.Len())
		for _, e := range v.Elements() {
			out = append(out, valueToInterface(e))
		}
		return out
	case KindObject:
		out := make(map[string]interface{}, v.Len())
		for _, k := range v.Keys() {
			e, _ := v.Get(k)
			out[k] = valueToInterface(e)
		}
		return out
	case KindRef:
		return v.Ref().Path
	}
	return nil
}

func interfaceToValue(x interface{}) Value {
	switch t := x.(type) {
	case nil:
		return NullVal
	case bool:
		return BoolVal(t)
	case json.Number:
		v, err := ParseNumberVal(t.String())
		if err != nil {
			return NullVal
		}
		return v
	case float64:
		return NumberFloatVal(t)
	case string:
		return StringVal(t)
	case []interface{}:
		out := make([]Value, len(t))
		for i, e := range t {
			out[i] = interfaceToValue(e)
		}
		return TupleVal(out)
	case map[string]interface{}:
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		m := make(map[string]Value, len(t))
		for k, e := range t {
			m[k] = interfaceToValue(e)
		}
		return ObjectVal(keys, m)
	}
	return NullVal
}

// formatValues implements the format function with cty-like verbs.
func formatValues(format string, args []Value) (string, error) {
	var b strings.Builder
	argIdx := 0
	for i := 0; i < len(format); i++ {
		c := format[i]
		if c != '%' {
			b.WriteByte(c)
			continue
		}
		if i+1 < len(format) && format[i+1] == '%' {
			b.WriteByte('%')
			i++
			continue
		}
		// Parse verb: flags, width, precision, verb.
		j := i + 1
		for j < len(format) && strings.IndexByte("+-# 0123456789.*[]", format[j]) >= 0 {
			j++
		}
		if j >= len(format) {
			return "", errors.New("unterminated format verb")
		}
		verb := format[j]
		spec := format[i:j]
		if argIdx >= len(args) {
			return "", fmt.Errorf("not enough arguments for %q at %d: need index %d but have %d total", format[i:j+1], i, argIdx+1, len(args))
		}
		arg := args[argIdx]
		argIdx++
		switch verb {
		case 'v':
			if arg.IsNull() {
				b.WriteString("null")
			} else {
				b.WriteString(formatGeneric(arg))
			}
		case 's':
			s, err := Convert(arg, tString)
			if err != nil {
				return "", fmt.Errorf("unsupported value for %q at %d: %s", format[i:j+1], i, err.Error())
			}
			b.WriteString(fmt.Sprintf(spec+"s", s.AsString()))
		case 'q':
			s, err := Convert(arg, tString)
			if err != nil {
				return "", fmt.Errorf("unsupported value for %q at %d: %s", format[i:j+1], i, err.Error())
			}
			b.WriteString(fmt.Sprintf(spec+"q", s.AsString()))
		case 'd':
			n, err := Convert(arg, tNumber)
			if err != nil {
				return "", fmt.Errorf("unsupported value for %q at %d: %s", format[i:j+1], i, err.Error())
			}
			iv, _ := n.AsBigFloat().Int(nil)
			b.WriteString(fmt.Sprintf(spec+"d", iv))
		case 'f', 'e', 'g', 'E', 'G':
			n, err := Convert(arg, tNumber)
			if err != nil {
				return "", fmt.Errorf("unsupported value for %q at %d: %s", format[i:j+1], i, err.Error())
			}
			b.WriteString(fmt.Sprintf(spec+string(verb), n.AsFloat64()))
		case 't':
			bv, err := Convert(arg, tBool)
			if err != nil {
				return "", fmt.Errorf("unsupported value for %q at %d: %s", format[i:j+1], i, err.Error())
			}
			b.WriteString(fmt.Sprintf(spec+"t", bv.True()))
		case 'x', 'X', 'o', 'b':
			n, err := Convert(arg, tNumber)
			if err != nil {
				return "", fmt.Errorf("unsupported value for %q at %d: %s", format[i:j+1], i, err.Error())
			}
			iv, _ := n.AsBigFloat().Int(nil)
			b.WriteString(fmt.Sprintf(spec+string(verb), iv))
		default:
			return "", fmt.Errorf("unsupported format verb %q in %q at offset %d", string(verb), format[i:j+1], i)
		}
		i = j
	}
	if argIdx < len(args) {
		return "", fmt.Errorf("too many arguments; no verbs in format string to use the last %d", len(args)-argIdx)
	}
	return b.String(), nil
}

func formatGeneric(v Value) string {
	switch v.Kind() {
	case KindString:
		return strconv.Quote(v.AsString())
	default:
		return v.GoString()
	}
}
