	u, err := url.Parse(rawURL)
	if err != nil {
		return NullVal, err
	}
	if pass != "" {
		u.User = url.UserPassword(user, pass)
	} else {
		u.User = url.User(user)
	}
	return StringVal(u.String()), nil
}

