package hcl

import (
	"net/url"
	"time"
)

func urlQueryEscape(s string) string { return url.QueryEscape(s) }

func urlQuerySet(rawURL, key, value string) (Value, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return NullVal, err
	}
	q := u.Query()
	q.Set(key, value)
	u.RawQuery = q.Encode()
	return StringVal(u.String()), nil
}

func urlSetPath(rawURL, path string) (Value, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return NullVal, err
	}
	u.Path = path
	return StringVal(u.String()), nil
}

func urlUserInfo(rawURL, user, pass string) (Value, error) {
	u, err := url.Parse(rawURL)
	if err != nil {
		return NullVal, err
	}
	if pass != "" {
		u.User = url.UserPassword(user, pass)
	} else {
		u.User = url.User(user)
	}
	return StringVal(u.String()), nil
}

func nowUTC() string { return time.Now().UTC().Format(time.RFC3339) }
