// ParseTypeConstraint interprets an expression as a type constraint such as
// string, number, bool, list(string), map(number) or object({...}).
func ParseTypeConstraint(expr Expression) (*TypeConstraint, Diagnostics) {
	switch e := expr.(type) {
	case *ScopeTraversalExpr:
		if len(e.Traversal) != 1 {
			break
		}
		switch e.Traversal.RootName() {
		case "string":
			return &TypeConstraint{Kind: KindString}, nil
		case "number":
			return &TypeConstraint{Kind: KindNumber}, nil
		case "bool":
			return &TypeConstraint{Kind: KindBool}, nil
		case "any":
			return &TypeConstraint{Kind: KindNull}, nil
		case "list", "set", "map", "object", "tuple":
			return nil, Diagnostics{errDiag("Invalid type specification", fmt.Sprintf("The %s type constructor requires one argument specifying the element type.", e.Traversal.RootName()), e.Range())}
		default:
			return nil, Diagnostics{errDiag("Invalid type specification", fmt.Sprintf("The keyword %q is not a valid type specification.", e.Traversal.RootName()), e.Range())}
		}
	case *FunctionCallExpr:
		switch e.Name {
		case "list", "set", "map":
			if len(e.Args) != 1 {
				return nil, Diagnostics{errDiag("Invalid type specification", fmt.Sprintf("The %s type constructor requires one argument specifying the element type.", e.Name), e.Range())}
			}
			elem, diags := ParseTypeConstraint(e.Args[0])
			if diags.HasErrors() {
				return nil, diags
			}
			switch e.Name {
			case "list":
				return &TypeConstraint{Kind: KindTuple, Elem: elem}, nil
			case "set":
				return &TypeConstraint{Kind: KindTuple, Elem: elem, Set: true}, nil
			default:
				return &TypeConstraint{Kind: KindObject, Elem: elem}, nil
			}
		case "object":
			if len(e.Args) != 1 {
				return nil, Diagnostics{errDiag("Invalid type specification", "The object type constructor requires one argument specifying the attribute types and values as a map.", e.Range())}
			}
			oc, ok := e.Args[0].(*ObjectConsExpr)
			if !ok {
				return nil, Diagnostics{errDiag("Invalid type specification", "Object type constructor requires a map whose keys are attribute names and whose values are the corresponding attribute types.", e.Args[0].Range())}
			}
			attrs := map[string]*TypeConstraint{}
			for _, item := range oc.Items {
				k, diags := evalObjectKey(item.KeyExpr, &EvalContext{})
				if diags.HasErrors() {
					return nil, diags
				}
				t, diags := ParseTypeConstraint(item.ValueExpr)
				if diags.HasErrors() {
					return nil, diags
				}
				attrs[k] = t
			}
			return &TypeConstraint{Kind: KindObject, Attrs: attrs}, nil
		case "tuple":
			return &TypeConstraint{Kind: KindTuple, Elem: &TypeConstraint{Kind: KindNull}}, nil
		default:
			return nil, Diagnostics{errDiag("Invalid type specification", fmt.Sprintf("Keyword %q is not a valid type constructor.", e.Name), e.Range())}
		}
	}
	return nil, Diagnostics{errDiag("Invalid type specification", "A type specification is either a primitive type keyword (bool, number, string) or a complex type constructor call, like list(string).", expr.Range())}
}
