func configPath(configURL string) (string, error) {
	u, err := url.Parse(configURL)
	if err != nil {
		return "", fmt.Errorf("parse config url: %w", err)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported config file driver %q", u.Scheme)
	}
	p := filepath.Join(u.Host, u.Path)
	if p == "" {
		p = "atlas.hcl"
	}
	return p, nil
}

// Parse parses and evaluates the project file.
func Parse(src []byte, filename, envName string, vars map[string][]string) (*Project, error) {
	file, diags := hcl.ParseConfig(src, filepath.Base(filename))
	if diags.HasErrors() {
		return nil, diags
	}
	baseDir, _ := filepath.Abs(filepath.Dir(filename))
	ctx := &hcl.EvalContext{
		Variables: map[string]hcl.Value{
			"atlas": hcl.ObjectVal([]string{"env"}, map[string]hcl.Value{"env": hcl.StringVal(envName)}),
		},
		Functions: hcl.StdFunctions(baseDir),
	}
	ev := &Evaluator{File: file, Ctx: ctx}
	if err := ev.SetVariables(vars); err != nil {
		return nil, err
	}
	if err := ev.SetLocals(); err != nil {
		return nil, err
	}
	proj := &Project{}
	for _, blk := range file.Body.Blocks {
		switch blk.Type {
		case "env":
			env, err := ev.evalEnv(blk, envName)
			if err != nil {
				return nil, err
			}
			if env != nil {
				proj.Envs = append(proj.Envs, env)
			}
		case "lint":
			l, err := ev.evalLint(blk)
			if err != nil {
				return nil, err
			}
			proj.Lint = l
		case "diff":
			d, err := ev.evalDiff(blk)
			if err != nil {
				return nil, err
			}
			proj.Diff = d
		}
	}
	// Inherit project-level settings.
	for _, e := range proj.Envs {
		if !e.Lint.HasBlock {
			e.Lint = proj.Lint
		}
		if e.Diff.SkipDestructive == nil && e.Diff.ConcurrentIndex == nil {
			e.Diff = proj.Diff
		}
	}
	return proj, nil
}

// Evaluator evaluates the blocks of a project/schema file.
type Evaluator struct {
	File *hcl.File
	Ctx  *hcl.EvalContext
}

// SetVariables evaluates the variable blocks and sets var.* in the context.
func (ev *Evaluator) SetVariables(input map[string][]string) error {
	vals := map[string]hcl.Value{}
	keys := []string{}
	for _, blk := range ev.File.Body.BlocksOfType("variable") {
		if len(blk.Labels) != 1 {
			return fmt.Errorf("variable block must have exactly one label")
		}
		name := blk.Labels[0]
		var tc *hcl.TypeConstraint
		if a := blk.Body.Attribute("type"); a != nil {
			var diags hcl.Diagnostics
			tc, diags = hcl.ParseTypeConstraint(a.Expr)
			if diags.HasErrors() {
				return diags
			}
		}
		var v hcl.Value
		if in, ok := input[name]; ok {
			if len(in) == 1 {
				v = hcl.StringVal(in[0])
			} else {
				els := make([]hcl.Value, len(in))
				for i, s := range in {
					els[i] = hcl.StringVal(s)
				}
				v = hcl.ListVal(els)
			}
		} else if a := blk.Body.Attribute("default"); a != nil {
			dv, diags := hcl.Eval(a.Expr, ev.Ctx)
			if diags.HasErrors() {
				return diags
			}
			if dv.IsNull() {
				return fmt.Errorf("missing value for required variable %q", name)
			}
			v = dv
		} else {
			return fmt.Errorf("missing value for required variable %q", name)
		}
		cv, err := hcl.Convert(v, tc)
		if err != nil {
			return fmt.Errorf("variable %q: %w", name, err)
		}
		if _, ok := vals[name]; !ok {
			keys = append(keys, name)
		}
		vals[name] = cv
	}
	ev.Ctx.Variables["var"] = hcl.ObjectVal(keys, vals)
	return nil
}

// SetLocals evaluates the locals blocks lazily and sets local.* in the context.
func (ev *Evaluator) SetLocals() error {
	attrs := map[string]*hcl.Attribute{}
	var names []string
	for _, blk := range ev.File.Body.BlocksOfType("locals") {
		for _, a := range blk.Body.Attributes {
			if _, ok := attrs[a.Name]; ok {
				return fmt.Errorf("duplicate local %q", a.Name)
			}
			attrs[a.Name] = a
			names = append(names, a.Name)
		}
	}
	if len(attrs) == 0 {
		return nil
	}
	vals := map[string]hcl.Value{}
	visiting := map[string]bool{}
	var evalLocal func(name string) (hcl.Value, hcl.Diagnostics)
	// A child context that resolves local.* references lazily.
	localCtx := ev.Ctx.NewChild()
	localCtx.ResolveRef = func(trav hcl.Traversal, _ *hcl.EvalContext) (hcl.Value, hcl.Diagnostics, bool) {
		if trav.RootName() != "local" {
			return hcl.NullVal, nil, false
		}
		if len(trav) < 2 {
			return hcl.NullVal, hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Invalid local reference", Detail: "A local reference must have the form local.<name>.", Subject: trav[0].Range().Ptr()}}, true
		}
		attr, ok := trav[1].(hcl.TraverseAttr)
		if !ok {
			return hcl.NullVal, hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Invalid local reference", Detail: "A local reference must have the form local.<name>.", Subject: trav[1].Range().Ptr()}}, true
		}
		v, diags := evalLocal(attr.Name)
		if diags.HasErrors() {
			return hcl.NullVal, diags, true
		}
		if v.IsNull() && visiting[attr.Name] {
			return hcl.NullVal, diags, true
		}
		if _, exists := attrs[attr.Name]; !exists {
			return hcl.NullVal, hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Unsupported attribute", Detail: fmt.Sprintf("This object does not have an attribute named %q.", attr.Name), Subject: attr.SrcRange.Ptr()}}, true
		}
		// Apply the rest of the traversal.
		rest := trav[2:]
		if len(rest) == 0 {
			return v, nil, true
		}
		rv, rdiags := hcl.EvalTraversal(v, rest, ev.Ctx)
		return rv, rdiags, true
	}
	evalLocal = func(name string) (hcl.Value, hcl.Diagnostics) {
		if v, ok := vals[name]; ok {
			return v, nil
		}
		a, ok := attrs[name]
		if !ok {
			return hcl.NullVal, nil
		}
		if visiting[name] {
			return hcl.NullVal, hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Cyclic local reference", Detail: fmt.Sprintf("The local %q refers to itself.", name), Subject: a.NameRange.Ptr()}}
		}
		visiting[name] = true
		v, diags := hcl.Eval(a.Expr, localCtx)
		visiting[name] = false
		if diags.HasErrors() {
			return hcl.NullVal, diags
		}
		vals[name] = v
		return v, nil
	}
	for _, name := range names {
		if _, diags := evalLocal(name); diags.HasErrors() {
			return diags
		}
	}
	ev.Ctx.Variables["local"] = hcl.ObjectVal(names, vals)
	return nil
}

func (ev *Evaluator) evalAttrs(body *hcl.Body) (map[string]hcl.Value, error) {
	out := map[string]hcl.Value{}
	for _, a := range body.Attributes {
		v, diags := hcl.Eval(a.Expr, ev.Ctx)
		if diags.HasErrors() {
			return nil, diags
		}
		out[a.Name] = v
	}
	return out, nil
}

func attrString(attrs map[string]hcl.Value, name string) (string, bool, error) {
	v, ok := attrs[name]
	if !ok || v.IsNull() {
		return "", false, nil
	}
	switch v.Kind() {
	case hcl.KindString:
		return v.AsString(), true, nil
	case hcl.KindNumber, hcl.KindBool:
		s, _ := hcl.Convert(v, &hcl.TypeConstraint{Kind: hcl.KindString})
		return s.AsString(), true, nil
	}
	return "", false, fmt.Errorf("value of attr %q cannot be read as string: string value is required", name)
}

func attrStrings(attrs map[string]hcl.Value, name string) ([]string, bool, error) {
	v, ok := attrs[name]
	if !ok || v.IsNull() {
		return nil, false, nil
	}
	switch v.Kind() {
	case hcl.KindString:
		return []string{v.AsString()}, true, nil
	case hcl.KindTuple:
		out := make([]string, 0, v.Len())
		for _, e := range v.Elements() {
			if e.Kind() != hcl.KindString {
				return nil, false, fmt.Errorf("value of attr %q cannot be read as []string: string value is required", name)
			}
			out = append(out, e.AsString())
		}
		return out, true, nil
	}
	return nil, false, fmt.Errorf("value of attr %q cannot be read as []string: list value is required", name)
}

func (ev *Evaluator) evalEnv(blk *hcl.Block, envName string) (*Env, error) {
	attrs, err := ev.evalAttrs(blk.Body)
	if err != nil {
		return nil, err
	}
	env := &Env{Attrs: attrs}
	switch len(blk.Labels) {
	case 1:
		env.Name = blk.Labels[0]
	case 0:
		n, ok, err := attrString(attrs, "name")
		if err != nil {
			return nil, decodeErr(err)
		}
		if !ok {
			return nil, nil
		}
		env.Name = n
	default:
		return nil, nil
	}
	if env.URL, _, err = attrString(attrs, "url"); err != nil {
		return nil, decodeErr(err)
	}
	if env.DevURL, _, err = attrString(attrs, "dev"); err != nil {
		return nil, decodeErr(err)
	}
	if env.Schemas, _, err = attrStrings(attrs, "schemas"); err != nil {
		return nil, decodeErr(err)
	}
	if env.Exclude, _, err = attrStrings(attrs, "exclude"); err != nil {
		return nil, decodeErr(err)
	}
	if env.Srcs, _, err = attrStrings(attrs, "src"); err != nil {
		return nil, decodeErr(err)
	}
	for _, b := range blk.Body.Blocks {
		switch b.Type {
		case "migration":
			m, err := ev.evalAttrs(b.Body)
			if err != nil {
				return nil, err
			}
			for _, kv := range []struct {
				key string
				dst *string
			}{
				{"dir", &env.Migration.Dir}, {"format", &env.Migration.Format}, {"baseline", &env.Migration.Baseline},
				{"exec_order", &env.Migration.ExecOrder}, {"lock_timeout", &env.Migration.LockTimeout},
				{"revisions_schema", &env.Migration.RevisionsSchema},
			} {
				if *kv.dst, _, err = attrString(m, kv.key); err != nil {
					return nil, decodeErr(err)
				}
			}
		case "format":
			for _, fb := range b.Body.Blocks {
				m, err := ev.evalAttrs(fb.Body)
				if err != nil {
					return nil, err
				}
				strs := map[string]string{}
				for k := range m {
					s, _, err := attrString(m, k)
					if err != nil {
						return nil, decodeErr(err)
					}
					strs[k] = s
				}
				switch fb.Type {
				case "migrate":
					env.Format.Migrate = strs
				case "schema":
					env.Format.Schema = strs
				}
			}
		case "lint":
			l, err := ev.evalLint(b)
			if err != nil {
				return nil, err
			}
			env.Lint = l
		case "diff":
			d, err := ev.evalDiff(b)
			if err != nil {
				return nil, err
			}
			env.Diff = d
		}
	}
	return env, nil
}

func (ev *Evaluator) evalLint(blk *hcl.Block) (Lint, error) {
	l := Lint{HasBlock: true, Rules: map[string]bool{}}
	attrs, err := ev.evalAttrs(blk.Body)
	if err != nil {
		return l, err
	}
	if v, ok := attrs["latest"]; ok && v.Kind() == hcl.KindNumber {
		l.Latest, _ = v.AsInt64()
	}
	if s, _, err := attrString(attrs, "format"); err == nil {
		l.Format = s
	}
	for _, b := range blk.Body.Blocks {
		if b.Type == "git" {
			g, err := ev.evalAttrs(b.Body)
			if err != nil {
				return l, err
			}
			l.GitBase, _, _ = attrString(g, "base")
			l.GitDir, _, _ = attrString(g, "dir")
			continue
		}
		a, err := ev.evalAttrs(b.Body)
		if err != nil {
			return l, err
		}
		if v, ok := a["error"]; ok && v.Kind() == hcl.KindBool {
			l.Rules[b.Type] = v.True()
		} else {
			l.Rules[b.Type] = false
		}
	}
	return l, nil
}

func (ev *Evaluator) evalDiff(blk *hcl.Block) (Diff, error) {
	d := Diff{SkipDestructive: map[string]bool{}, ConcurrentIndex: map[string]bool{}}
	for _, b := range blk.Body.Blocks {
		a, err := ev.evalAttrs(b.Body)
		if err != nil {
			return d, err
		}
		switch b.Type {
		case "skip":
			for k, v := range a {
				d.SkipDestructive[k] = v.True()
			}
		case "concurrent_index":
			for k, v := range a {
				d.ConcurrentIndex[k] = v.True()
			}
		}
	}
	return d, nil
}

func decodeErr(err error) error {
	return fmt.Errorf("schemahcl: failed reading spec as *cmdapi.Project: %w", err)
}

// SplitSchemas splits a comma separated list of schema names.
func SplitSchemas(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}
