package cmdapi

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"

	"atlas/internal/hcl"

	"github.com/spf13/cobra"
)

type fmtTask struct {
	path string
	info os.FileInfo
}

func schemaFmtRun(cmd *cobra.Command, args []string) error {
	if len(args) == 0 {
		args = append(args, "./")
	}
	for _, path := range args {
		tasks, err := fmtTasks(path)
		if err != nil {
			return err
		}
		for _, t := range tasks {
			changed, err := fmtFile(t)
			if err != nil {
				return err
			}
			if changed {
				cmd.Println(t.path)
			}
		}
	}
	return nil
}

func fmtTasks(path string) ([]fmtTask, error) {
	var tasks []fmtTask
	stat, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if !stat.IsDir() {
		if strings.HasSuffix(path, ".hcl") {
			tasks = append(tasks, fmtTask{path: path, info: stat})
		}
		return tasks, nil
	}
	all, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	for _, f := range all {
		if f.IsDir() {
			continue
		}
		if strings.HasSuffix(f.Name(), ".hcl") {
			i, err := f.Info()
			if err != nil {
				return nil, err
			}
			tasks = append(tasks, fmtTask{path: filepath.Join(path, f.Name()), info: i})
		}
	}
	return tasks, nil
}

func fmtFile(t fmtTask) (bool, error) {
	orig, err := os.ReadFile(t.path)
	if err != nil {
		return false, err
	}
	formatted := hcl.Format(orig)
	if !bytes.Equal(formatted, orig) {
		return true, os.WriteFile(t.path, formatted, t.info.Mode())
	}
	return false, nil
}
