import "C"

import (
	"errors"
	"fmt"
	"strings"
	"unsafe"
)

// DB is an open database connection.
type DB struct {
	db *C.sqlite3
}

// Error is an error returned by SQLite.
type Error struct {
	Code int
	Msg  string
}

func (e *Error) Error() string { return e.Msg }

func (d *DB) lastError(rc C.int) error {
	msg := C.GoString(C.sqlite3_errmsg(d.db))
	return &Error{Code: int(rc), Msg: msg}
}

// Open opens (or creates) the database identified by the given URI/path.
func Open(uri string) (*DB, error) {
	var db *C.sqlite3
	cs := C.CString(uri)
	defer C.free(unsafe.Pointer(cs))
	flags := C.SQLITE_OPEN_READWRITE | C.SQLITE_OPEN_CREATE | C.SQLITE_OPEN_URI | C.SQLITE_OPEN_FULLMUTEX
	rc := C.sqlite3_open_v2(cs, &db, C.int(flags), nil)
	if rc != C.SQLITE_OK {
		msg := "unable to open database"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close_v2(db)
		}
		return nil, &Error{Code: int(rc), Msg: msg}
	}
	d := &DB{db: db}
	C.sqlite3_busy_timeout(db, 5000)
	return d, nil
}

// Close closes the connection.
func (d *DB) Close() error {
	if d.db == nil {
		return nil
	}
	rc := C.sqlite3_close_v2(d.db)
	d.db = nil
	if rc != C.SQLITE_OK {
		return &Error{Code: int(rc), Msg: "close failed"}
	}
	return nil
}

// Row is a result row.
type Row []interface{}

// Rows is a query result.
type Rows struct {
	Columns []string
	Rows    []Row
}

// Exec executes one or more SQL statements without returning rows.
func (d *DB) Exec(query string, args ...interface{}) error {
	if len(args) == 0 {
		cs := C.CString(query)
		defer C.free(unsafe.Pointer(cs))
		var errmsg *C.char
		rc := C.sqlite3_exec(d.db, cs, nil, nil, &errmsg)
		if rc != C.SQLITE_OK {
			msg := ""
			if errmsg != nil {
				msg = C.GoString(errmsg)
				C.sqlite3_free(unsafe.Pointer(errmsg))
			}
			return &Error{Code: int(rc), Msg: msg}
		}
		return nil
	}
	_, err := d.Query(query, args...)
	return err
}

// Query executes a statement and returns all rows.
func (d *DB) Query(query string, args ...interface{}) (*Rows, error) {
	cs := C.CString(query)
	defer C.free(unsafe.Pointer(cs))
	var stmt *C.sqlite3_stmt
	var tail *C.char
	rc := C.sqlite3_prepare_v2(d.db, cs, -1, &stmt, &tail)
	if rc != C.SQLITE_OK {
		return nil, d.lastError(rc)
	}
	if stmt == nil {
		return &Rows{}, nil
	}
	defer C.sqlite3_finalize(stmt)
	for i, a := range args {
		idx := C.int(i + 1)
		switch v := a.(type) {
		case nil:
			rc = C.sqlite3_bind_null(stmt, idx)
		case int:
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(v))
		case int64:
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(v))
		case bool:
			b := 0
			if v {
				b = 1
			}
			rc = C.sqlite3_bind_int64(stmt, idx, C.sqlite3_int64(b))
		case float64:
			rc = C.sqlite3_bind_double(stmt, idx, C.double(v))
		case string:
			s := C.CString(v)
			rc = C.bind_text(stmt, idx, s, C.int(len(v)))
			C.free(unsafe.Pointer(s))
		case []byte:
			if len(v) == 0 {
				rc = C.sqlite3_bind_zeroblob(stmt, idx, 0)
			} else {
				rc = C.bind_blob(stmt, idx, unsafe.Pointer(&v[0]), C.int(len(v)))
			}
		default:
			return nil, fmt.Errorf("unsupported bind type %T", a)
		}
		if rc != C.SQLITE_OK {
			return nil, d.lastError(rc)
		}
	}
	ncol := int(C.sqlite3_column_count(stmt))
	rows := &Rows{}
	for i := 0; i < ncol; i++ {
		rows.Columns = append(rows.Columns, C.GoString(C.sqlite3_column_name(stmt, C.int(i))))
	}
	for {
		rc = C.sqlite3_step(stmt)
		if rc == C.SQLITE_DONE {
			break
		}
		if rc != C.SQLITE_ROW {
			return nil, d.lastError(rc)
		}
		row := make(Row, ncol)
		for i := 0; i < ncol; i++ {
			ci := C.int(i)
			switch C.sqlite3_column_type(stmt, ci) {
			case C.SQLITE_INTEGER:
				row[i] = int64(C.sqlite3_column_int64(stmt, ci))
			case C.SQLITE_FLOAT:
				row[i] = float64(C.sqlite3_column_double(stmt, ci))
			case C.SQLITE_TEXT:
				n := C.sqlite3_column_bytes(stmt, ci)
				p := unsafe.Pointer(C.sqlite3_column_text(stmt, ci))
				row[i] = C.GoStringN((*C.char)(p), n)
			case C.SQLITE_BLOB:
				n := C.sqlite3_column_bytes(stmt, ci)
				p := C.sqlite3_column_blob(stmt, ci)
				if p == nil {
					row[i] = []byte{}
				} else {
					row[i] = C.GoBytes(p, n)
				}
			default:
				row[i] = nil
			}
		}
		rows.Rows = append(rows.Rows, row)
	}
	return rows, nil
}

// QueryString returns the first column of the first row as a string.
func (d *DB) QueryString(query string, args ...interface{}) (string, error) {
	rows, err := d.Query(query, args...)
	if err != nil {
		return "", err
	}
	if len(rows.Rows) == 0 || len(rows.Rows[0]) == 0 {
		return "", errors.New("no rows")
	}
	return ToString(rows.Rows[0][0]), nil
}

// ToString converts a column value to a string.
func ToString(v interface{}) string {
	switch t := v.(type) {
	case nil:
		return ""
	case string:
		return t
	case []byte:
		return string(t)
	case int64:
		return fmt.Sprintf("%d", t)
	case float64:
		return strings.TrimRight(strings.TrimRight(fmt.Sprintf("%f", t), "0"), ".")
	}
	return fmt.Sprint(v)
}

// ToInt converts a column value to an int64.
func ToInt(v interface{}) int64 {
	switch t := v.(type) {
	case int64:
		return t
	case float64:
		return int64(t)
	case string:
		var i int64
		fmt.Sscanf(t, "%d", &i)
		return i
	}
	return 0
}

// Version returns the SQLite library version.
func Version() string { return C.GoString(C.sqlite3_libversion()) }

// Changes returns the number of rows modified by the last statement.
func (d *DB) Changes() int64 { return int64(C.sqlite3_changes(d.db)) }
