// Package schema defines the database schema model shared by the drivers.
package schema

import (
	"fmt"
	"strings"
)

// Realm is a collection of schemas.
type Realm struct {
	Schemas []*Schema
}

// Schema is a database schema.
type Schema struct {
	Name   string
	Realm  *Realm
	Tables []*Table
	Attrs  []Attr
}

// Table is a database table.
type Table struct {
	Name        string
	Schema      *Schema
	Columns     []*Column
	Indexes     []*Index
	PrimaryKey  *Index
	ForeignKeys []*ForeignKey
	Attrs       []Attr
}

// Column is a table column.
type Column struct {
	Name        string
	Type        *ColumnType
	Default     Expr
	Attrs       []Attr
	Indexes     []*Index
	ForeignKeys []*ForeignKey
}

// ColumnType holds the type information of a column.
type ColumnType struct {
	Type Type
	Raw  string
	Null bool
}

// Index is a table index (or primary key).
type Index struct {
	Name   string
	Unique bool
	Table  *Table
	Attrs  []Attr
	Parts  []*IndexPart
}

// IndexPart is a column or expression part of an index.
type IndexPart struct {
	SeqNo int
	Desc  bool
	C     *Column
	X     Expr
	Attrs []Attr
}

// ForeignKey is a foreign key constraint.
type ForeignKey struct {
	Symbol     string
	Table      *Table
	Columns    []*Column
	RefTable   *Table
	RefColumns []*Column
	OnUpdate   ReferenceOption
	OnDelete   ReferenceOption
}

// ReferenceOption is a foreign key action.
type ReferenceOption string

// Reference options.
const (
	NoAction   ReferenceOption = "NO ACTION"
	Restrict   ReferenceOption = "RESTRICT"
	Cascade    ReferenceOption = "CASCADE"
	SetNull    ReferenceOption = "SET NULL"
	SetDefault ReferenceOption = "SET DEFAULT"
)

// Expr is a column default or index expression.
type Expr interface{ expr() }

// Literal is a literal value expression (e.g. 1, 'a').
type Literal struct{ V string }

// RawExpr is a raw SQL expression.
type RawExpr struct{ X string }

func (*Literal) expr() {}
func (*RawExpr) expr() {}

// Attr is a schema element attribute.
type Attr interface{ attr() }

// Comment is a comment attribute.
type Comment struct{ Text string }

// Check is a check constraint.
type Check struct {
	Name  string
	Expr  string
	Attrs []Attr
}

// Collation is a collation attribute.
type Collation struct{ V string }

// Charset is a charset attribute.
type Charset struct{ V string }

// GeneratedExpr is a generated column expression.
type GeneratedExpr struct {
	Expr string
	Type string // STORED or VIRTUAL
}

// IndexPredicate is a partial index predicate.
type IndexPredicate struct{ P string }

func (*Comment) attr()        {}
func (*Check) attr()          {}
func (*Collation) attr()      {}
func (*Charset) attr()        {}
func (*GeneratedExpr) attr()  {}
func (*IndexPredicate) attr() {}

// Type is a column type.
type Type interface{ typ() }

// Column types.
type (
	BoolType struct{ T string }
	BinaryType struct {
		T    string
		Size *int
	}
	IntegerType struct {
		T        string
		Unsigned bool
	}
	StringType struct {
		T    string
		Size int
	}
	FloatType struct {
		T         string
		Precision int
	}
	DecimalType struct {
		T         string
		Precision int
		Scale     int
	}
	TimeType struct {
		T         string
		Precision *int
	}
	JSONType struct{ T string }
	UUIDType struct{ T string }
	EnumType struct {
		T      string
		Values []string
	}
	UnsupportedType struct{ T string }
)

func (*BoolType) typ()        {}
func (*BinaryType) typ()      {}
func (*IntegerType) typ()     {}
func (*StringType) typ()      {}
func (*FloatType) typ()       {}
func (*DecimalType) typ()     {}
func (*TimeType) typ()        {}
func (*JSONType) typ()        {}
func (*UUIDType) typ()        {}
func (*EnumType) typ()        {}
func (*UnsupportedType) typ() {}

// New returns a new realm.
func New(schemas ...*Schema) *Realm {
	r := &Realm{}
	for _, s := range schemas {
		s.Realm = r
		r.Schemas = append(r.Schemas, s)
	}
	return r
}

// NewSchema returns a new schema.
func NewSchema(name string) *Schema { return &Schema{Name: name} }

// AddTables adds tables to the schema.
