package sqlite

import (
	"fmt"
	"net/url"
	"strings"

	"atlas/internal/schema"
	"atlas/internal/sqlite3"
)

// Attributes specific to SQLite.
type (
	// WithoutRowID marks a table as WITHOUT ROWID.
	WithoutRowID struct{}
	// Strict marks a table as STRICT.
	Strict struct{}
	// AutoIncrement marks a column as AUTOINCREMENT.
	AutoIncrement struct{ Seq int64 }
	// IndexOrigin holds the origin of an index (c, u or pk).
	IndexOrigin struct{ O string }
)

func (*WithoutRowID) attr()  {}
func (*Strict) attr()        {}
func (*AutoIncrement) attr() {}
func (*IndexOrigin) attr()   {}

// Ensure the attributes implement schema.Attr by embedding the marker method
// through type assertion helpers.
var (
	_ schema.Attr = (*WithoutRowID)(nil)
	_ schema.Attr = (*Strict)(nil)
	_ schema.Attr = (*AutoIncrement)(nil)
	_ schema.Attr = (*IndexOrigin)(nil)
)

// URL holds the parsed connection URL.
type URL struct {
	Raw    string
	Scheme string
	// Path is the database file path (may be empty for memory databases).
	Path string
	// Query holds the query parameters.
	Query  url.Values
	Schema string
}

// ParseURL parses a sqlite:// URL.
func ParseURL(raw string) (*URL, error) {
	u := &URL{Raw: raw, Schema: "main"}
	i := strings.Index(raw, "://")
	if i < 0 {
		return nil, fmt.Errorf("sql/sqlclient: missing driver in url %q", raw)
	}
	u.Scheme = raw[:i]
	rest := raw[i+3:]
	if j := strings.IndexByte(rest, '?'); j >= 0 {
		q, err := url.ParseQuery(rest[j+1:])
		if err != nil {
			return nil, err
		}
		u.Query = q
		rest = rest[:j]
	} else {
		u.Query = url.Values{}
	}
	u.Path = strings.TrimPrefix(rest, "file:")
	return u, nil
}

// Host returns the host part the way net/url would parse it (used for status output).
func (u *URL) Host() string {
	if strings.HasPrefix(u.Path, "/") {
		return ""
	}
	if i := strings.IndexByte(u.Path, '/'); i >= 0 {
		return u.Path[:i]
	}
	return u.Path
}

// URLPath returns the path part the way net/url would parse it.
func (u *URL) URLPath() string {
	if strings.HasPrefix(u.Path, "/") {
		return u.Path
	}
	if i := strings.IndexByte(u.Path, '/'); i >= 0 {
		return u.Path[i:]
	}
	return ""
}

// Driver is an open SQLite connection.
type Driver struct {
	DB        *sqlite3.DB
	URL       *URL
	Version   string
	FKEnabled bool
}

// Open opens a connection to the database described by the URL.
func Open(raw string) (*Driver, error) {
	u, err := ParseURL(raw)
	if err != nil {
		return nil, err
	}
	if u.Scheme != "sqlite" && u.Scheme != "sqlite3" {
		return nil, fmt.Errorf("sql/sqlclient: unknown driver %q", u.Scheme)
	}
	// Build the SQLite URI with the parameters it understands.
	known := url.Values{}
	for k, vs := range u.Query {
		switch k {
		case "mode", "cache", "vfs", "immutable", "nolock", "psow", "modeof":
			known[k] = vs
		}
	}
	path := u.Path
	if path == "" {
		path = ":memory:"
	}
	uri := "file:" + path
	if len(known) > 0 {
		uri += "?" + known.Encode()
	}
	db, err := sqlite3.Open(uri)
	if err != nil {
		return nil, fmt.Errorf("sql/sqlclient: open: %w", err)
	}
	d := &Driver{DB: db, URL: u}
	// Foreign keys enforcement.
	fk := u.Query.Get("_fk")
	if fk == "" {
		fk = u.Query.Get("_foreign_keys")
	}
	switch strings.ToLower(fk) {
	case "1", "true", "on", "yes":
		_ = db.Exec("PRAGMA foreign_keys = ON")
	case "0", "false", "off", "no":
		_ = db.Exec("PRAGMA foreign_keys = OFF")
	}
	if v := u.Query.Get("_journal_mode"); v != "" {
		_ = db.Exec("PRAGMA journal_mode = " + v)
	}
	if v := u.Query.Get("_journal"); v != "" {
		_ = db.Exec("PRAGMA journal_mode = " + v)
	}
	ver, err := db.QueryString("SELECT sqlite_version()")
	if err != nil {
		db.Close()
		return nil, fmt.Errorf("sqlite: query version: %w", err)
	}
	d.Version = ver
	fkv, err := db.QueryString("PRAGMA foreign_keys")
	if err == nil {
		d.FKEnabled = fkv == "1"
	}
	return d, nil
}

// Close closes the connection.
func (d *Driver) Close() error { return d.DB.Close() }

// Exec executes a statement.
func (d *Driver) Exec(stmt string) error {
	return d.DB.Exec(stmt)
}

// Quote quotes an identifier.
func Quote(s string) string {
	return "`" + strings.ReplaceAll(s, "`", "``") + "`"
}
EOF
echo ok"}

