package sqlite

import (
	"fmt"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"atlas/internal/schema"
	"atlas/internal/sqlite3"
)

// InspectOptions control the inspection.
type InspectOptions struct {
	// Schemas to inspect (empty means all).
	Schemas []string
	// Exclude patterns.
	Exclude []string
	// Tables to inspect (empty means all).
	Tables []string
}

var (
	reAutoinc = regexp.MustCompile(`(?i)\bAUTOINCREMENT\b`)
	reWithout = regexp.MustCompile(`(?i)\)\s*WITHOUT\s+ROWID\b`)
	reStrict  = regexp.MustCompile(`(?i)\)\s*(?:WITHOUT\s+ROWID\s*,?\s*)?STRICT\b|\bSTRICT\s*,?\s*WITHOUT\s+ROWID\b`)
	reNumber  = regexp.MustCompile(`^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$`)
)

// InspectRealm inspects all (or the selected) schemas.
func (d *Driver) InspectRealm(opts *InspectOptions) (*schema.Realm, error) {
	if opts == nil {
		opts = &InspectOptions{}
	}
	rows, err := d.DB.Query("SELECT name, file FROM pragma_database_list()")
	if err != nil {
		return nil, fmt.Errorf("sqlite: querying schemas: %w", err)
	}
	r := &schema.Realm{}
	want := map[string]bool{}
	for _, s := range opts.Schemas {
		want[s] = true
	}
	for _, row := range rows.Rows {
		name := sqlite3.ToString(row[0])
		if len(want) > 0 && !want[name] {
			continue
		}
		s, err := d.inspectSchema(name, opts)
		if err != nil {
			return nil, err
		}
		s.Realm = r
		r.Schemas = append(r.Schemas, s)
	}
	if len(want) > 0 {
		for _, s := range opts.Schemas {
			if _, ok := r.Schema(s); !ok {
				return nil, &schema.NotExistError{Err: fmt.Errorf("sqlite: schema %q was not found", s)}
			}
		}
	}
	linkRealm(r)
	return r, nil
}

// InspectSchema inspects a single schema. An empty name means the main schema.
func (d *Driver) InspectSchema(name string, opts *InspectOptions) (*schema.Schema, error) {
	if opts == nil {
		opts = &InspectOptions{}
	}
	if name == "" {
		name = "main"
	}
	r, err := d.InspectRealm(&InspectOptions{Schemas: []string{name}, Exclude: opts.Exclude, Tables: opts.Tables})
	if err != nil {
		return nil, err
	}
	return r.Schemas[0], nil
}

func (d *Driver) inspectSchema(name string, opts *InspectOptions) (*schema.Schema, error) {
	s := &schema.Schema{Name: name}
	q := fmt.Sprintf("SELECT name, sql FROM %s.sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%%'", Quote(name))
	rows, err := d.DB.Query(q)
	if err != nil {
		return nil, fmt.Errorf("sqlite: querying %q tables: %w", name, err)
	}
	type tableSQL struct {
		t   *schema.Table
		sql string
	}
	var tables []tableSQL
	for _, row := range rows.Rows {
		tn := sqlite3.ToString(row[0])
		if len(opts.Tables) > 0 && !contains(opts.Tables, tn) {
			continue
		}
		if excluded(opts.Exclude, name, tn) {
			continue
		}
		t := &schema.Table{Name: tn, Schema: s}
		s.Tables = append(s.Tables, t)
		tables = append(tables, tableSQL{t: t, sql: sqlite3.ToString(row[1])})
	}
	for _, ts := range tables {
		if err := d.inspectTable(s, ts.t, ts.sql, opts); err != nil {
			return nil, err
		}
	}
	// Resolve foreign keys after all tables are loaded.
	for _, ts := range tables {
		if err := d.inspectFKs(s, ts.t, ts.sql); err != nil {
			return nil, err
		}
	}
	return s, nil
}

func contains(list []string, s string) bool {
	for _, x := range list {
		if x == s {
			return true
		}
	}
	return false
}

func (d *Driver) inspectTable(s *schema.Schema, t *schema.Table, createSQL string, opts *InspectOptions) error {
	// Columns.
	rows, err := d.DB.Query(fmt.Sprintf("SELECT name, type, \"notnull\", dflt_value, pk, hidden FROM %s.pragma_table_xinfo(%s)", Quote(s.Name), sqlQuote(t.Name)))
	if err != nil {
		return fmt.Errorf("sqlite: querying %q columns: %w", t.Name, err)
	}
	type pkCol struct {
		c  *schema.Column
		pk int64
	}
	var pks []pkCol
	for _, row := range rows.Rows {
		name := sqlite3.ToString(row[0])
		typ := sqlite3.ToString(row[1])
		notnull := sqlite3.ToInt(row[2]) != 0
		hidden := sqlite3.ToInt(row[5])
		if hidden == 1 {
			continue
		}
		if excluded(opts.Exclude, s.Name, t.Name, name) {
			continue
		}
		c := &schema.Column{Name: name, Type: &schema.ColumnType{Raw: typ, Null: !notnull}}
		c.Type.Type, err = ParseType(typ)
		if err != nil {
			return err
		}
		if row[3] != nil {
			c.Default = defaultExpr(sqlite3.ToString(row[3]))
		}
		if hidden == 2 || hidden == 3 {
			g := &schema.GeneratedExpr{Type: "VIRTUAL"}
			if hidden == 3 {
				g.Type = "STORED"
			}
			g.Expr = generatedExpr(createSQL, name)
			c.Attrs = append(c.Attrs, g)
		}
		if pk := sqlite3.ToInt(row[4]); pk > 0 {
			pks = append(pks, pkCol{c: c, pk: pk})
		}
		t.Columns = append(t.Columns, c)
	}
	if len(pks) > 0 {
		sort.SliceStable(pks, func(i, j int) bool { return pks[i].pk < pks[j].pk })
		pk := &schema.Index{Name: "PRIMARY", Unique: true, Table: t}
		for i, p := range pks {
			pk.Parts = append(pk.Parts, &schema.IndexPart{SeqNo: i + 1, C: p.c})
		}
		t.PrimaryKey = pk
		if len(pks) == 1 && strings.EqualFold(pks[0].c.Type.Raw, "INTEGER") && reAutoinc.MatchString(createSQL) {
			pks[0].c.Attrs = append(pks[0].c.Attrs, &AutoIncrement{})
		}
	}
	if reWithout.MatchString(createSQL) {
		t.Attrs = append(t.Attrs, &WithoutRowID{})
	}
	if reStrict.MatchString(createSQL) {
		t.Attrs = append(t.Attrs, &Strict{})
	}
	// Indexes.
	irows, err := d.DB.Query(fmt.Sprintf("SELECT name, \"unique\", origin, partial FROM %s.pragma_index_list(%s)", Quote(s.Name), sqlQuote(t.Name)))
	if err != nil {
		return fmt.Errorf("sqlite: querying %q indexes: %w", t.Name, err)
	}
	// pragma_index_list returns the most recent first; reverse to creation order.
	for i := len(irows.Rows) - 1; i >= 0; i-- {
		row := irows.Rows[i]
		name := sqlite3.ToString(row[0])
		origin := sqlite3.ToString(row[2])
		if origin == "pk" {
			continue
		}
		idx := &schema.Index{Name: name, Unique: sqlite3.ToInt(row[1]) != 0, Table: t}
		idx.Attrs = append(idx.Attrs, &IndexOrigin{O: origin})
		var idxSQL string
		if origin == "c" {
			idxSQL, _ = d.DB.QueryString(fmt.Sprintf("SELECT sql FROM %s.sqlite_master WHERE type = 'index' AND name = ?", Quote(s.Name)), name)
		}
		if err := d.indexParts(s, t, idx, idxSQL); err != nil {
			return err
		}
		if sqlite3.ToInt(row[3]) != 0 && idxSQL != "" {
			if p := indexPredicate(idxSQL); p != "" {
				idx.Attrs = append(idx.Attrs, &schema.IndexPredicate{P: p})
			}
		}
		t.Indexes = append(t.Indexes, idx)
		for _, p := range idx.Parts {
			if p.C != nil {
				p.C.Indexes = append(p.C.Indexes, idx)
			}
		}
	}
	// Check constraints.
	for _, ck := range parseChecks(createSQL) {
		t.Attrs = append(t.Attrs, ck)
	}
	return nil
}

func (d *Driver) indexParts(s *schema.Schema, t *schema.Table, idx *schema.Index, idxSQL string) error {
	rows, err := d.DB.Query(fmt.Sprintf("SELECT seqno, cid, name, \"desc\", coll, key FROM %s.pragma_index_xinfo(%s)", Quote(s.Name), sqlQuote(idx.Name)))
	if err != nil {
		return fmt.Errorf("sqlite: querying %q index columns: %w", idx.Name, err)
	}
	var exprs []string
	if idxSQL != "" {
		exprs = indexExprs(idxSQL)
	}
	ei := 0
	for _, row := range rows.Rows {
		if sqlite3.ToInt(row[5]) == 0 {
			continue
		}
		part := &schema.IndexPart{SeqNo: int(sqlite3.ToInt(row[0])) + 1, Desc: sqlite3.ToInt(row[3]) != 0}
		cid := sqlite3.ToInt(row[1])
		if cid >= 0 {
			name := sqlite3.ToString(row[2])
			c, ok := t.Column(name)
			if !ok {
				// Column excluded; skip part.
				continue
			}
			part.C = c
		} else {
			// Expression part.
			if ei < len(exprs) {
				part.X = &schema.RawExpr{X: exprs[ei]}
			} else {
				part.X = &schema.RawExpr{X: "<expr>"}
			}
			ei++
		}
		if coll := sqlite3.ToString(row[4]); coll != "" && !strings.EqualFold(coll, "BINARY") {
			part.Attrs = append(part.Attrs, &schema.Collation{V: coll})
		}
		idx.Parts = append(idx.Parts, part)
	}
	return nil
}

func (d *Driver) inspectFKs(s *schema.Schema, t *schema.Table, createSQL string) error {
	rows, err := d.DB.Query(fmt.Sprintf("SELECT id, seq, \"table\", \"from\", \"to\", on_update, on_delete FROM %s.pragma_foreign_key_list(%s) ORDER BY id, seq", Quote(s.Name), sqlQuote(t.Name)))
	if err != nil {
		return fmt.Errorf("sqlite: querying %q foreign keys: %w", t.Name, err)
	}
	byID := map[int64]*schema.ForeignKey{}
	var ids []int64
	for _, row := range rows.Rows {
		id := sqlite3.ToInt(row[0])
		fk, ok := byID[id]
		if !ok {
			fk = &schema.ForeignKey{
				Symbol:   fmt.Sprintf("%d", id),
				Table:    t,
				OnUpdate: schema.ReferenceOption(sqlite3.ToString(row[5])),
				OnDelete: schema.ReferenceOption(sqlite3.ToString(row[6])),
			}
			refName := sqlite3.ToString(row[2])
			if rt, ok := s.Table(refName); ok {
				fk.RefTable = rt
			} else if strings.EqualFold(refName, t.Name) {
				fk.RefTable = t
			} else {
				// Referenced table not found (excluded or missing); create a stub.
				fk.RefTable = &schema.Table{Name: refName, Schema: s}
			}
			byID[id] = fk
			ids = append(ids, id)
		}
		from := sqlite3.ToString(row[3])
		c, ok := t.Column(from)
		if !ok {
			continue
		}
		fk.Columns = append(fk.Columns, c)
		to := sqlite3.ToString(row[4])
		if to == "" && fk.RefTable != nil && fk.RefTable.PrimaryKey != nil && len(fk.RefTable.PrimaryKey.Parts) > 0 {
			// References the primary key implicitly.
			if len(fk.RefColumns) < len(fk.RefTable.PrimaryKey.Parts) {
				to = fk.RefTable.PrimaryKey.Parts[len(fk.RefColumns)].C.Name
			}
		}
		if rc, ok := fk.RefTable.Column(to); ok {
			fk.RefColumns = append(fk.RefColumns, rc)
		} else {
			fk.RefColumns = append(fk.RefColumns, &schema.Column{Name: to, Type: &schema.ColumnType{}})
		}
	}
	// Named constraints from the CREATE statement.
	named := parseFKNames(createSQL)
	for _, id := range ids {
		fk := byID[id]
		for _, n := range named {
			if sameColumns(n.cols, fk.Columns) {
				fk.Symbol = n.name
				break
			}
		}
		t.ForeignKeys = append(t.ForeignKeys, fk)
		for _, c := range fk.Columns {
			c.ForeignKeys = append(c.ForeignKeys, fk)
		}
	}
	return nil
}

func sameColumns(names []string, cols []*schema.Column) bool {
	if len(names) != len(cols) {
		return false
	}
	for i, n := range names {
		if !strings.EqualFold(n, cols[i].Name) {
			return false
		}
	}
	return true
}

func linkRealm(r *schema.Realm) {
	for _, s := range r.Schemas {
		s.Realm = r
		for _, t := range s.Tables {
			t.Schema = s
		}
	}
}

// defaultExpr converts a default value string to a schema expression.
func defaultExpr(x string) schema.Expr {
	switch {
	case isQuoted(x, '\'', '"'), reNumber.MatchString(x), isBoolLit(x), strings.EqualFold(x, "null"):
		return &schema.Literal{V: x}
	default:
		return &schema.RawExpr{X: x}
	}
}

func isBoolLit(s string) bool {
	return strings.EqualFold(s, "true") || strings.EqualFold(s, "false")
}

func isQuoted(s string, quotes ...byte) bool {
	if len(s) < 2 {
		return false
	}
	for _, q := range quotes {
		if s[0] == q && s[len(s)-1] == q {
			return true
		}
	}
	return false
}

func sqlQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

// excluded reports whether the resource identified by the qualified name parts
// matches one of the glob patterns.
func excluded(patterns []string, parts ...string) bool {
	for _, p := range patterns {
		pp := strings.Split(p, ".")
		// Patterns are relative to the schema when they have fewer parts.
		if len(pp) < len(parts)-1 {
			continue
		}
		var target []string
		if len(pp) == len(parts) {
			target = parts
		} else if len(pp) == len(parts)-1 {
			target = parts[1:]
		} else {
			continue
		}
		match := true
		for i := range pp {
			ok, err := filepath.Match(pp[i], target[i])
			if err != nil || !ok {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}
