		if !ok {
			continue
		}
		fk.Columns = append(fk.Columns, c)
		to := sqlite3.ToString(row[4])
		if to == "" && fk.RefTable != nil && fk.RefTable.PrimaryKey != nil && len(fk.RefTable.PrimaryKey.Parts) > 0 {
			// References the primary key implicitly.
			if len(fk.RefColumns) < len(fk.RefTable.PrimaryKey.Parts) {
				to = fk.RefTable.PrimaryKey.Parts[len(fk.RefColumns)].C.Name
			}
		}
		if rc, ok := fk.RefTable.Column(to); ok {
			fk.RefColumns = append(fk.RefColumns, rc)
		} else {
			fk.RefColumns = append(fk.RefColumns, &schema.Column{Name: to, Type: &schema.ColumnType{}})
		}
	}
	// Named constraints from the CREATE statement.
	named := parseFKNames(createSQL)
	for _, id := range ids {
		fk := byID[id]
		for _, n := range named {
			if sameColumns(n.cols, fk.Columns) {
				fk.Symbol = n.name
				break
			}
		}
		t.ForeignKeys = append(t.ForeignKeys, fk)
		for _, c := range fk.Columns {
			c.ForeignKeys = append(c.ForeignKeys, fk)
		}
	}
	return nil
}

func sameColumns(names []string, cols []*schema.Column) bool {
	if len(names) != len(cols) {
		return false
	}
	for i, n := range names {
		if !strings.EqualFold(n, cols[i].Name) {
			return false
		}
	}
	return true
}

func linkRealm(r *schema.Realm) {
	for _, s := range r.Schemas {
		s.Realm = r
		for _, t := range s.Tables {
			t.Schema = s
		}
	}
}

// defaultExpr converts a default value string to a schema expression.
func defaultExpr(x string) schema.Expr {
	switch {
	case isQuoted(x, '\'', '"'), reNumber.MatchString(x), isBoolLit(x), strings.EqualFold(x, "null"):
		return &schema.Literal{V: x}
	default:
		return &schema.RawExpr{X: x}
	}
}

func isBoolLit(s string) bool {
	return strings.EqualFold(s, "true") || strings.EqualFold(s, "false")
}

func isQuoted(s string, quotes ...byte) bool {
	if len(s) < 2 {
		return false
	}
	for _, q := range quotes {
		if s[0] == q && s[len(s)-1] == q {
			return true
		}
	}
	return false
}

func sqlQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

// excluded reports whether the resource identified by the qualified name parts
// matches one of the glob patterns.
func excluded(patterns []string, parts ...string) bool {
	for _, p := range patterns {
		pp := strings.Split(p, ".")
		// Patterns are relative to the schema when they have fewer parts.
		if len(pp) < len(parts)-1 {
			continue
		}
		var target []string
		if len(pp) == len(parts) {
			target = parts
		} else if len(pp) == len(parts)-1 {
			target = parts[1:]
		} else {
			continue
		}
		match := true
		for i := range pp {
			ok, err := filepath.Match(pp[i], target[i])
			if err != nil || !ok {
				match = false
				break
			}
		}
		if match {
			return true
		}
	}
	return false
}
