// tableBody returns the tokens inside the outermost parentheses of a CREATE
// TABLE statement, and the tokens after it.
func tableBody(toks []ddlToken) ([]ddlToken, []ddlToken) {
	depth := 0
	start := -1
	for i, t := range toks {
		if t.kind != tkPunct {
			continue
		}
		switch t.s {
		case "(":
			if depth == 0 {
				start = i
			}
			depth++
		case ")":
			depth--
			if depth == 0 && start >= 0 {
				return toks[start+1 : i], toks[i+1:]
