				return toks[start+1 : i], toks[i+1:]
			}
		}
	}
	return nil, nil
}

// splitDefs splits the table body tokens into top-level comma separated definitions.
func splitDefs(toks []ddlToken) [][]ddlToken {
	var defs [][]ddlToken
	depth := 0
	start := 0
	for i, t := range toks {
		if t.kind == tkPunct {
			switch t.s {
			case "(":
				depth++
			case ")":
				depth--
			case ",":
				if depth == 0 {
					defs = append(defs, toks[start:i])
					start = i + 1
				}
			}
		}
	}
	if start < len(toks) {
		defs = append(defs, toks[start:])
	}
	return defs
}

// parenGroup returns the raw text of the parenthesized group starting at toks[i]
// (which must be "("), and the index after the group.
func parenGroup(src []ddlToken, i int) (string, int) {
	if i >= len(src) || src[i].s != "(" {
		return "", i
	}
	depth := 0
	var b strings.Builder
	for j := i; j < len(src); j++ {
		t := src[j]
		if t.kind == tkPunct {
			switch t.s {
			case "(":
				depth++
			case ")":
				depth--
			}
		}
		if j > i {
			b.WriteString(joinSep(src[j-1], t))
		}
		b.WriteString(t.s)
		if depth == 0 {
			return b.String(), j + 1
		}
	}
	return b.String(), len(src)
}

// joinSep returns the separator to use between two tokens when rendering.
func joinSep(prev, cur ddlToken) string {
	if prev.kind == tkPunct && prev.s == "(" {
		return ""
	}
	if cur.kind == tkPunct && (cur.s == ")" || cur.s == ",") {
		return ""
	}
	if cur.kind == tkPunct && cur.s == "(" && prev.kind == tkWord {
		// function call or type args: keep attached for words like "max(" ... but
		// SQLite renders expressions as written; we cannot know. Use a space
		// only after keywords.
		return ""
	}
	return " "
}

// renderTokens renders tokens to text with simple spacing.
func renderTokens(toks []ddlToken) string {
	var b strings.Builder
	for i, t := range toks {
		if i > 0 {
			b.WriteString(joinSep(toks[i-1], t))
		}
		b.WriteString(t.s)
	}
	return b.String()
}

// parseChecks extracts CHECK constraints from a CREATE TABLE statement.
// The expression text is taken verbatim from the source (including parentheses).
func parseChecks(createSQL string) []*schema.Check {
	var checks []*schema.Check
	body, _ := tableBodyRaw(createSQL)
	if body == "" {
		return nil
	}
	toks := tokenizeDDLPos(body)
	for i := 0; i < len(toks); i++ {
		t := toks[i]
		if t.kind != tkWord || t.upper != "CHECK" {
			continue
		}
		if i+1 >= len(toks) || toks[i+1].s != "(" {
			continue
		}
		name := ""
		if i >= 2 && toks[i-2].kind == tkWord && toks[i-2].upper == "CONSTRAINT" {
			name = unquoteIdent(toks[i-1].s)
		}
		// Find the matching paren using positions in the raw text.
		depth := 0
		end := -1
		for j := i + 1; j < len(toks); j++ {
			if toks[j].kind == tkPunct {
				switch toks[j].s {
				case "(":
					depth++
				case ")":
					depth--
					if depth == 0 {
						end = j
					}
				}
			}
			if end >= 0 {
				break
			}
		}
		if end < 0 {
			continue
		}
		expr := body[toks[i+1].pos : toks[end].pos+1]
		checks = append(checks, &schema.Check{Name: name, Expr: expr})
		i = end
	}
	return checks
}

// posToken is a token with its byte position.
type posToken struct {
	ddlToken
	pos int
}

func tokenizeDDLPos(s string) []posToken {
	var toks []posToken
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '-' && i+1 < len(s) && s[i+1] == '-':
			for i < len(s) && s[i] != '\n' {
				i++
			}
		case c == '/' && i+1 < len(s) && s[i+1] == '*':
			j := strings.Index(s[i+2:], "*/")
			if j < 0 {
				i = len(s)
			} else {
				i += j + 4
			}
		case c == '\'' || c == '"' || c == '`' || c == '[':
			end := c
			if c == '[' {
				end = ']'
			}
			j := i + 1
			for j < len(s) {
				if s[j] == end {
					if j+1 < len(s) && s[j+1] == end && end != ']' {
						j += 2
						continue
					}
					break
				}
				j++
			}
			if j >= len(s) {
				j = len(s) - 1
			}
			toks = append(toks, posToken{ddlToken{s: s[i : j+1], kind: tkQuoted}, i})
			i = j + 1
		case c == '(' || c == ')' || c == ',' || c == ';':
			toks = append(toks, posToken{ddlToken{s: string(c), kind: tkPunct, upper: string(c)}, i})
			i++
		default:
			j := i
			for j < len(s) {
				d := s[j]
				if d == ' ' || d == '\t' || d == '\n' || d == '\r' || d == '(' || d == ')' || d == ',' || d == ';' || d == '\'' || d == '"' || d == '`' || d == '[' {
					break
				}
				j++
			}
			if j == i {
				j++
			}
			w := s[i:j]
			toks = append(toks, posToken{ddlToken{s: w, kind: tkWord, upper: strings.ToUpper(w)}, i})
			i = j
		}
	}
	return toks
}

// tableBodyRaw returns the raw text inside the outermost parentheses of a
// CREATE TABLE statement and the trailing text after it.
func tableBodyRaw(createSQL string) (string, string) {
	toks := tokenizeDDLPos(createSQL)
	depth := 0
	start := -1
	for _, t := range toks {
		if t.kind != tkPunct {
			continue
		}
		switch t.s {
		case "(":
			if depth == 0 {
				start = t.pos
			}
			depth++
		case ")":
			depth--
			if depth == 0 && start >= 0 {
				return createSQL[start+1 : t.pos], createSQL[t.pos+1:]
			}
		}
	}
	return "", ""
}

type fkName struct {
	name string
	cols []string
}

// parseFKNames extracts named FOREIGN KEY constraints: CONSTRAINT name FOREIGN KEY (cols).
func parseFKNames(createSQL string) []fkName {
	body, _ := tableBody(tokenizeDDL(createSQL))
	var out []fkName
	for _, def := range splitDefs(body) {
		if len(def) < 5 || def[0].upper != "CONSTRAINT" {
			continue
		}
		name := unquoteIdent(def[1].s)
		if def[2].upper != "FOREIGN" || def[3].upper != "KEY" || def[4].s != "(" {
			continue
		}
		var cols []string
		for j := 5; j < len(def) && def[j].s != ")"; j++ {
			if def[j].s == "," {
				continue
			}
			cols = append(cols, unquoteIdent(def[j].s))
		}
		out = append(out, fkName{name: name, cols: cols})
	}
	return out
}

// indexExprs extracts the expression parts of a CREATE INDEX statement (in order).
func indexExprs(idxSQL string) []string {
	// Find the column list: after "ON <table>".
	toks := tokenizeDDLPos(idxSQL)
	start := -1
	for i, t := range toks {
		if t.kind == tkWord && t.upper == "ON" && i+2 < len(toks) {
			// table name then "("
			for j := i + 1; j < len(toks); j++ {
				if toks[j].s == "(" {
					start = j
					break
				}
			}
			break
		}
	}
	if start < 0 {
		return nil
	}
	depth := 0
	end := -1
	for j := start; j < len(toks); j++ {
		if toks[j].kind == tkPunct {
			switch toks[j].s {
			case "(":
				depth++
			case ")":
				depth--
				if depth == 0 {
					end = j
				}
			}
		}
		if end >= 0 {
			break
		}
	}
	if end < 0 {
		return nil
	}
	inner := toks[start+1 : end]
	// Split by top-level commas.
	var parts [][]posToken
	depth = 0
	s := 0
	for i, t := range inner {
		if t.kind == tkPunct {
			switch t.s {
			case "(":
				depth++
			case ")":
				depth--
			case ",":
				if depth == 0 {
					parts = append(parts, inner[s:i])
					s = i + 1
				}
			}
		}
	}
	if s < len(inner) {
		parts = append(parts, inner[s:])
	}
	var exprs []string
	for _, p := range parts {
		if len(p) == 0 {
			continue
		}
		// Strip trailing COLLATE x / ASC / DESC.
		end := len(p)
		for end > 0 {
			u := p[end-1].upper
			if u == "ASC" || u == "DESC" {
				end--
				continue
			}
			if end >= 2 && p[end-2].upper == "COLLATE" {
				end -= 2
				continue
			}
			break
		}
		if end == 0 {
			continue
		}
		core := p[:end]
		// A single identifier is a column, not an expression.
		if len(core) == 1 && (core[0].kind == tkQuoted || core[0].kind == tkWord) {
			continue
		}
		text := idxSQL[core[0].pos : core[end-1].pos+len(core[end-1].s)]
		// Strip wrapping parentheses.
		if strings.HasPrefix(text, "(") && strings.HasSuffix(text, ")") && balanced(text[1:len(text)-1]) {
			text = text[1 : len(text)-1]
		}
		exprs = append(exprs, text)
	}
	return exprs
}

// indexPredicate extracts the WHERE clause of a partial index.
func indexPredicate(idxSQL string) string {
	toks := tokenizeDDLPos(idxSQL)
	depth := 0
	for _, t := range toks {
		if t.kind == tkPunct {
			switch t.s {
			case "(":
				depth++
			case ")":
				depth--
			}
		}
		if depth == 0 && t.kind == tkWord && t.upper == "WHERE" {
			return strings.TrimSpace(idxSQL[t.pos+len(t.s):])
		}
	}
	return ""
}

// generatedExpr extracts the generation expression of the given column.
func generatedExpr(createSQL, column string) string {
	body, _ := tableBody(tokenizeDDL(createSQL))
	for _, def := range splitDefs(body) {
		if len(def) == 0 || unquoteIdent(def[0].s) != column {
			continue
		}
		for i := 0; i < len(def); i++ {
			if def[i].upper == "AS" && i+1 < len(def) && def[i+1].s == "(" {
				g, _ := parenGroup(def, i+1)
				if strings.HasPrefix(g, "(") && strings.HasSuffix(g, ")") {
					g = g[1 : len(g)-1]
				}
				return g
			}
		}
	}
	return ""
}

func balanced(s string) bool {
	depth := 0
	for _, c := range s {
		switch c {
		case '(':
			depth++
		case ')':
			depth--
			if depth < 0 {
				return false
			}
		}
	}
	return depth == 0
}
