// Package sqlspec converts between the schema model and the Atlas HCL schema language.
package sqlspec

import (
	"fmt"
	"math/big"
	"sort"
	"strconv"
	"strings"
	"unicode"

	"atlas/internal/hcl"
	"atlas/internal/schema"
	"atlas/internal/sqlite"
)

// TypeSpec describes an HCL type and its attributes.
type TypeSpec struct {
	Name  string
	Attrs []string // ordered attribute names, e.g. size or precision, scale
}

// Registry maps between HCL type names and the SQL types of a driver.
type Registry struct {
	Specs  []*TypeSpec
	byName map[string]*TypeSpec
	// Format formats a schema.Type to SQL.
	Format func(schema.Type) (string, error)
	// Parse parses a SQL type.
	Parse func(string) (schema.Type, error)
}

func newRegistry(format func(schema.Type) (string, error), parse func(string) (schema.Type, error), specs ...*TypeSpec) *Registry {
	r := &Registry{Specs: specs, byName: map[string]*TypeSpec{}, Format: format, Parse: parse}
	for _, s := range specs {
		r.byName[s.Name] = s
	}
	return r
}

func sizeSpec(name string) *TypeSpec { return &TypeSpec{Name: name, Attrs: []string{"size"}} }

func precSpec(name string) *TypeSpec { return &TypeSpec{Name: name, Attrs: []string{"precision", "scale"}} }

func plainSpec(name string) *TypeSpec { return &TypeSpec{Name: name} }

// SQLiteRegistry is the type registry of the SQLite driver.
var SQLiteRegistry = newRegistry(sqlite.FormatType, sqlite.ParseType,
	precSpec("real"), sizeSpec("blob"), sizeSpec("text"), sizeSpec("integer"), sizeSpec("int"),
	sizeSpec("tinyint"), sizeSpec("smallint"), sizeSpec("mediumint"), sizeSpec("bigint"), sizeSpec("unsigned_big_int"),
	sizeSpec("int2"), sizeSpec("int8"), sizeSpec("double"), sizeSpec("double_precision"), sizeSpec("float"),
	precSpec("numeric"), precSpec("decimal"),
	sizeSpec("character"), sizeSpec("varchar"), sizeSpec("varying_character"), sizeSpec("nchar"),
	sizeSpec("native_character"), sizeSpec("nvarchar"), sizeSpec("clob"),
	plainSpec("boolean"), plainSpec("bool"), plainSpec("date"), plainSpec("datetime"), plainSpec("json"), plainSpec("uuid"),
)

// hclType is the HCL representation of a type.
type hclType struct {
	Name string
	Args []string
	Raw  bool // rendered as sql("...")
}

func (t *hclType) String() string {
	if t.Raw {
		return "sql(" + quoteHCL(t.Name) + ")"
	}
	if len(t.Args) == 0 {
		return t.Name
	}
	return t.Name + "(" + strings.Join(t.Args, ",") + ")"
}

// typeToHCL converts a schema type to its HCL representation.
func (r *Registry) typeToHCL(t schema.Type) (*hclType, error) {
	raw := func() (*hclType, error) {
		s, err := r.Format(t)
		if err != nil {
			return nil, err
		}
		return &hclType{Name: s, Raw: true}, nil
	}
	var name string
	switch x := t.(type) {
	case *schema.UnsupportedType:
		return raw()
	case *schema.BoolType:
		name = x.T
	case *schema.BinaryType:
		name = x.T
	case *schema.IntegerType:
		name = x.T
	case *schema.StringType:
		name = x.T
	case *schema.FloatType:
		name = x.T
	case *schema.DecimalType:
		name = x.T
	case *schema.TimeType:
		name = x.T
	case *schema.JSONType:
		name = x.T
	case *schema.UUIDType:
		name = x.T
	case *schema.EnumType:
		name = x.T
	default:
		return raw()
	}
	spec, ok := r.byName[strings.ReplaceAll(strings.ToLower(name), " ", "_")]
	if !ok {
		return raw()
	}
	ht := &hclType{Name: spec.Name}
	for _, a := range spec.Attrs {
		v := typeAttrValue(t, a)
		if v != 0 {
			ht.Args = append(ht.Args, strconv.Itoa(v))
		} else if len(ht.Args) > 0 && a == "scale" {
			// numeric(10) → keep only precision.
		}
	}
	return ht, nil
}

func typeAttrValue(t schema.Type, attr string) int {
	switch x := t.(type) {
	case *schema.StringType:
		if attr == "size" {
			return x.Size
		}
	case *schema.BinaryType:
		if attr == "size" && x.Size != nil {
			return *x.Size
		}
	case *schema.FloatType:
		if attr == "precision" {
			return x.Precision
		}
	case *schema.DecimalType:
		switch attr {
		case "precision":
			return x.Precision
		case "scale":
			return x.Scale
		}
	}
	return 0
}

// quoteHCL renders a string as an HCL quoted literal.
func quoteHCL(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\n':
			b.WriteString(`\n`)
		case '\r':
			b.WriteString(`\r`)
		case '\t':
			b.WriteString(`\t`)
		case '$', '%':
			if i+1 < len(s) && s[i+1] == '{' {
				b.WriteByte(c)
				b.WriteByte(c)
			} else {
				b.WriteByte(c)
			}
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

func isIdent(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if i == 0 && !(unicode.IsLetter(r) || r == '_') {
			return false
		}
		if !(unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_' || r == '-') {
			return false
		}
	}
	return true
}

// refPart renders a reference step such as `.name` or `["weird name"]`.
func refPart(kind, name string) string {
	if isIdent(name) {
		return kind + "." + name
	}
	return kind + "[" + quoteHCL(name) + "]"
}

// writer builds HCL text.
type writer struct {
	b      strings.Builder
	indent int
}

func (w *writer) line(format string, args ...interface{}) {
	w.b.WriteString(strings.Repeat("  ", w.indent))
	fmt.Fprintf(&w.b, format, args...)
	w.b.WriteByte('\n')
}

func (w *writer) open(format string, args ...interface{}) {
	w.line(format+" {", args...)
	w.indent++
}

func (w *writer) close() {
	w.indent--
	w.line("}")
}

// MarshalOptions control the HCL output.
type MarshalOptions struct {
	Registry *Registry
}

// MarshalRealm renders the realm as Atlas HCL.
func MarshalRealm(r *schema.Realm, opts *MarshalOptions) ([]byte, error) {
	if opts == nil {
		opts = &MarshalOptions{Registry: SQLiteRegistry}
	}
	w := &writer{}
	// Determine which tables need qualifiers.
	count := map[string]int{}
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			count[t.Name]++
		}
	}
	for _, s := range r.Schemas {
		for _, t := range s.Tables {
			if err := writeTable(w, t, count[t.Name] > 1, opts.Registry); err != nil {
				return nil, err
			}
		}
	}
	for _, s := range r.Schemas {
		w.open("schema %s", quoteHCL(s.Name))
		w.close()
	}
	return hcl.Format([]byte(w.b.String())), nil
}

// MarshalSchema renders a single schema as Atlas HCL.
func MarshalSchema(s *schema.Schema, opts *MarshalOptions) ([]byte, error) {
	return MarshalRealm(&schema.Realm{Schemas: []*schema.Schema{s}}, opts)
}

func writeTable(w *writer, t *schema.Table, qualify bool, reg *Registry) error {
	if qualify {
		w.open("table %s %s", quoteHCL(t.Schema.Name), quoteHCL(t.Name))
	} else {
		w.open("table %s", quoteHCL(t.Name))
	}
	w.line("schema = %s", refPart("schema", t.Schema.Name))
	var comment schema.Comment
	for _, c := range t.Columns {
		if err := writeColumn(w, c, t, reg); err != nil {
			return err
		}
	}
	if t.PrimaryKey != nil {
		w.open("primary_key")
		writeIndexParts(w, t.PrimaryKey, t)
		w.close()
	}
	for _, fk := range t.ForeignKeys {
		w.open("foreign_key %s", quoteHCL(fk.Symbol))
		w.line("columns     = %s", columnRefs(fk.Columns, nil))
		if fk.RefTable != nil {
			if fk.RefTable == t || fk.RefTable.Name == t.Name && (fk.RefTable.Schema == nil || fk.RefTable.Schema == t.Schema) {
				w.line("ref_columns = %s", columnRefs(fk.RefColumns, nil))
			} else {
				w.line("ref_columns = %s", columnRefs(fk.RefColumns, fk.RefTable))
			}
		}
		if fk.OnUpdate != "" {
			w.line("on_update   = %s", strings.ReplaceAll(string(fk.OnUpdate), " ", "_"))
		}
		if fk.OnDelete != "" {
			w.line("on_delete   = %s", strings.ReplaceAll(string(fk.OnDelete), " ", "_"))
		}
		w.close()
	}
	for _, idx := range t.Indexes {
		w.open("index %s", quoteHCL(idx.Name))
		if idx.Unique {
			w.line("unique = true")
		}
		writeIndexParts(w, idx, t)
		var pred schema.IndexPredicate
		if schema.Has(idx.Attrs, &pred) {
			w.line("where = %s", quoteHCL(pred.P))
		}
		if schema.Has(idx.Attrs, &comment) {
			w.line("comment = %s", quoteHCL(comment.Text))
		}
		w.close()
	}
	for _, ck := range t.Checks() {
		if ck.Name != "" {
			w.open("check %s", quoteHCL(ck.Name))
		} else {
			w.open("check")
		}
		w.line("expr = %s", quoteHCL(ck.Expr))
		w.close()
	}
	// Extra attributes.
	for _, a := range t.Attrs {
		switch x := a.(type) {
		case *sqlite.WithoutRowID:
			w.line("without_rowid = true")
		case *sqlite.Strict:
			w.line("strict = true")
		case *schema.Comment:
			w.line("comment = %s", quoteHCL(x.Text))
		}
	}
	w.close()
	return nil
}

func columnRefs(cols []*schema.Column, table *schema.Table) string {
	parts := make([]string, 0, len(cols))
	for _, c := range cols {
		parts = append(parts, columnRef(c, table))
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func columnRef(c *schema.Column, table *schema.Table) string {
	if table == nil {
		return refPart("column", c.Name)
	}
	return refPart("table", table.Name) + "." + refPart("column", c.Name)
}

func writeIndexParts(w *writer, idx *schema.Index, t *schema.Table) {
	simple := true
	for _, p := range idx.Parts {
		if p.C == nil || p.Desc || len(p.Attrs) > 0 {
			simple = false
			break
		}
	}
	if simple {
		cols := make([]*schema.Column, 0, len(idx.Parts))
		for _, p := range idx.Parts {
			cols = append(cols, p.C)
		}
		w.line("columns = %s", columnRefs(cols, nil))
		return
	}
	for _, p := range idx.Parts {
		w.open("on")
		if p.Desc {
			w.line("desc = true")
		}
		if p.C != nil {
			w.line("column = %s", refPart("column", p.C.Name))
		} else if p.X != nil {
			w.line("expr = %s", quoteHCL(schema.ExprString(p.X)))
		}
		var coll schema.Collation
		if schema.Has(p.Attrs, &coll) {
			w.line("collate = %s", quoteHCL(coll.V))
		}
		w.close()
	}
}

func writeColumn(w *writer, c *schema.Column, t *schema.Table, reg *Registry) error {
	w.open("column %s", quoteHCL(c.Name))
	w.line("null = %t", c.Type.Null)
	ht, err := reg.typeToHCL(c.Type.Type)
	if err != nil {
		return err
	}
	w.line("type = %s", ht.String())
	if c.Default != nil {
		d, err := defaultHCL(c)
		if err != nil {
			return err
		}
		w.line("default = %s", d)
	}
	for _, a := range c.Attrs {
		switch x := a.(type) {
		case *sqlite.AutoIncrement:
			w.line("auto_increment = true")
		case *schema.Comment:
			w.line("comment = %s", quoteHCL(x.Text))
		case *schema.GeneratedExpr:
			w.open("as")
			w.line("expr = %s", quoteHCL(x.Expr))
			if x.Type != "" {
				w.line("type = %s", x.Type)
			}
			w.close()
		}
	}
	w.close()
	return nil
}

// defaultHCL renders the default value of a column.
func defaultHCL(c *schema.Column) (string, error) {
	switch x := c.Default.(type) {
	case *schema.Literal:
		switch c.Type.Type.(type) {
		case *schema.BoolType:
			b, err := strconv.ParseBool(x.V)
			if err != nil {
				return quoteHCL(x.V), nil
			}
			return strconv.FormatBool(b), nil
		case *schema.IntegerType, *schema.FloatType, *schema.DecimalType:
			f, _, err := big.ParseFloat(x.V, 10, 512, big.ToNearestEven)
			if err != nil {
				return quoteHCL(unquote(x.V)), nil
			}
			return hcl.NumberString(f), nil
		default:
			return quoteHCL(unquote(x.V)), nil
		}
	case *schema.RawExpr:
		return "sql(" + quoteHCL(x.X) + ")", nil
	}
	return "", fmt.Errorf("unsupported default type: %T", c.Default)
}

func unquote(s string) string {
	if len(s) >= 2 && (s[0] == '\'' && s[len(s)-1] == '\'' || s[0] == '"' && s[len(s)-1] == '"') {
		q := s[0]
		inner := s[1 : len(s)-1]
		return strings.ReplaceAll(inner, string([]byte{q, q}), string(q))
	}
	return s
}

// sortedKeys returns the sorted keys of a map.
func sortedKeys(m map[string]bool) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
