	"sql":     sqlFunc,
	"hcl":     hclFunc,
	"mermaid": mermaidFunc,
	"split":   strings.Split,
	"join":    strings.Join,
	"upper":   strings.ToUpper,
	"lower":   strings.ToLower,
}

// DefaultSchemaInspectTemplate is the default output template of schema inspect.
var DefaultSchemaInspectTemplate = template.Must(template.New("inspect").Funcs(SchemaInspectFuncs).Parse("{{ $.MarshalHCL }}"))

// MarshalHCL returns the HCL representation of the realm.
func (s *SchemaInspect) MarshalHCL() (string, error) {
	b, err := sqlspec.MarshalRealm(s.Realm, nil)
	if err != nil {
		return "", err
	}
	return string(b), nil
}

// MarshalJSON implements json.Marshaler.
func (s *SchemaInspect) MarshalJSON() ([]byte, error) {
	type (
		Attrs struct {
			Comment string `json:"comment,omitempty"`
			Charset string `json:"charset,omitempty"`
			Collate string `json:"collate,omitempty"`
		}
		Column struct {
			Name string `json:"name"`
			Type string `json:"type,omitempty"`
			Null bool   `json:"null,omitempty"`
			Attrs
		}
		IndexPart struct {
			Desc   bool   `json:"desc,omitempty"`
			Column string `json:"column,omitempty"`
			Expr   string `json:"expr,omitempty"`
		}
		Index struct {
			Name   string      `json:"name,omitempty"`
			Unique bool        `json:"unique,omitempty"`
			Parts  []IndexPart `json:"parts,omitempty"`
		}
		ForeignKey struct {
			Name       string   `json:"name"`
			Columns    []string `json:"columns,omitempty"`
			References struct {
				Table   string   `json:"table"`
				Columns []string `json:"columns,omitempty"`
			} `json:"references"`
		}
		Table struct {
			Name        string       `json:"name"`
			Columns     []Column     `json:"columns,omitempty"`
			Indexes     []Index      `json:"indexes,omitempty"`
			PrimaryKey  *Index       `json:"primary_key,omitempty"`
			ForeignKeys []ForeignKey `json:"foreign_keys,omitempty"`
			Attrs
		}
		Schema struct {
			Name   string  `json:"name"`
			Tables []Table `json:"tables,omitempty"`
			Attrs
		}
	)
	var realm struct {
		Schemas []Schema `json:"schemas,omitempty"`
	}
	attrs := func(as []schema.Attr) Attrs {
		var a Attrs
		for _, x := range as {
			switch x := x.(type) {
			case *schema.Comment:
				a.Comment = x.Text
			case *schema.Charset:
				a.Charset = x.V
			case *schema.Collation:
				a.Collate = x.V
			}
		}
		return a
	}
	idx := func(i *schema.Index) Index {
		out := Index{Name: i.Name, Unique: i.Unique}
		for _, p := range i.Parts {
			part := IndexPart{Desc: p.Desc}
			if p.C != nil {
				part.Column = p.C.Name
			}
			if p.X != nil {
				part.Expr = schema.ExprString(p.X)
			}
			out.Parts = append(out.Parts, part)
		}
		return out
	}
	for _, s1 := range s.Realm.Schemas {
		s2 := Schema{Name: s1.Name, Attrs: attrs(s1.Attrs)}
		for _, t1 := range s1.Tables {
			t2 := Table{Name: t1.Name, Attrs: attrs(t1.Attrs)}
			for _, c1 := range t1.Columns {
				t2.Columns = append(t2.Columns, Column{Name: c1.Name, Type: c1.Type.Raw, Null: c1.Type.Null, Attrs: attrs(c1.Attrs)})
			}
			for _, i1 := range t1.Indexes {
				t2.Indexes = append(t2.Indexes, idx(i1))
			}
			if t1.PrimaryKey != nil {
				pk := idx(t1.PrimaryKey)
				pk.Name = ""
				pk.Unique = false
				t2.PrimaryKey = &pk
			}
			for _, fk1 := range t1.ForeignKeys {
				fk2 := ForeignKey{Name: fk1.Symbol}
				for _, c := range fk1.Columns {
					fk2.Columns = append(fk2.Columns, c.Name)
				}
				if fk1.RefTable != nil {
					fk2.References.Table = fk1.RefTable.Name
				}
				for _, c := range fk1.RefColumns {
					fk2.References.Columns = append(fk2.References.Columns, c.Name)
				}
				t2.ForeignKeys = append(t2.ForeignKeys, fk2)
			}
			s2.Tables = append(s2.Tables, t2)
		}
		realm.Schemas = append(realm.Schemas, s2)
	}
	return json.Marshal(realm)
}

