cat > /workspace/internal/sqlite/plan.go <<'EOF'
package sqlite

import (
	"fmt"
	"strings"

	"atlas/internal/schema"
)

// Change is a planned SQL statement.
type Change struct {
	Cmd     string
	Comment string
	Reverse string
	Source  schema.Change
}

// Plan is a list of planned statements.
type Plan struct {
	Name          string
	Transactional bool
	Changes       []*Change
}

// PlanOptions control the plan output.
type PlanOptions struct {
	// Indent is used to format multi-line statements.
	Indent string
	// Mode adjusts for the plan to be executed on the dev database (unused).
	SchemaQualifier string
}

type builder struct {
	b      strings.Builder
	indent string
	level  int
}

func newBuilder(indent string) *builder { return &builder{indent: indent} }

// P writes the given phrases separated by spaces.
func (b *builder) P(phrases ...string) *builder {
	for _, p := range phrases {
		if p == "" {
			continue
		}
		if b.b.Len() > 0 && !b.lastIs('(', ' ', '\n') {
			b.b.WriteByte(' ')
		}
		b.b.WriteString(p)
	}
	return b
}

func (b *builder) lastIs(chars ...byte) bool {
	s := b.b.String()
	if len(s) == 0 {
		return false
	}
	last := s[len(s)-1]
	for _, c := range chars {
		if last == c {
			return true
		}
	}
	return false
}

// Ident writes a quoted identifier.
func (b *builder) Ident(s string) *builder { return b.P(Quote(s)) }

// Table writes the table name.
func (b *builder) Table(t *schema.Table) *builder { return b.Ident(t.Name) }

// Comma writes a comma.
func (b *builder) Comma() *builder {
	b.b.WriteString(",")
	return b
}

// NL writes a newline followed by indentation when indentation is enabled.
func (b *builder) NL() *builder {
	if b.indent != "" {
		b.b.WriteByte('\n')
		b.b.WriteString(strings.Repeat(b.indent, b.level))
	} else if !b.lastIs(' ', '(') {
		b.b.WriteByte(' ')
	}
	return b
}

// Wrap writes the content of f wrapped in parentheses.
func (b *builder) Wrap(f func(b *builder)) *builder {
	b.P("(")
	f(b)
	b.b.WriteString(")")
	return b
}

// WrapIndent writes the content of f wrapped in parentheses with the body
// indented on separate lines when indentation is enabled.
func (b *builder) WrapIndent(f func(b *builder)) *builder {
	b.P("(")
	b.level++
	b.NL()
	f(b)
	b.level--
	if b.indent != "" {
		b.b.WriteByte('\n')
		b.b.WriteString(strings.Repeat(b.indent, b.level))
	}
	b.b.WriteString(")")
	return b
}

// MapComma writes n comma separated items.
func (b *builder) MapComma(n int, f func(i int, b *builder)) *builder {
	for i := 0; i < n; i++ {
		if i > 0 {
			b.Comma().P("")
			if !b.lastIs(' ') {
				b.b.WriteByte(' ')
			}
		}
		f(i, b)
	}
	return b
}

// MapIndent writes n comma separated items, each on its own line when indentation is enabled.
func (b *builder) MapIndent(n int, f func(i int, b *builder)) *builder {
	for i := 0; i < n; i++ {
		if i > 0 {
			b.Comma().NL()
		}
		f(i, b)
	}
	return b
}

func (b *builder) String() string { return b.b.String() }

type state struct {
	opts    *PlanOptions
	changes []*Change
	skipFKs bool
}

// PlanChanges plans the given schema changes into SQL statements.
func PlanChanges(changes []schema.Change, opts *PlanOptions) (*Plan, error) {
	if opts == nil {
		opts = &PlanOptions{}
	}
	s := &state{opts: opts}
	for _, c := range changes {
		var err error
		switch c := c.(type) {
		case *schema.AddTable:
			err = s.addTable(c)
		case *schema.DropTable:
			s.dropTable(c)
		case *schema.ModifyTable:
			err = s.modifyTable(c)
		case *schema.RenameTable:
			s.renameTable(c)
		case *schema.AddSchema, *schema.DropSchema:
			// Schemas are not managed in SQLite.
		default:
			err = fmt.Errorf("unsupported change %T", c)
		}
		if err != nil {
			return nil, err
		}
	}
	plan := &Plan{Transactional: true, Changes: s.changes}
	if s.skipFKs {
		plan.Transactional = false
		plan.Changes = append([]*Change{{Cmd: "PRAGMA foreign_keys = off", Comment: "disable the enforcement of foreign-keys constraints"}}, plan.Changes...)
		plan.Changes = append(plan.Changes, &Change{Cmd: "PRAGMA foreign_keys = on", Comment: "enable back the enforcement of foreign-keys constraints"})
	}
	return plan, nil
}

func (s *state) build(phrases ...string) *builder {
	return newBuilder(s.opts.Indent).P(phrases...)
}

func (s *state) append(c *Change) { s.changes = append(s.changes, c) }

// autoincPK reports whether the table primary key is a single AUTOINCREMENT column.
func autoincPK(t *schema.Table) (*schema.Column, bool) {
	if t.PrimaryKey == nil || len(t.PrimaryKey.Parts) != 1 || t.PrimaryKey.Parts[0].C == nil {
		return nil, false
	}
	c := t.PrimaryKey.Parts[0].C
	for _, a := range c.Attrs {
		if _, ok := a.(*AutoIncrement); ok {
			return c, true
		}
	}
	return nil, false
}

func (s *state) createTableSQL(t *schema.Table) (string, error) {
	var errs []string
	b := s.build("CREATE TABLE").Table(t)
	b.WrapIndent(func(b *builder) {
		b.MapIndent(len(t.Columns), func(i int, b *builder) {
			if err := s.column(b, t, t.Columns[i]); err != nil {
				errs = append(errs, err.Error())
			}
		})
		if pk := t.PrimaryKey; pk != nil {
			if _, ok := autoincPK(t); !ok {
				b.Comma().NL().P("PRIMARY KEY")
				s.indexParts(b, pk.Parts)
			}
		}
		if len(t.ForeignKeys) > 0 {
			b.Comma().NL()
			s.fks(b, t.ForeignKeys...)
		}
		for _, ck := range t.Checks() {
			b.Comma().NL()
			check(b, ck)
		}
	})
	if len(errs) > 0 {
		return "", fmt.Errorf("create table %q: %s", t.Name, strings.Join(errs, ", "))
	}
	for _, a := range t.Attrs {
		switch a.(type) {
		case *WithoutRowID:
			b.P("WITHOUT ROWID")
		case *Strict:
			b.P("STRICT")
		}
	}
	return b.String(), nil
}

func (s *state) addTable(add *schema.AddTable) error {
	cmd, err := s.createTableSQL(add.T)
	if err != nil {
		return err
	}
	s.append(&Change{
		Cmd:     cmd,
		Source:  add,
		Reverse: s.build("DROP TABLE").Table(add.T).String(),
		Comment: fmt.Sprintf("create %q table", add.T.Name),
	})
	return s.addIndexes(add.T, add.T.Indexes...)
}

func (s *state) dropTable(drop *schema.DropTable) {
	s.skipFKs = true
	rs := &state{opts: s.opts}
	_ = rs.addTable(&schema.AddTable{T: drop.T})
	var reverse []string
	for _, c := range rs.changes {
		reverse = append(reverse, c.Cmd)
	}
	s.append(&Change{
		Cmd:     s.build("DROP TABLE").Table(drop.T).String(),
		Source:  drop,
		Reverse: strings.Join(reverse, "; "),
		Comment: fmt.Sprintf("drop %q table", drop.T.Name),
	})
}

func (s *state) renameTable(r *schema.RenameTable) {
	s.append(&Change{
		Cmd:     s.build("ALTER TABLE").Table(r.From).P("RENAME TO").Table(r.To).String(),
		Source:  r,
		Reverse: s.build("ALTER TABLE").Table(r.To).P("RENAME TO").Table(r.From).String(),
		Comment: fmt.Sprintf("rename a table from %q to %q", r.From.Name, r.To.Name),
	})
}

func (s *state) addIndexes(t *schema.Table, indexes ...*schema.Index) error {
	for _, idx := range indexes {
		if strings.HasPrefix(idx.Name, "sqlite_autoindex") {
			var origin IndexOrigin
			if hasOrigin(idx.Attrs, &origin) && origin.O == "pk" {
				continue
			}
			names := make([]string, len(idx.Parts)+1)
			names[0] = t.Name
			for i, p := range idx.Parts {
				if p.C == nil {
					return fmt.Errorf("unexpected index part %s of auto index %q", schema.ExprString(p.X), idx.Name)
				}
				names[i+1] = p.C.Name
			}
			idx.Name = strings.Join(names, "_")
		}
		b := s.build("CREATE")
		if idx.Unique {
			b.P("UNIQUE")
		}
		b.P("INDEX").Ident(idx.Name).P("ON").Table(t)
		s.indexParts(b, idx.Parts)
		var pred schema.IndexPredicate
		if schema.Has(idx.Attrs, &pred) {
			b.P("WHERE").P(pred.P)
		}
		s.append(&Change{
			Cmd:     b.String(),
			Source:  &schema.AddIndex{I: idx},
			Reverse: s.build("DROP INDEX").Ident(idx.Name).String(),
			Comment: fmt.Sprintf("create index %q to table: %q", idx.Name, t.Name),
		})
	}
	return nil
}

func hasOrigin(attrs []schema.Attr, o *IndexOrigin) bool {
	for _, a := range attrs {
		if x, ok := a.(*IndexOrigin); ok {
			*o = *x
			return true
		}
	}
	return false
}

func (s *state) dropIndexes(t *schema.Table, indexes ...*schema.Index) {
	for _, idx := range indexes {
		rs := &state{opts: s.opts}
		_ = rs.addIndexes(t, idx)
		reverse := ""
		if len(rs.changes) > 0 {
			reverse = rs.changes[0].Cmd
		}
		s.append(&Change{
			Cmd:     s.build("DROP INDEX").Ident(idx.Name).String(),
			Source:  &schema.DropIndex{I: idx},
			Reverse: reverse,
			Comment: fmt.Sprintf("drop index %q from table: %q", idx.Name, t.Name),
		})
	}
}

func (s *state) indexParts(b *builder, parts []*schema.IndexPart) {
	b.Wrap(func(b *builder) {
		b.MapComma(len(parts), func(i int, b *builder) {
			p := parts[i]
			switch {
			case p.C != nil:
				b.Ident(p.C.Name)
			case p.X != nil:
				b.P(mayWrap(schema.ExprString(p.X)))
			}
			var coll schema.Collation
			if schema.Has(p.Attrs, &coll) {
				b.P("COLLATE", coll.V)
			}
			if p.Desc {
				b.P("DESC")
			}
		})
	})
}

func (s *state) fks(b *builder, fks ...*schema.ForeignKey) {
	b.MapIndent(len(fks), func(i int, b *builder) {
		fk := fks[i]
		if fk.Symbol != "" {
			b.P("CONSTRAINT").Ident(fk.Symbol)
		}
		b.P("FOREIGN KEY")
		b.Wrap(func(b *builder) {
			b.MapComma(len(fk.Columns), func(i int, b *builder) { b.Ident(fk.Columns[i].Name) })
		})
		b.P("REFERENCES").Ident(fk.RefTable.Name)
		b.Wrap(func(b *builder) {
			b.MapComma(len(fk.RefColumns), func(i int, b *builder) { b.Ident(fk.RefColumns[i].Name) })
		})
		if fk.OnUpdate != "" {
			b.P("ON UPDATE", string(fk.OnUpdate))
		}
		if fk.OnDelete != "" {
			b.P("ON DELETE", string(fk.OnDelete))
		}
	})
}

func check(b *builder, c *schema.Check) {
	if c.Name != "" {
		b.P("CONSTRAINT").Ident(c.Name)
	}
	b.P("CHECK", mayWrap(c.Expr))
}

func (s *state) column(b *builder, t *schema.Table, c *schema.Column) error {
	typ, err := FormatType(c.Type.Type)
	if err != nil {
		return err
	}
	b.Ident(c.Name).P(typ)
	if !c.Type.Null {
		b.P("NOT")
	}
	b.P("NULL")
	if pk, ok := autoincPK(t); ok && pk == c {
		b.P("PRIMARY KEY AUTOINCREMENT")
	}
	if c.Default != nil {
		b.P("DEFAULT", defaultValue(c.Default))
	}
	var g schema.GeneratedExpr
	if schema.Has(c.Attrs, &g) {
		b.P("AS", mayWrap(g.Expr), g.Type)
	}
	return nil
}

// defaultValue formats a default value expression.
func defaultValue(e schema.Expr) string {
	switch x := e.(type) {
	case *schema.Literal:
		return x.V
	case *schema.RawExpr:
		return mayWrap(x.X)
	}
	return ""
}

// mayWrap wraps the expression with parentheses if it is not already wrapped.
func mayWrap(s string) string {
	n := len(s) - 1
	if len(s) < 2 || s[0] != '(' || s[n] != ')' || !balanced(s[1:n]) {
		return "(" + s + ")"
	}
	return s
}

func (s *state) modifyTable(modify *schema.ModifyTable) error {
	if alterable(modify) {
		return s.alterTable(modify)
	}
	return s.copyTable(modify)
}

func isPKColumn(t *schema.Table, c *schema.Column) bool {
	if t.PrimaryKey == nil {
		return false
	}
	for _, p := range t.PrimaryKey.Parts {
		if p.C == c {
			return true
		}
	}
	return false
}

// alterable reports whether all changes can be applied with ALTER TABLE statements.
func alterable(modify *schema.ModifyTable) bool {
	for _, change := range modify.Changes {
		switch change := change.(type) {
		case *schema.RenameColumn, *schema.RenameIndex, *schema.DropIndex, *schema.AddIndex, *schema.ModifyIndex:
		case *schema.AddColumn:
			c := change.C
			if len(c.ForeignKeys) > 0 || isPKColumn(modify.T, c) {
				return false
			}
			for _, idx := range c.Indexes {
				if idx.Unique {
					return false
				}
			}
			for _, a := range c.Attrs {
				if _, ok := a.(*AutoIncrement); ok {
					return false
				}
			}
			if _, ok := c.Default.(*schema.RawExpr); ok {
				return false
			}
			if !c.Type.Null && c.Default == nil {
				return false
			}
		case *schema.DropColumn:
			c := change.C
			if len(c.Indexes) > 0 || len(c.ForeignKeys) > 0 {
				return false
			}
			for _, fk := range modify.T.ForeignKeys {
				for _, rc := range fk.RefColumns {
					if rc.Name == c.Name {
						return false
					}
				}
			}
			var g schema.GeneratedExpr
			if schema.Has(c.Attrs, &g) {
				return false
			}
		default:
			return false
		}
	}
	return true
}

func (s *state) alterTable(modify *schema.ModifyTable) error {
	for _, change := range modify.Changes {
		switch change := change.(type) {
		case *schema.AddIndex:
			if err := s.addIndexes(modify.T, change.I); err != nil {
				return err
			}
		case *schema.DropIndex:
			s.dropIndexes(modify.T, change.I)
		case *schema.ModifyIndex:
			s.dropIndexes(modify.T, change.From)
			if err := s.addIndexes(modify.T, change.To); err != nil {
				return err
			}
		case *schema.RenameIndex:
			s.dropIndexes(modify.T, change.From)
			if err := s.addIndexes(modify.T, change.To); err != nil {
				return err
			}
		case *schema.AddColumn:
			b := s.build("ALTER TABLE").Table(modify.T).P("ADD COLUMN")
			if err := s.column(b, modify.T, change.C); err != nil {
				return err
			}
			s.append(&Change{
				Cmd:     b.String(),
				Source:  change,
				Reverse: s.build("ALTER TABLE").Table(modify.T).P("DROP COLUMN").Ident(change.C.Name).String(),
				Comment: fmt.Sprintf("add column %q to table: %q", change.C.Name, modify.T.Name),
			})
		case *schema.DropColumn:
			rb := s.build("ALTER TABLE").Table(modify.T).P("ADD COLUMN")
			_ = s.column(rb, modify.T, change.C)
			s.append(&Change{
				Cmd:     s.build("ALTER TABLE").Table(modify.T).P("DROP COLUMN").Ident(change.C.Name).String(),
				Source:  change,
				Reverse: rb.String(),
				Comment: fmt.Sprintf("drop column %q from table: %q", change.C.Name, modify.T.Name),
			})
		case *schema.RenameColumn:
			s.append(&Change{
				Cmd:     s.build("ALTER TABLE").Table(modify.T).P("RENAME COLUMN").Ident(change.From.Name).P("TO").Ident(change.To.Name).String(),
				Source:  change,
				Reverse: s.build("ALTER TABLE").Table(modify.T).P("RENAME COLUMN").Ident(change.To.Name).P("TO").Ident(change.From.Name).String(),
				Comment: fmt.Sprintf("rename a column from %q to %q", change.From.Name, change.To.Name),
			})
		}
	}
	return nil
}

// copyTable implements table modification using the "create new, copy, drop, rename" approach.
func (s *state) copyTable(modify *schema.ModifyTable) error {
	s.skipFKs = true
	newT := *modify.T
	newT.Name = "new_" + modify.T.Name
	// Indexes are created after renaming the table.
	newT.Indexes = nil
	cmd, err := s.createTableSQL(&newT)
	if err != nil {
		return err
	}
	s.append(&Change{
		Cmd:     cmd,
		Source:  modify,
		Reverse: s.build("DROP TABLE").Ident(newT.Name).String(),
		Comment: fmt.Sprintf("create %q table", newT.Name),
	})
	// Determine the columns to copy: columns that exist in both the old and the
	// new table (taking renames into account), excluding generated columns.
	renamed := map[string]string{} // new name -> old name
	dropped := map[string]bool{}
	added := map[string]bool{}
	for _, c := range modify.Changes {
		switch c := c.(type) {
		case *schema.RenameColumn:
			renamed[c.To.Name] = c.From.Name
		case *schema.DropColumn:
			dropped[c.C.Name] = true
		case *schema.AddColumn:
			added[c.C.Name] = true
		}
	}
	var newCols, oldCols []string
	for _, c := range modify.T.Columns {
		var g schema.GeneratedExpr
		if schema.Has(c.Attrs, &g) {
			continue
		}
		old := c.Name
		if o, ok := renamed[c.Name]; ok {
			old = o
		} else if added[c.Name] {
			continue
		}
		newCols = append(newCols, c.Name)
		oldCols = append(oldCols, old)
	}
	if len(newCols) > 0 {
		b := s.build("INSERT INTO").Ident(newT.Name)
		b.Wrap(func(b *builder) {
			b.MapComma(len(newCols), func(i int, b *builder) { b.Ident(newCols[i]) })
		})
		b.P("SELECT")
		b.MapComma(len(oldCols), func(i int, b *builder) { b.Ident(oldCols[i]) })
		b.P("FROM").Ident(modify.T.Name)
		s.append(&Change{
			Cmd:     b.String(),
			Source:  modify,
			Comment: fmt.Sprintf("copy rows from old table %q to new temporary table %q", modify.T.Name, newT.Name),
		})
	}
	s.append(&Change{
		Cmd:     s.build("DROP TABLE").Ident(modify.T.Name).String(),
		Source:  modify,
		Comment: fmt.Sprintf("drop %q table after copying rows", modify.T.Name),
	})
	s.append(&Change{
		Cmd:     s.build("ALTER TABLE").Ident(newT.Name).P("RENAME TO").Ident(modify.T.Name).String(),
		Source:  modify,
		Comment: fmt.Sprintf("rename temporary table %q to %q", newT.Name, modify.T.Name),
	})
	return s.addIndexes(modify.T, modify.T.Indexes...)
}
