// DiffOptions control the diff.
type DiffOptions struct {
	// SkipDestructive drops are skipped when the corresponding flag is set.
	SkipDropTable  bool
	SkipDropColumn bool
	SkipDropIndex  bool
	SkipDropSchema bool
}

// RealmDiff returns the changes required to migrate from one realm to another.
func RealmDiff(from, to *schema.Realm, opts *DiffOptions) ([]schema.Change, error) {
	if opts == nil {
		opts = &DiffOptions{}
	}
	var changes []schema.Change
	for _, s1 := range from.Schemas {
		s2, ok := to.Schema(s1.Name)
		if !ok {
			if !opts.SkipDropSchema {
				changes = append(changes, &schema.DropSchema{S: s1})
			}
			continue
		}
		c, err := SchemaDiff(s1, s2, opts)
		if err != nil {
			return nil, err
		}
		changes = append(changes, c...)
	}
	for _, s1 := range to.Schemas {
		if _, ok := from.Schema(s1.Name); ok {
			continue
		}
		changes = append(changes, &schema.AddSchema{S: s1})
		for _, t := range s1.Tables {
			changes = append(changes, &schema.AddTable{T: t})
		}
	}
	return changes, nil
}

// SchemaDiff returns the changes required to migrate from one schema to another.
func SchemaDiff(from, to *schema.Schema, opts *DiffOptions) ([]schema.Change, error) {
	if opts == nil {
		opts = &DiffOptions{}
	}
	var changes []schema.Change
	for _, t1 := range from.Tables {
		t2, ok := to.Table(t1.Name)
		if !ok {
			if !opts.SkipDropTable {
				changes = append(changes, &schema.DropTable{T: t1})
			}
			continue
		}
		change, err := TableDiff(t1, t2, opts)
		if err != nil {
			return nil, err
		}
		if len(change) > 0 {
			changes = append(changes, &schema.ModifyTable{T: t2, Changes: change})
		}
	}
	for _, t1 := range to.Tables {
		if _, ok := from.Table(t1.Name); !ok {
			changes = append(changes, &schema.AddTable{T: t1})
		}
	}
	return changes, nil
}

// TableDiff returns the changes required to migrate one table to another.
func TableDiff(from, to *schema.Table, opts *DiffOptions) ([]schema.Change, error) {
	if opts == nil {
		opts = &DiffOptions{}
	}
	var changes []schema.Change
	if from.Name != to.Name {
		return nil, fmt.Errorf("mismatched table names: %q != %q", from.Name, to.Name)
	}
	// Table attributes: checks, without rowid, strict.
	changes = append(changes, tableAttrDiff(from, to)...)
	// Columns.
	for _, c1 := range from.Columns {
		c2, ok := to.Column(c1.Name)
		if !ok {
			if !opts.SkipDropColumn {
				changes = append(changes, &schema.DropColumn{C: c1})
			}
			continue
		}
		change, err := columnChange(c1, c2)
		if err != nil {
			return nil, err
		}
		if change != schema.NoChange {
			changes = append(changes, &schema.ModifyColumn{From: c1, To: c2, Change: change})
		}
	}
	for _, c1 := range to.Columns {
		if _, ok := from.Column(c1.Name); !ok {
			changes = append(changes, &schema.AddColumn{C: c1})
		}
	}
	// Primary key.
	pk1, pk2 := from.PrimaryKey, to.PrimaryKey
	switch {
	case pk1 == nil && pk2 != nil:
		changes = append(changes, &schema.AddPrimaryKey{P: pk2})
	case pk1 != nil && pk2 == nil:
		changes = append(changes, &schema.DropPrimaryKey{P: pk1})
	case pk1 != nil && pk2 != nil:
		if change := partsChange(pk1.Parts, pk2.Parts); change != schema.NoChange {
			changes = append(changes, &schema.ModifyPrimaryKey{From: pk1, To: pk2, Change: change})
		}
	}
	// Indexes.
	for _, idx1 := range from.Indexes {
		idx2, ok := findIndex(to, idx1)
		if !ok {
			if !opts.SkipDropIndex {
				changes = append(changes, &schema.DropIndex{I: idx1})
			}
			continue
		}
		if change := indexChange(idx1, idx2); change != schema.NoChange {
			changes = append(changes, &schema.ModifyIndex{From: idx1, To: idx2, Change: change})
		}
	}
	for _, idx1 := range to.Indexes {
		if _, ok := findIndex(from, idx1); !ok {
			changes = append(changes, &schema.AddIndex{I: idx1})
		}
	}
	// Foreign keys.
	for _, fk1 := range from.ForeignKeys {
		fk2, ok := to.ForeignKey(fk1.Symbol)
		if !ok {
			changes = append(changes, &schema.DropForeignKey{F: fk1})
			continue
		}
		if change := fkChange(fk1, fk2); change != schema.NoChange {
			changes = append(changes, &schema.ModifyForeignKey{From: fk1, To: fk2, Change: change})
		}
	}
	for _, fk1 := range to.ForeignKeys {
		if _, ok := from.ForeignKey(fk1.Symbol); !ok {
			changes = append(changes, &schema.AddForeignKey{F: fk1})
		}
	}
	return changes, nil
}

// findIndex finds the matching index in the table. Auto indexes created for
// UNIQUE constraints are matched by their generated name as well.
func findIndex(t *schema.Table, idx *schema.Index) (*schema.Index, bool) {
	if i, ok := t.Index(idx.Name); ok {
		return i, true
	}
	if strings.HasPrefix(idx.Name, "sqlite_autoindex") {
		names := []string{t.Name}
		for _, p := range idx.Parts {
			if p.C != nil {
				names = append(names, p.C.Name)
			}
		}
		if i, ok := t.Index(strings.Join(names, "_")); ok {
			return i, true
		}
	}
	for _, i := range t.Indexes {
		if strings.HasPrefix(i.Name, "sqlite_autoindex") {
			names := []string{t.Name}
			for _, p := range i.Parts {
				if p.C != nil {
					names = append(names, p.C.Name)
				}
			}
			if strings.Join(names, "_") == idx.Name {
				return i, true
			}
		}
	}
	return nil, false
}

func tableAttrDiff(from, to *schema.Table) []schema.Change {
	var changes []schema.Change
	// Checks.
	fromChecks, toChecks := from.Checks(), to.Checks()
	for _, c1 := range fromChecks {
		c2, ok := findCheck(toChecks, c1)
		if !ok {
			changes = append(changes, &schema.DropCheck{C: c1})
			continue
		}
		if normalizeExpr(c1.Expr) != normalizeExpr(c2.Expr) {
			changes = append(changes, &schema.ModifyCheck{From: c1, To: c2, Change: schema.ChangeAttr})
		}
	}
	for _, c1 := range toChecks {
		if _, ok := findCheck(fromChecks, c1); !ok {
			changes = append(changes, &schema.AddCheck{C: c1})
		}
	}
	// WITHOUT ROWID / STRICT.
	for _, pair := range []struct {
		a    schema.Attr
		name string
	}{{&WithoutRowID{}, "without_rowid"}, {&Strict{}, "strict"}} {
		h1, h2 := hasAttrType(from.Attrs, pair.a), hasAttrType(to.Attrs, pair.a)
		switch {
		case h1 && !h2:
			changes = append(changes, &schema.DropAttr{A: pair.a})
		case !h1 && h2:
			changes = append(changes, &schema.AddAttr{A: pair.a})
		}
	}
	return changes
}

func hasAttrType(attrs []schema.Attr, target schema.Attr) bool {
	for _, a := range attrs {
		if reflect.TypeOf(a) == reflect.TypeOf(target) {
			return true
		}
	}
	return false
}

func findCheck(checks []*schema.Check, c *schema.Check) (*schema.Check, bool) {
	if c.Name != "" {
		for _, x := range checks {
			if x.Name == c.Name {
				return x, true
			}
		}
		return nil, false
	}
	for _, x := range checks {
		if x.Name == "" && normalizeExpr(x.Expr) == normalizeExpr(c.Expr) {
			return x, true
		}
	}
	return nil, false
}

func normalizeExpr(s string) string {
	s = strings.TrimSpace(s)
	for len(s) >= 2 && s[0] == '(' && s[len(s)-1] == ')' && balanced(s[1:len(s)-1]) {
		s = strings.TrimSpace(s[1 : len(s)-1])
	}
	return strings.ToLower(strings.Join(strings.Fields(s), " "))
}

func columnChange(from, to *schema.Column) (schema.ChangeKind, error) {
	var change schema.ChangeKind
	if from.Type.Null != to.Type.Null {
		change |= schema.ChangeNull
	}
	if from.Type.Type == nil || to.Type.Type == nil {
		return change, fmt.Errorf("sqlite: missing type information for column %q", from.Name)
	}
	// Types are mismatched if they do not have the same type affinity.
	if reflect.TypeOf(from.Type.Type) != reflect.TypeOf(to.Type.Type) {
		change |= schema.ChangeType
	}
	if defaultChanged(from, to) {
		change |= schema.ChangeDefault
	}
	if hasAttrType(from.Attrs, &AutoIncrement{}) != hasAttrType(to.Attrs, &AutoIncrement{}) {
		change |= schema.ChangeAttr
	}
	var g1, g2 schema.GeneratedExpr
	h1, h2 := schema.Has(from.Attrs, &g1), schema.Has(to.Attrs, &g2)
	if h1 != h2 || h1 && normalizeExpr(g1.Expr) != normalizeExpr(g2.Expr) {
		change |= schema.ChangeGenerated
	}
	return change, nil
}

func defaultChanged(from, to *schema.Column) bool {
	d1, d2 := from.Default, to.Default
	if (d1 == nil) != (d2 == nil) {
		return true
	}
	if d1 == nil {
		return false
	}
	s1, s2 := normalizeDefault(d1), normalizeDefault(d2)
	return s1 != s2
}

func normalizeDefault(e schema.Expr) string {
	s := strings.TrimSpace(schema.ExprString(e))
	for len(s) >= 2 && s[0] == '(' && s[len(s)-1] == ')' && balanced(s[1:len(s)-1]) {
		s = strings.TrimSpace(s[1 : len(s)-1])
	}
	if isQuoted(s, '\'', '"') {
		return "'" + unquote(s) + "'"
	}
	return strings.ToLower(s)
}

func unquote(s string) string {
	if len(s) >= 2 {
		q := s[0]
		return strings.ReplaceAll(s[1:len(s)-1], string([]byte{q, q}), string(q))
	}
	return s
}

func partsChange(from, to []*schema.IndexPart) schema.ChangeKind {
	if len(from) != len(to) {
		return schema.ChangeParts
	}
	for i := range from {
		p1, p2 := from[i], to[i]
		if p1.Desc != p2.Desc {
			return schema.ChangeParts
		}
		switch {
		case p1.C != nil && p2.C != nil:
			if p1.C.Name != p2.C.Name {
				return schema.ChangeParts
			}
		case p1.X != nil && p2.X != nil:
			if normalizeExpr(schema.ExprString(p1.X)) != normalizeExpr(schema.ExprString(p2.X)) {
				return schema.ChangeParts
			}
		default:
			return schema.ChangeParts
		}
		var c1, c2 schema.Collation
		h1, h2 := schema.Has(p1.Attrs, &c1), schema.Has(p2.Attrs, &c2)
		if h1 != h2 || h1 && !strings.EqualFold(c1.V, c2.V) {
			return schema.ChangeParts
		}
	}
	return schema.NoChange
}

func indexChange(from, to *schema.Index) schema.ChangeKind {
	var change schema.ChangeKind
	if from.Unique != to.Unique {
		change |= schema.ChangeUnique
	}
	var p1, p2 schema.IndexPredicate
	h1, h2 := schema.Has(from.Attrs, &p1), schema.Has(to.Attrs, &p2)
	if h1 != h2 || h1 && normalizeExpr(p1.P) != normalizeExpr(p2.P) {
		change |= schema.ChangeAttr
	}
	change |= partsChange(from.Parts, to.Parts)
	return change
}

func fkChange(from, to *schema.ForeignKey) schema.ChangeKind {
	var change schema.ChangeKind
	switch {
	case from.RefTable == nil || to.RefTable == nil:
		if from.RefTable != to.RefTable {
			change |= schema.ChangeRefTable
		}
	case from.RefTable.Name != to.RefTable.Name:
		change |= schema.ChangeRefTable
	}
	if !sameColumnNames(from.Columns, to.Columns) {
		change |= schema.ChangeColumn
	}
	if !sameColumnNames(from.RefColumns, to.RefColumns) {
		change |= schema.ChangeRefColumn
	}
	if normalizeAction(from.OnUpdate) != normalizeAction(to.OnUpdate) {
		change |= schema.ChangeUpdateAction
	}
	if normalizeAction(from.OnDelete) != normalizeAction(to.OnDelete) {
		change |= schema.ChangeDeleteAction
	}
	return change
}

func normalizeAction(o schema.ReferenceOption) string {
	s := strings.ToUpper(strings.TrimSpace(string(o)))
	if s == "" {
		return string(schema.NoAction)
	}
	return strings.Join(strings.Fields(strings.ReplaceAll(s, "_", " ")), " ")
}

func sameColumnNames(a, b []*schema.Column) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i].Name != b[i].Name {
			return false
		}
	}
	return true
}
