	w.tb.Newline()
}

func (w *writer) attrRaw(name, raw string) {
	w.attr(name, func(tb *hcl.TokenBuilder) { tb.Raw(raw) })
}

func (w *writer) attrString(name, s string) {
	w.attr(name, func(tb *hcl.TokenBuilder) { tb.Quoted(escapeHCL(s)) })
}

func (w *writer) attrBool(name string, b bool) {
	w.attrRaw(name, strconv.FormatBool(b))
}

// open writes a block header: `type "label" {`.
func (w *writer) open(typ string, labels ...string) {
	w.tb.Ident(typ)
	for _, l := range labels {
		w.tb.Quoted(escapeHCL(l))
	}
	w.tb.OBrace().Newline()
}

func (w *writer) close() {
	w.tb.CBrace().Newline()
}

// ref writes a reference such as column.id or table["x"].column.id.
func writeRef(tb *hcl.TokenBuilder, parts ...[2]string) {
	for i, p := range parts {
		if i > 0 {
			tb.Dot()
		}
		tb.Ident(p[0])
		if isIdent(p[1]) {
			tb.Dot().Ident(p[1])
		} else {
			tb.OBrack().Quoted(escapeHCL(p[1])).CBrack()
		}
	}
}

