package sqlspec

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"atlas/internal/hcl"
	"atlas/internal/project"
	"atlas/internal/schema"
	"atlas/internal/sqlite"
)

// enumValues are bare identifiers accepted as enum-like values.
var enumValues = map[string]bool{
	"NO_ACTION": true, "RESTRICT": true, "CASCADE": true, "SET_NULL": true, "SET_DEFAULT": true,
	"STORED": true, "VIRTUAL": true,
}

// refRoots are the resource kinds that can be referenced.
var refRoots = map[string]bool{
	"schema": true, "table": true, "column": true, "index": true, "primary_key": true,
	"foreign_key": true, "check": true, "view": true, "enum": true, "function": true,
	"procedure": true, "trigger": true, "sequence": true, "domain": true,
}

// UnmarshalOptions control the conversion from HCL to the schema model.
type UnmarshalOptions struct {
	Registry *Registry
	Vars     map[string][]string
	// EnvName is the value of atlas.env.
	EnvName string
}

// ParseFiles reads all HCL files from the given paths (files or directories).
func ParseFiles(paths []string) ([]*hcl.File, error) {
	var files []*hcl.File
	for _, p := range paths {
		st, err := os.Stat(p)
		if err != nil {
			return nil, err
		}
		if st.IsDir() {
			entries, err := os.ReadDir(p)
			if err != nil {
				return nil, err
			}
			var names []string
			for _, e := range entries {
				if !e.IsDir() && strings.HasSuffix(e.Name(), ".hcl") {
					names = append(names, filepath.Join(p, e.Name()))
				}
			}
			sort.Strings(names)
			for _, n := range names {
				f, err := parseFile(n)
				if err != nil {
					return nil, err
				}
				files = append(files, f)
			}
			continue
		}
		f, err := parseFile(p)
		if err != nil {
			return nil, err
		}
		files = append(files, f)
	}
	return files, nil
}

func parseFile(path string) (*hcl.File, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	f, diags := hcl.ParseConfig(src, filepath.Base(path))
	if diags.HasErrors() {
		return nil, diags
	}
	f.Name = path
	return f, nil
}

// UnmarshalRealm converts the HCL files into a realm.
func UnmarshalRealm(files []*hcl.File, opts *UnmarshalOptions) (*schema.Realm, error) {
	if opts == nil {
		opts = &UnmarshalOptions{}
	}
	if opts.Registry == nil {
		opts.Registry = SQLiteRegistry
	}
	// Merge all bodies into a single body for evaluation.
	merged := &hcl.Body{}
	for _, f := range files {
		merged.Attributes = append(merged.Attributes, f.Body.Attributes...)
		merged.Blocks = append(merged.Blocks, f.Body.Blocks...)
		merged.Items = append(merged.Items, f.Body.Items...)
	}
	baseDir := "."
	if len(files) > 0 {
		baseDir, _ = filepath.Abs(filepath.Dir(files[0].Name))
	}
	ctx := &hcl.EvalContext{
		Variables: map[string]hcl.Value{
			"atlas": hcl.ObjectVal([]string{"env"}, map[string]hcl.Value{"env": hcl.StringVal(opts.EnvName)}),
		},
		Functions: hcl.StdFunctions(baseDir),
	}
	u := &unmarshaler{reg: opts.Registry, ctx: ctx}
	ctx.ResolveRef = u.resolveRef
	ctx.ResolveFunc = u.resolveFunc
	ev := &project.Evaluator{File: &hcl.File{Body: merged}, Ctx: ctx}
	if err := ev.SetVariables(opts.Vars); err != nil {
		return nil, err
	}
	if err := ev.SetLocals(); err != nil {
		return nil, err
	}
	r := &schema.Realm{}
	// Schemas.
	for _, blk := range merged.BlocksOfType("schema") {
		if len(blk.Labels) != 1 {
			return nil, fmt.Errorf("schemahcl: schema block must have exactly one label")
		}
		if _, ok := r.Schema(blk.Labels[0]); ok {
			return nil, fmt.Errorf("schemahcl: duplicate schema %q", blk.Labels[0])
		}
		s := &schema.Schema{Name: blk.Labels[0], Realm: r}
		attrs, err := u.evalAttrs(blk.Body)
		if err != nil {
			return nil, err
		}
		if c, ok := attrs["comment"]; ok && c.Kind() == hcl.KindString {
			s.Attrs = append(s.Attrs, &schema.Comment{Text: c.AsString()})
		}
		r.Schemas = append(r.Schemas, s)
	}
	// Tables: first pass creates tables and columns.
	type pending struct {
		t   *schema.Table
		blk *hcl.Block
	}
	var tables []pending
	for _, blk := range merged.BlocksOfType("table") {
		t, err := u.tableHeader(r, blk)
		if err != nil {
			return nil, err
		}
		tables = append(tables, pending{t: t, blk: blk})
	}
	for _, p := range tables {
		u.table = p.t
		if err := u.columns(p.t, p.blk); err != nil {
			return nil, err
		}
	}
	// Second pass: keys, indexes and checks.
	for _, p := range tables {
		u.table = p.t
		if err := u.tableConstraints(r, p.t, p.blk); err != nil {
			return nil, err
		}
	}
	u.table = nil
	return r, nil
}

type unmarshaler struct {
	reg   *Registry
	ctx   *hcl.EvalContext
	table *schema.Table
}

func (u *unmarshaler) evalAttrs(body *hcl.Body) (map[string]hcl.Value, error) {
	out := map[string]hcl.Value{}
	for _, a := range body.Attributes {
		v, diags := hcl.Eval(a.Expr, u.ctx)
		if diags.HasErrors() {
			return nil, diags
		}
		out[a.Name] = v
	}
	return out, nil
}

// resolveRef resolves references to schema resources and type names.
func (u *unmarshaler) resolveRef(trav hcl.Traversal, _ *hcl.EvalContext) (hcl.Value, hcl.Diagnostics, bool) {
	root := trav.RootName()
	switch {
	case refRoots[root]:
		path, diags := refPath(trav)
		if diags.HasErrors() {
			return hcl.NullVal, diags, true
		}
		return hcl.RefVal(path), nil, true
	case enumValues[root] && len(trav) == 1:
		return hcl.StringVal(root), nil, true
	case len(trav) == 1:
		if _, ok := u.reg.byName[root]; ok {
			return hcl.TypeValue(&hcl.TypeVal{Name: root}), nil, true
		}
	}
	return hcl.NullVal, nil, false
}

// resolveFunc resolves type constructor calls such as varchar(255).
func (u *unmarshaler) resolveFunc(name string) (*hcl.Function, bool) {
	spec, ok := u.reg.byName[name]
	if !ok {
		return nil, false
	}
	return &hcl.Function{
		VarParam: &hcl.Param{Name: "args", AllowAny: true},
		Impl: func(args []hcl.Value) (hcl.Value, error) {
			if len(args) > len(spec.Attrs) {
				return hcl.NullVal, fmt.Errorf("type %q expects at most %d argument(s)", name, len(spec.Attrs))
			}
			return hcl.TypeValue(&hcl.TypeVal{Name: name, Args: args}), nil
		},
	}, true
}

// refPath converts a traversal such as table.users.column.id to $table.users.$column.id.
func refPath(trav hcl.Traversal) (string, hcl.Diagnostics) {
	var parts []string
	i := 0
	for i < len(trav) {
		kind := ""
		switch s := trav[i].(type) {
		case hcl.TraverseRoot:
			kind = s.Name
		case hcl.TraverseAttr:
			kind = s.Name
		default:
			return "", hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Invalid reference", Detail: "Unexpected index in resource reference.", Subject: trav[i].Range().Ptr()}}
		}
		if i+1 >= len(trav) {
			return "", hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Invalid reference", Detail: fmt.Sprintf("Reference to %q must be followed by a resource name.", kind), Subject: trav[i].Range().Ptr()}}
		}
		name := ""
		switch s := trav[i+1].(type) {
		case hcl.TraverseAttr:
			name = s.Name
		case hcl.TraverseIndex:
			sv, err := hcl.Convert(s.Key, &hcl.TypeConstraint{Kind: hcl.KindString})
			if err != nil {
				return "", hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Invalid reference", Detail: "Resource name must be a string.", Subject: s.SrcRange.Ptr()}}
			}
			name = sv.AsString()
		default:
			return "", hcl.Diagnostics{&hcl.Diagnostic{Severity: hcl.DiagError, Summary: "Invalid reference", Detail: "Unexpected reference step.", Subject: trav[i+1].Range().Ptr()}}
		}
		parts = append(parts, "$"+kind+"."+name)
		i += 2
	}
	return strings.Join(parts, "."), nil
}

// refParts splits a reference path into (kind, name) pairs.
func refParts(path string) [][2]string {
	var out [][2]string
	for _, seg := range strings.Split(path, ".$") {
		seg = strings.TrimPrefix(seg, "$")
		kv := strings.SplitN(seg, ".", 2)
		if len(kv) != 2 {
			out = append(out, [2]string{kv[0], ""})
			continue
		}
		out = append(out, [2]string{kv[0], kv[1]})
	}
	return out
}

func (u *unmarshaler) tableHeader(r *schema.Realm, blk *hcl.Block) (*schema.Table, error) {
	var name, qualifier string
	switch len(blk.Labels) {
	case 1:
		name = blk.Labels[0]
	case 2:
		qualifier, name = blk.Labels[0], blk.Labels[1]
	default:
		return nil, fmt.Errorf("schemahcl: table block must have one or two labels")
	}
	t := &schema.Table{Name: name}
	sa := blk.Body.Attribute("schema")
	if sa == nil {
		return nil, fmt.Errorf("schemahcl: missing schema reference for table %q", name)
	}
	v, diags := hcl.Eval(sa.Expr, u.ctx)
	if diags.HasErrors() {
		return nil, diags
	}
	if v.Kind() != hcl.KindRef {
		return nil, fmt.Errorf("schemahcl: table %q: schema attribute must be a reference to a schema", name)
	}
	parts := refParts(v.Ref().Path)
	if len(parts) != 1 || parts[0][0] != "schema" {
		return nil, fmt.Errorf("schemahcl: table %q: invalid schema reference %q", name, v.Ref().Path)
	}
	s, ok := r.Schema(parts[0][1])
	if !ok {
		return nil, fmt.Errorf("schemahcl: schema %q was not found", parts[0][1])
	}
	if qualifier != "" && qualifier != s.Name {
		return nil, fmt.Errorf("schemahcl: table %q: qualifier %q does not match schema %q", name, qualifier, s.Name)
	}
	if _, exists := s.Table(name); exists {
		return nil, fmt.Errorf("schemahcl: duplicate table %q in schema %q", name, s.Name)
	}
	t.Schema = s
	s.Tables = append(s.Tables, t)
	return t, nil
}

func (u *unmarshaler) columns(t *schema.Table, blk *hcl.Block) error {
	attrs, err := u.evalAttrs(blk.Body)
	if err != nil {
		return err
	}
	for k, v := range attrs {
		switch k {
		case "schema":
		case "comment":
			if v.Kind() == hcl.KindString {
				t.Attrs = append(t.Attrs, &schema.Comment{Text: v.AsString()})
			}
		case "without_rowid":
			if v.True() {
				t.Attrs = append(t.Attrs, &sqlite.WithoutRowID{})
			}
		case "strict":
			if v.True() {
				t.Attrs = append(t.Attrs, &sqlite.Strict{})
			}
		}
	}
	for _, cb := range blk.Body.BlocksOfType("column") {
		if len(cb.Labels) != 1 {
			return fmt.Errorf("schemahcl: column block must have exactly one label")
		}
		c := &schema.Column{Name: cb.Labels[0], Type: &schema.ColumnType{}}
		if _, exists := t.Column(c.Name); exists {
			return fmt.Errorf("schemahcl: duplicate column %q in table %q", c.Name, t.Name)
		}
		ca, err := u.evalAttrs(cb.Body)
		if err != nil {
			return err
		}
		tv, ok := ca["type"]
		if !ok {
			return fmt.Errorf("schemahcl: missing type for column %q in table %q", c.Name, t.Name)
		}
		c.Type.Type, c.Type.Raw, err = u.convertType(tv)
		if err != nil {
			return fmt.Errorf("schemahcl: column %q: %w", c.Name, err)
		}
		if nv, ok := ca["null"]; ok {
			if nv.Kind() != hcl.KindBool {
				return fmt.Errorf("schemahcl: column %q: null attribute must be a boolean", c.Name)
			}
			c.Type.Null = nv.True()
		}
		if dv, ok := ca["default"]; ok {
			c.Default, err = convertDefault(dv)
			if err != nil {
				return fmt.Errorf("schemahcl: column %q: %w", c.Name, err)
			}
		}
		if av, ok := ca["auto_increment"]; ok && av.True() {
			c.Attrs = append(c.Attrs, &sqlite.AutoIncrement{})
		}
		if cv, ok := ca["comment"]; ok && cv.Kind() == hcl.KindString {
			c.Attrs = append(c.Attrs, &schema.Comment{Text: cv.AsString()})
		}
		for _, as := range cb.Body.BlocksOfType("as") {
			ga, err := u.evalAttrs(as.Body)
			if err != nil {
				return err
			}
			g := &schema.GeneratedExpr{Type: "VIRTUAL"}
			if e, ok := ga["expr"]; ok && e.Kind() == hcl.KindString {
				g.Expr = e.AsString()
			}
			if ty, ok := ga["type"]; ok && ty.Kind() == hcl.KindString {
				g.Type = strings.ToUpper(ty.AsString())
			}
			c.Attrs = append(c.Attrs, g)
		}
		if gv, ok := ca["as"]; ok && gv.Kind() == hcl.KindString {
			c.Attrs = append(c.Attrs, &schema.GeneratedExpr{Expr: gv.AsString(), Type: "VIRTUAL"})
		}
		t.Columns = append(t.Columns, c)
	}
	return nil
}

// convertType converts an HCL type value to a schema type.
func (u *unmarshaler) convertType(v hcl.Value) (schema.Type, string, error) {
	switch v.Kind() {
	case hcl.KindType:
		tv := v.Type()
		spec, ok := u.reg.byName[tv.Name]
		if !ok {
			return nil, "", fmt.Errorf("unknown type %q", tv.Name)
		}
		name := strings.ReplaceAll(spec.Name, "_", " ")
		if len(tv.Args) > 0 {
			args := make([]string, 0, len(tv.Args))
			for _, a := range tv.Args {
				args = append(args, a.GoString())
			}
			name += "(" + strings.Join(args, ",") + ")"
		}
		t, err := u.reg.Parse(name)
		if err != nil {
			return nil, "", err
		}
		return t, name, nil
	case hcl.KindRaw:
		t, err := u.reg.Parse(v.AsString())
		if err != nil {
			return nil, "", err
		}
		return t, v.AsString(), nil
	case hcl.KindString:
		t, err := u.reg.Parse(v.AsString())
		if err != nil {
			return nil, "", err
		}
		return t, v.AsString(), nil
	}
	return nil, "", fmt.Errorf("unexpected type value %s", v.GoString())
}

// convertDefault converts an HCL default value to a schema expression.
func convertDefault(v hcl.Value) (schema.Expr, error) {
	switch v.Kind() {
	case hcl.KindString:
		return &schema.Literal{V: "'" + strings.ReplaceAll(v.AsString(), "'", "''") + "'"}, nil
	case hcl.KindNumber:
		return &schema.Literal{V: hcl.NumberString(v.AsBigFloat())}, nil
	case hcl.KindBool:
		return &schema.Literal{V: strconv.FormatBool(v.True())}, nil
	case hcl.KindRaw:
		return &schema.RawExpr{X: v.AsString()}, nil
	case hcl.KindNull:
		return nil, nil
	}
	return nil, fmt.Errorf("unsupported default value %s", v.GoString())
}

func (u *unmarshaler) tableConstraints(r *schema.Realm, t *schema.Table, blk *hcl.Block) error {
	// Primary key.
	pks := blk.Body.BlocksOfType("primary_key")
	if len(pks) > 1 {
		return fmt.Errorf("schemahcl: multiple primary keys defined for table %q", t.Name)
	}
	for _, pb := range pks {
		pk := &schema.Index{Name: "PRIMARY", Unique: true, Table: t}
		parts, err := u.indexParts(t, pb)
		if err != nil {
			return fmt.Errorf("schemahcl: table %q primary key: %w", t.Name, err)
		}
		pk.Parts = parts
		t.PrimaryKey = pk
	}
	// Indexes.
	for _, ib := range blk.Body.BlocksOfType("index") {
		if len(ib.Labels) != 1 {
			return fmt.Errorf("schemahcl: index block must have exactly one label")
		}
		idx := &schema.Index{Name: ib.Labels[0], Table: t}
		ia, err := u.evalAttrs(ib.Body)
		if err != nil {
			return err
		}
		if uv, ok := ia["unique"]; ok {
			idx.Unique = uv.True()
		}
		parts, err := u.indexParts(t, ib)
		if err != nil {
			return fmt.Errorf("schemahcl: index %q: %w", idx.Name, err)
		}
		idx.Parts = parts
		if wv, ok := ia["where"]; ok && wv.Kind() == hcl.KindString {
			idx.Attrs = append(idx.Attrs, &schema.IndexPredicate{P: wv.AsString()})
		}
		if cv, ok := ia["comment"]; ok && cv.Kind() == hcl.KindString {
			idx.Attrs = append(idx.Attrs, &schema.Comment{Text: cv.AsString()})
		}
		t.AddIndexes(idx)
	}
	// Foreign keys.
	for _, fb := range blk.Body.BlocksOfType("foreign_key") {
		if len(fb.Labels) != 1 {
			return fmt.Errorf("schemahcl: foreign_key block must have exactly one label")
		}
		fk := &schema.ForeignKey{Symbol: fb.Labels[0], Table: t}
		fa, err := u.evalAttrs(fb.Body)
		if err != nil {
			return err
		}
		cols, err := u.columnRefs(r, t, fa["columns"])
		if err != nil {
			return fmt.Errorf("schemahcl: foreign_key %q: %w", fk.Symbol, err)
		}
		fk.Columns = cols
		rv, ok := fa["ref_columns"]
		if !ok {
			return fmt.Errorf("schemahcl: foreign_key %q: missing ref_columns", fk.Symbol)
		}
		refCols, err := u.columnRefs(r, t, rv)
		if err != nil {
			return fmt.Errorf("schemahcl: foreign_key %q: %w", fk.Symbol, err)
		}
		fk.RefColumns = refCols
		if len(refCols) > 0 {
			fk.RefTable = u.columnTable(r, t, rv)
		}
		if v, ok := fa["on_update"]; ok {
			fk.OnUpdate = schema.ReferenceOption(strings.ReplaceAll(v.AsString(), "_", " "))
		}
		if v, ok := fa["on_delete"]; ok {
			fk.OnDelete = schema.ReferenceOption(strings.ReplaceAll(v.AsString(), "_", " "))
		}
		t.AddForeignKeys(fk)
	}
	// Checks.
	for _, cb := range blk.Body.BlocksOfType("check") {
		ck := &schema.Check{}
		if len(cb.Labels) > 0 {
			ck.Name = cb.Labels[0]
		}
		ca, err := u.evalAttrs(cb.Body)
		if err != nil {
			return err
		}
		ev, ok := ca["expr"]
		if !ok || ev.Kind() != hcl.KindString {
			return fmt.Errorf("schemahcl: check constraint in table %q: missing expr", t.Name)
		}
		ck.Expr = ev.AsString()
		t.Attrs = append(t.Attrs, ck)
	}
	return nil
}

// indexParts reads the columns/on blocks of an index-like block.
func (u *unmarshaler) indexParts(t *schema.Table, blk *hcl.Block) ([]*schema.IndexPart, error) {
	attrs, err := u.evalAttrs(blk.Body)
	if err != nil {
		return nil, err
	}
	var parts []*schema.IndexPart
	if cv, ok := attrs["columns"]; ok {
		cols, err := u.columnRefs(t.Schema.Realm, t, cv)
		if err != nil {
			return nil, err
		}
		for i, c := range cols {
			parts = append(parts, &schema.IndexPart{SeqNo: i + 1, C: c})
		}
	}
	for _, ob := range blk.Body.BlocksOfType("on") {
		oa, err := u.evalAttrs(ob.Body)
		if err != nil {
			return nil, err
		}
		p := &schema.IndexPart{SeqNo: len(parts) + 1}
		if dv, ok := oa["desc"]; ok {
			p.Desc = dv.True()
		}
		if cv, ok := oa["column"]; ok {
			cols, err := u.columnRefs(t.Schema.Realm, t, cv)
			if err != nil {
				return nil, err
			}
			if len(cols) != 1 {
				return nil, fmt.Errorf("expected a single column reference")
			}
			p.C = cols[0]
		}
		if xv, ok := oa["expr"]; ok && xv.Kind() == hcl.KindString {
			p.X = &schema.RawExpr{X: xv.AsString()}
		}
		if p.C == nil && p.X == nil {
			return nil, fmt.Errorf("index part must have either a column or an expression")
		}
		if cv, ok := oa["collate"]; ok && cv.Kind() == hcl.KindString {
			p.Attrs = append(p.Attrs, &schema.Collation{V: cv.AsString()})
		}
		parts = append(parts, p)
	}
	if len(parts) == 0 && blk.Type != "primary_key" {
		return nil, fmt.Errorf("missing columns")
	}
	return parts, nil
}

// columnRefs resolves a reference or list of references to columns.
func (u *unmarshaler) columnRefs(r *schema.Realm, t *schema.Table, v hcl.Value) ([]*schema.Column, error) {
	var refs []hcl.Value
	switch v.Kind() {
	case hcl.KindRef:
		refs = []hcl.Value{v}
	case hcl.KindTuple:
		refs = v.Elements()
	case hcl.KindNull:
		return nil, nil
	default:
		return nil, fmt.Errorf("expected column references, got %s", v.TypeName())
	}
	var cols []*schema.Column
	for _, rv := range refs {
		if rv.Kind() != hcl.KindRef {
			return nil, fmt.Errorf("expected a column reference, got %s", rv.TypeName())
		}
		c, err := u.columnRef(r, t, rv.Ref().Path)
		if err != nil {
			return nil, err
		}
		cols = append(cols, c)
	}
	return cols, nil
}

// columnRef resolves a single column reference.
func (u *unmarshaler) columnRef(r *schema.Realm, t *schema.Table, path string) (*schema.Column, error) {
	parts := refParts(path)
	switch {
	case len(parts) == 1 && parts[0][0] == "column":
		c, ok := t.Column(parts[0][1])
		if !ok {
			return nil, fmt.Errorf("column %q was not found in table %q", parts[0][1], t.Name)
		}
		return c, nil
	case len(parts) == 2 && parts[0][0] == "table" && parts[1][0] == "column":
		rt, err := findTable(r, t.Schema, parts[0][1])
		if err != nil {
			return nil, err
		}
		c, ok := rt.Column(parts[1][1])
		if !ok {
			return nil, fmt.Errorf("column %q was not found in table %q", parts[1][1], rt.Name)
		}
		return c, nil
	case len(parts) == 3 && parts[0][0] == "schema" && parts[1][0] == "table" && parts[2][0] == "column":
		s, ok := r.Schema(parts[0][1])
		if !ok {
			return nil, fmt.Errorf("schema %q was not found", parts[0][1])
		}
		rt, ok := s.Table(parts[1][1])
		if !ok {
			return nil, fmt.Errorf("table %q was not found in schema %q", parts[1][1], s.Name)
		}
		c, ok := rt.Column(parts[2][1])
		if !ok {
			return nil, fmt.Errorf("column %q was not found in table %q", parts[2][1], rt.Name)
		}
		return c, nil
	}
	return nil, fmt.Errorf("invalid column reference %q", strings.ReplaceAll(path, "$", ""))
}

// columnTable returns the table of the first referenced column.
func (u *unmarshaler) columnTable(r *schema.Realm, t *schema.Table, v hcl.Value) *schema.Table {
	var first hcl.Value
	switch v.Kind() {
	case hcl.KindRef:
		first = v
	case hcl.KindTuple:
		if v.Len() > 0 {
			first = v.Elements()[0]
		}
	}
	if first.Kind() != hcl.KindRef {
		return t
	}
	parts := refParts(first.Ref().Path)
	switch {
	case len(parts) == 2 && parts[0][0] == "table":
		rt, err := findTable(r, t.Schema, parts[0][1])
		if err == nil {
			return rt
		}
	case len(parts) == 3 && parts[0][0] == "schema":
		if s, ok := r.Schema(parts[0][1]); ok {
			if rt, ok := s.Table(parts[1][1]); ok {
				return rt
			}
		}
	}
	return t
}

func findTable(r *schema.Realm, s *schema.Schema, name string) (*schema.Table, error) {
	if s != nil {
		if t, ok := s.Table(name); ok {
			return t, nil
		}
	}
	var found *schema.Table
	for _, sc := range r.Schemas {
		if t, ok := sc.Table(name); ok {
			if found != nil {
				return nil, fmt.Errorf("ambiguous table reference %q", name)
			}
			found = t
		}
	}
	if found == nil {
		return nil, fmt.Errorf("table %q was not found", name)
	}
	return found, nil
}
