// Dir is a local migration directory.
type Dir struct {
	Path string
}

// NewDir opens a migration directory.
func NewDir(path string) (*Dir, error) {
	fi, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: %w", err)
	}
	if !fi.IsDir() {
		return nil, fmt.Errorf("sql/migrate: %q is not a dir", path)
	}
	return &Dir{Path: path}, nil
}

// File is a migration file.
type File struct {
	Name    string
	Content []byte
}

// Version returns the version part of the file name.
func (f *File) Version() string {
	return strings.SplitN(strings.TrimSuffix(f.Name, ".sql"), "_", 2)[0]
}

// Desc returns the description part of the file name.
func (f *File) Desc() string {
	parts := strings.SplitN(strings.TrimSuffix(f.Name, ".sql"), "_", 2)
	if len(parts) == 1 {
		return ""
	}
	return parts[1]
}

// Files returns the migration files of the directory sorted by name.
func (d *Dir) Files() ([]*File, error) {
	entries, err := os.ReadDir(d.Path)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: %w", err)
	}
	var files []*File
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".sql") {
			continue
		}
		b, err := os.ReadFile(filepath.Join(d.Path, e.Name()))
		if err != nil {
			return nil, fmt.Errorf("sql/migrate: read file %q: %w", e.Name(), err)
		}
		files = append(files, &File{Name: e.Name(), Content: b})
	}
	sort.Slice(files, func(i, j int) bool { return files[i].Name < files[j].Name })
	return files, nil
}

// WriteFile writes a file to the directory.
func (d *Dir) WriteFile(name string, b []byte) error {
	return os.WriteFile(filepath.Join(d.Path, name), b, 0644)
}

// HashFile represents the atlas.sum file content.
type HashFile []struct{ N, H string }

// Checksum computes the checksum of the directory.
func (d *Dir) Checksum() (HashFile, error) {
	files, err := d.Files()
	if err != nil {
		return nil, err
	}
	var hf HashFile
	h := sha256.New()
	for _, f := range files {
		if _, err := h.Write([]byte(f.Name)); err != nil {
			return nil, err
		}
		// Files marked with "atlas:sum ignore" are not included in the hash.
		if mode, ok := directive(string(f.Content), "sum"); !ok || mode != "ignore" {
			if _, err := h.Write(f.Content); err != nil {
				return nil, err
			}
		}
		hf = append(hf, struct{ N, H string }{f.Name, base64.StdEncoding.EncodeToString(h.Sum(nil))})
	}
	return hf, nil
}

// Sum returns the checksum of the hash file.
func (f HashFile) Sum() string {
	sha := sha256.New()
	for _, f := range f {
		sha.Write([]byte(f.N))
		sha.Write([]byte(f.H))
	}
	return base64.StdEncoding.EncodeToString(sha.Sum(nil))
}

// MarshalText implements encoding.TextMarshaler.
func (f HashFile) MarshalText() ([]byte, error) {
	buf := new(bytes.Buffer)
	for _, f := range f {
		fmt.Fprintf(buf, "%s h1:%s\n", f.N, f.H)
	}
	return []byte(fmt.Sprintf("h1:%s\n%s", f.Sum(), buf)), nil
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (f *HashFile) UnmarshalText(b []byte) error {
	sc := bufio.NewScanner(bytes.NewReader(b))
	// The first line contains the sum.
	sc.Scan()
	sum := strings.TrimPrefix(sc.Text(), "h1:")
	for sc.Scan() {
		li := strings.SplitN(sc.Text(), " ", 2)
		if len(li) != 2 {
			return ErrChecksumFormat
		}
