package migrate

import (
	"fmt"
	"strings"
)

// Stmt is a single SQL statement of a migration file.
type Stmt struct {
	Pos      int
	Text     string
	Comments []string
}

// Stmts parses the SQL statements of the file. Statements are separated by
// semicolons (or a custom delimiter set with the "atlas:delimiter" directive).
func (f *File) Stmts() ([]*Stmt, error) {
	return ScanStmts(string(f.Content))
}

// StmtDecls returns the statement texts of the file.
func (f *File) StmtDecls() ([]string, error) {
	stmts, err := f.Stmts()
	if err != nil {
		return nil, err
	}
	out := make([]string, len(stmts))
	for i, s := range stmts {
		out[i] = s.Text
	}
	return out, nil
}

// ScanStmts splits the input into statements.
func ScanStmts(input string) ([]*Stmt, error) {
	delim := ";"
	if d, ok := directive(input, "delimiter"); ok && d != "" {
		delim = unescapeDelim(d)
	}
	var (
		stmts    []*Stmt
		comments []string
		b        strings.Builder
		start    = -1
		i        = 0
		depth    = 0
	)
	flush := func(end int) {
		text := strings.TrimSpace(b.String())
		b.Reset()
		if text == "" {
			start = -1
			return
		}
		stmts = append(stmts, &Stmt{Pos: start, Text: text, Comments: comments})
		comments = nil
		start = -1
	}
	for i < len(input) {
		c := input[i]
		// Leading whitespace and comments between statements.
		if b.Len() == 0 {
			switch {
			case c == ' ' || c == '\t' || c == '\n' || c == '\r':
				i++
				continue
			case strings.HasPrefix(input[i:], "--"):
				j := strings.IndexByte(input[i:], '\n')
				var line string
				if j < 0 {
					line = input[i:]
					j = len(input) - i
				} else {
					line = input[i : i+j]
					j++
				}
				comments = append(comments, strings.TrimSpace(line))
				i += j
				continue
			case strings.HasPrefix(input[i:], "/*"):
				j := strings.Index(input[i+2:], "*/")
				if j < 0 {
					return nil, fmt.Errorf("unclosed comment at position %d", i)
				}
				comments = append(comments, strings.TrimSpace(input[i:i+j+4]))
				i += j + 4
				continue
			}
			start = i
		}
		switch {
		case strings.HasPrefix(input[i:], delim) && depth == 0:
			// Include the delimiter in the statement text for ";".
			if delim == ";" {
				b.WriteString(";")
			}
			i += len(delim)
			flush(i)
			continue
		case c == '\'' || c == '"' || c == '`':
			j := i + 1
			for j < len(input) {
				if input[j] == c {
					if j+1 < len(input) && input[j+1] == c {
						j += 2
						continue
					}
					break
				}
				if input[j] == '\\' && c == '\'' && j+1 < len(input) {
					j++
				}
				j++
			}
			if j >= len(input) {
				return nil, fmt.Errorf("unclosed quote at position %d", i)
			}
			b.WriteString(input[i : j+1])
			i = j + 1
			continue
		case c == '[':
			j := strings.IndexByte(input[i:], ']')
			if j < 0 {
				b.WriteByte(c)
				i++
				continue
			}
			b.WriteString(input[i : i+j+1])
			i += j + 1
			continue
		case strings.HasPrefix(input[i:], "--"):
			j := strings.IndexByte(input[i:], '\n')
			if j < 0 {
				j = len(input) - i
			}
			b.WriteString(input[i : i+j])
			i += j
			continue
		case strings.HasPrefix(input[i:], "/*"):
			j := strings.Index(input[i+2:], "*/")
			if j < 0 {
				return nil, fmt.Errorf("unclosed comment at position %d", i)
			}
			b.WriteString(input[i : i+j+4])
			i += j + 4
			continue
		case c == '(':
			depth++
		case c == ')':
			if depth > 0 {
				depth--
			}
		case strings.HasPrefix(strings.ToUpper(input[i:]), "BEGIN") && isWordBoundary(input, i, 5) && delim == ";":
			// Trigger bodies: BEGIN ... END; contain semicolons.
			j := findTriggerEnd(input, i+5)
			if j > 0 {
				b.WriteString(input[i:j])
				i = j
				continue
			}
		}
		b.WriteByte(c)
		i++
	}
	if strings.TrimSpace(b.String()) != "" {
		flush(len(input))
	}
	return stmts, nil
}

func isWordBoundary(s string, i, n int) bool {
	if i > 0 {
		p := s[i-1]
		if isIdentByte(p) {
			return false
		}
	}
	if i+n < len(s) && isIdentByte(s[i+n]) {
		return false
	}
	return true
}

func isIdentByte(c byte) bool {
	return c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9'
}

// findTriggerEnd finds the position right after the END keyword matching a
// BEGIN at the given position.
func findTriggerEnd(s string, from int) int {
	depth := 1
	i := from
	for i < len(s) {
		c := s[i]
		switch {
		case c == '\'' || c == '"' || c == '`':
			j := i + 1
			for j < len(s) && s[j] != c {
				j++
			}
			i = j + 1
			continue
		case strings.HasPrefix(s[i:], "--"):
			j := strings.IndexByte(s[i:], '\n')
			if j < 0 {
				return -1
			}
			i += j
			continue
		}
		up := strings.ToUpper(s[i:])
		switch {
		case strings.HasPrefix(up, "BEGIN") && isWordBoundary(s, i, 5):
			depth++
			i += 5
			continue
		case strings.HasPrefix(up, "CASE") && isWordBoundary(s, i, 4):
			depth++
			i += 4
			continue
		case strings.HasPrefix(up, "END") && isWordBoundary(s, i, 3):
			depth--
			i += 3
			if depth == 0 {
				return i
			}
			continue
		}
		i++
	}
	return -1
}

func unescapeDelim(d string) string {
	d = strings.ReplaceAll(d, `\n`, "\n")
	d = strings.ReplaceAll(d, `\r`, "\r")
	d = strings.ReplaceAll(d, `\t`, "\t")
	return d
}
