package migrate

import (
	"errors"
	"fmt"
	"strings"
	"time"

	"atlas/internal/sqlite3"
)

// NotCleanError is returned when the database is not clean.
type NotCleanError struct {
	Reason string
}

func (e *NotCleanError) Error() string {
	return "sql/migrate: connected database is not clean: " + e.Reason
}

// HistoryNonLinearError is returned when the migration history is not linear.
type HistoryNonLinearError struct {
	Missing []string
}

func (e *HistoryNonLinearError) Error() string {
	return fmt.Sprintf("sql/migrate: migration file %s was added out of order. See: https://atlasgo.io/versioned/apply#non-linear-error", strings.Join(e.Missing, ", "))
}

// ExecOptions configure the executor.
type ExecOptions struct {
	DB              *sqlite3.DB
	Dir             *Dir
	Revisions       *RevisionStore
	Baseline        string
	AllowDirty      bool
	TxMode          string // none, file, all
	ExecOrder       string // linear, linear-skip, non-linear
	OperatorVersion string
	DryRun          bool
	// CheckClean returns an error if the connected database is not clean.
	CheckClean func() error
	// Logger receives execution events.
	Logger Logger
}

// Logger receives execution events.
type Logger interface {
	LogExecution(current, target string, files []*File)
	LogFile(f *File, version string, skip int)
	LogStmt(stmt string)
	LogError(err error)
	LogDone()
}

// Executor executes migration files.
type Executor struct {
	opts *ExecOptions
}

// NewExecutor returns a new executor.
func NewExecutor(opts *ExecOptions) (*Executor, error) {
	if opts.TxMode == "" {
		opts.TxMode = "file"
	}
	if opts.ExecOrder == "" {
		opts.ExecOrder = "linear"
	}
	switch opts.TxMode {
	case "none", "file", "all":
	default:
		return nil, fmt.Errorf("unknown tx-mode %q", opts.TxMode)
	}
	switch opts.ExecOrder {
	case "linear", "linear-skip", "non-linear":
	default:
		return nil, fmt.Errorf("unknown exec-order %q", opts.ExecOrder)
	}
	return &Executor{opts: opts}, nil
}

// Pending returns the migration files that have not been applied yet.
func (e *Executor) Pending() ([]*File, error) {
	if err := Validate(e.opts.Dir); err != nil {
		return nil, fmt.Errorf("sql/migrate: validate migration directory: %w", err)
	}
	revs, err := e.opts.Revisions.ReadRevisions()
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: read revisions: %w", err)
	}
	files, err := e.opts.Dir.Files()
	if err != nil {
		return nil, err
	}
	var pending []*File
	switch {
	case len(revs) == 0 && e.opts.Baseline != "":
		idx := -1
		for i, f := range files {
			if f.Version() == e.opts.Baseline {
				idx = i
				break
			}
		}
		if idx == -1 {
			return nil, fmt.Errorf("sql/migrate: baseline version %q not found", e.opts.Baseline)
		}
		if !e.opts.DryRun {
			if err := e.opts.Revisions.Init(); err != nil {
				return nil, err
			}
			if err := e.opts.Revisions.WriteRevision(&Revision{
				Version:         files[idx].Version(),
				Description:     files[idx].Desc(),
				Type:            RevisionTypeBaseline,
				ExecutedAt:      time.Now(),
				Hash:            e.fileHash(files[idx]),
				OperatorVersion: e.opts.OperatorVersion,
			}); err != nil {
				return nil, err
			}
		}
		pending = files[idx+1:]
	case len(revs) == 0:
		if !e.opts.AllowDirty && e.opts.CheckClean != nil {
			if err := e.opts.CheckClean(); err != nil {
				return nil, err
			}
		}
		pending = files
	default:
		// Find the index of the last applied revision in the directory.
		last := revs[len(revs)-1]
		idx := -1
		for i, f := range files {
			if f.Version() == last.Version {
				idx = i
				break
			}
		}
		if idx == -1 {
			return nil, fmt.Errorf("sql/migrate: migration file for version %q not found", last.Version)
		}
		// Ensure the applied revisions match the migration files.
		applied := map[string]bool{}
		for _, r := range revs {
			applied[r.Version] = true
		}
		var missing []string
		for _, f := range files[:idx] {
			if !applied[f.Version()] {
				missing = append(missing, f.Version())
			}
		}
		if len(missing) > 0 {
			switch e.opts.ExecOrder {
			case "linear":
				return nil, &HistoryNonLinearError{Missing: missing}
			case "non-linear":
				for _, f := range files[:idx] {
					if !applied[f.Version()] {
						pending = append(pending, f)
					}
				}
			}
		}
		if !last.Done() {
			pending = append(pending, files[idx])
		}
		pending = append(pending, files[idx+1:]...)
	}
	if len(pending) == 0 {
		return nil, ErrNoPendingFiles
	}
	return pending, nil
}

// fileHash returns the hash of the file as stored in the sum file.
func (e *Executor) fileHash(f *File) string {
	hf, err := ReadSumFile(e.opts.Dir)
	if err != nil {
		return ""
	}
	for _, h := range hf {
		if h.N == f.Name {
			return h.H
		}
	}
	return ""
}

// Execute applies the given files.
func (e *Executor) Execute(files []*File) error {
	if len(files) == 0 {
		return nil
	}
	if !e.opts.DryRun {
		if err := e.opts.Revisions.Init(); err != nil {
			return fmt.Errorf("sql/migrate: init revisions table: %w", err)
		}
	}
	revs, _ := e.opts.Revisions.ReadRevisions()
	byVersion := map[string]*Revision{}
	for _, r := range revs {
		byVersion[r.Version] = r
	}
	all := e.opts.TxMode == "all" && !e.opts.DryRun
	if all {
		if err := e.opts.DB.Exec("BEGIN"); err != nil {
			return fmt.Errorf("sql/migrate: begin transaction: %w", err)
		}
	}
	for _, f := range files {
		prev := byVersion[f.Version()]
		if err := e.execFile(f, prev); err != nil {
			if all {
				_ = e.opts.DB.Exec("ROLLBACK")
			}
			return err
		}
	}
	if all {
		if err := e.opts.DB.Exec("COMMIT"); err != nil {
			return fmt.Errorf("sql/migrate: commit transaction: %w", err)
		}
	}
	return nil
}

func (e *Executor) execFile(f *File, prev *Revision) error {
	stmts, err := f.Stmts()
	if err != nil {
		return fmt.Errorf("sql/migrate: scanning statements from %q: %w", f.Name, err)
	}
	skip := 0
	if prev != nil && !prev.Done() && prev.Applied > 0 {
		skip = prev.Applied
	}
	if e.opts.Logger != nil {
		e.opts.Logger.LogFile(f, f.Version(), skip)
	}
	rev := &Revision{
		Version:         f.Version(),
		Description:     f.Desc(),
		Type:            RevisionTypeExecute,
		Total:           len(stmts),
		ExecutedAt:      time.Now(),
		Hash:            e.fileHash(f),
		OperatorVersion: e.opts.OperatorVersion,
	}
	if prev != nil {
		rev.Applied = prev.Applied
		rev.PartialHashes = prev.PartialHashes
	}
	fileTx := e.opts.TxMode == "file" && !e.opts.DryRun
	if fileTx {
		if err := e.opts.DB.Exec("BEGIN"); err != nil {
			return fmt.Errorf("sql/migrate: begin transaction: %w", err)
		}
	}
	start := time.Now()
	for i, s := range stmts {
		if i < skip {
			continue
		}
		if e.opts.Logger != nil {
			e.opts.Logger.LogStmt(s.Text)
		}
		if e.opts.DryRun {
			continue
		}
		if err := e.opts.DB.Exec(s.Text); err != nil {
			if fileTx {
				_ = e.opts.DB.Exec("ROLLBACK")
				rev.Applied = skip
			}
			rev.Error = err.Error()
			rev.ErrorStmt = s.Text
			rev.ExecutionTime = time.Since(start)
			if e.opts.TxMode != "all" {
				_ = e.opts.Revisions.WriteRevision(rev)
			}
			if e.opts.Logger != nil {
				e.opts.Logger.LogError(err)
			}
			return fmt.Errorf("sql/migrate: executing statement %q from version %q: %w", s.Text, f.Version(), err)
		}
		rev.Applied = i + 1
		if e.opts.TxMode == "none" {
			rev.ExecutionTime = time.Since(start)
			rev.PartialHashes = partialHashes(stmts[:i+1])
			if i+1 == len(stmts) {
				rev.PartialHashes = nil
			}
			_ = e.opts.Revisions.WriteRevision(rev)
		}
	}
	rev.Applied = len(stmts)
	rev.PartialHashes = nil
	rev.ExecutionTime = time.Since(start)
	if e.opts.DryRun {
		return nil
	}
	if err := e.opts.Revisions.WriteRevision(rev); err != nil {
		if fileTx {
			_ = e.opts.DB.Exec("ROLLBACK")
		}
		return fmt.Errorf("sql/migrate: write revision: %w", err)
	}
	if fileTx {
		if err := e.opts.DB.Exec("COMMIT"); err != nil {
			return fmt.Errorf("sql/migrate: commit transaction: %w", err)
		}
	}
	return nil
}

func partialHashes(stmts []*Stmt) []string {
	out := make([]string, 0, len(stmts))
	for _, s := range stmts {
		out = append(out, hashString(s.Text))
	}
	return out
}

// ExecuteN executes up to n pending files (0 means all).
func (e *Executor) ExecuteN(n int) ([]*File, error) {
	pending, err := e.Pending()
	if err != nil {
		return nil, err
	}
	if n > 0 && n < len(pending) {
		pending = pending[:n]
	}
	return pending, e.Execute(pending)
}

// IsNoPending reports whether the error means there is nothing to apply.
func IsNoPending(err error) bool { return errors.Is(err, ErrNoPendingFiles) }
