type File struct {
	Name        string
	Version     string
	Description string
}

// NewFile converts a migration file.
func NewFile(f *migrate.File) File {
	return File{Name: f.Name, Version: f.Version(), Description: f.Desc()}
}

// Files converts migration files.
func Files(fs []*migrate.File) []File {
	out := make([]File, 0, len(fs))
	for _, f := range fs {
		out = append(out, NewFile(f))
	}
	return out
}

// StmtError holds a statement error.
type StmtError struct {
	Stmt string `json:"Stmt,omitempty"`
	Text string `json:"Text,omitempty"`
}

// AppliedFile is a migration file that was applied.
type AppliedFile struct {
	File
	Start   time.Time
	End     time.Time
	Skipped int
	Applied []string
	Error   *StmtError `json:"Error,omitempty"`
}

// MigrateApply is the report of the migrate apply command.
type MigrateApply struct {
	Env
	Pending []File         `json:"Pending,omitempty"`
	Applied []*AppliedFile `json:"Applied,omitempty"`
	Current string         `json:"Current,omitempty"`
	Target  string         `json:"Target,omitempty"`
	Start   time.Time
	End     time.Time
	Error   string `json:"Error,omitempty"`
}

// CountStmts returns the number of applied statements.
func (a *MigrateApply) CountStmts() int {
	n := 0
	for _, f := range a.Applied {
		n += len(f.Applied)
	}
	return n
}

// LogExecution implements migrate.Logger.
func (a *MigrateApply) LogExecution(current, target string, files []*migrate.File) {
	a.Start = time.Now()
	a.Current = current
	a.Target = target
	a.Pending = Files(files)
}

// LogFile implements migrate.Logger.
func (a *MigrateApply) LogFile(f *migrate.File, version string, skip int) {
	now := time.Now()
	if l := len(a.Applied); l > 0 {
		a.Applied[l-1].End = now
	}
	a.Applied = append(a.Applied, &AppliedFile{File: NewFile(f), Start: now, Skipped: skip})
}

// LogStmt implements migrate.Logger.
func (a *MigrateApply) LogStmt(stmt string) {
	if l := len(a.Applied); l > 0 {
		a.Applied[l-1].Applied = append(a.Applied[l-1].Applied, stmt)
	}
}

// LogError implements migrate.Logger.
func (a *MigrateApply) LogError(err error) {
	if l := len(a.Applied); l > 0 {
		f := a.Applied[l-1]
		stmt := ""
		if len(f.Applied) > 0 {
			stmt = f.Applied[len(f.Applied)-1]
		}
		f.End = time.Now()
		f.Error = &StmtError{Stmt: stmt, Text: err.Error()}
	}
	a.Error = err.Error()
}

// LogDone implements migrate.Logger.
func (a *MigrateApply) LogDone() {
	now := time.Now()
	a.End = now
	if l := len(a.Applied); l > 0 && a.Applied[l-1].End.IsZero() {
		a.Applied[l-1].End = now
	}
}

// ApplyTemplateFuncs are the functions available to the apply template.
var ApplyTemplateFuncs = template.FuncMap{
	"json":   jsonFunc,
	"dec":    func(i int) int { return i - 1 },
	"upper":  strings.ToUpper,
	"lower":  strings.ToLower,
	"split":  strings.Split,
	"join":   strings.Join,
	"cyan":   identity,
	"yellow": identity,
	"red":    identity,
	"green":  identity,
	"redBgWhiteFg": identity,
	"table":  identity,
}

func identity(s interface{}) string { return fmt.Sprint(s) }

// MigrateApplyTemplate is the default template of migrate apply.
var MigrateApplyTemplate = template.Must(template.New("report").Funcs(ApplyTemplateFuncs).Parse(
	`{{- if not .Pending -}}
