const checksumErrorText = `You have a checksum error in your migration directory.
This happens if you manually create or edit a migration file.
Please check your migration files and run

'atlas migrate hash'

to re-hash the contents and resolve the error

`

// dirPath extracts the local path of a migration directory URL.
func dirPath(dirURL string) (string, url.Values, error) {
	u, err := url.Parse(dirURL)
	if err != nil {
		return "", nil, err
	}
	switch u.Scheme {
	case "file":
	case "":
		return "", nil, fmt.Errorf("missing scheme for dir url. Did you mean %q? ", "file://"+dirURL)
	default:
		return "", nil, fmt.Errorf("unsupported driver %q", u.Scheme)
	}
	p := filepath.Join(u.Host, u.Path)
	if p == "" {
		p = "migrations"
	}
	return p, u.Query(), nil
}

// openDir opens (and optionally creates) the migration directory.
func openDir(dirURL string, create bool) (*migrate.Dir, error) {
	p, q, err := dirPath(dirURL)
	if err != nil {
		return nil, err
	}
	if f := q.Get("format"); f != "" && f != "atlas" {
		return nil, fmt.Errorf("unknown dir format %q", f)
	}
	if create {
		if err := os.MkdirAll(p, 0755); err != nil {
			return nil, fmt.Errorf("sql/migrate: %w", err)
		}
	}
	return migrate.NewDir(p)
}

// checkDir validates the directory checksum and prints a hint on mismatch.
func checkDir(cmd *cobra.Command, dir *migrate.Dir) error {
	if err := migrate.Validate(dir); err != nil {
		cmd.Print(checksumErrorText)
		return err
	}
	return nil
}

func checkDirFormat(f string) error {
	if f != "" && f != "atlas" {
		return fmt.Errorf("unknown dir format %q", f)
	}
	return nil
}

// dirURLWithFormat returns the directory URL with the format parameter as reported.
func dirURLWithFormat(dirURL, format string) string {
	if format == "" {
		format = "atlas"
	}
	u, err := url.Parse(dirURL)
	if err != nil {
		return dirURL
	}
	q := u.Query()
	q.Set("format", format)
	u.RawQuery = q.Encode()
	return u.String()
}

func migrateHashRun(cmd *cobra.Command, g *globalFlags, f *migrateHashFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	sum, err := dir.Checksum()
	if err != nil {
		return err
	}
	return migrate.WriteSumFile(dir, sum)
}

func migrateNewRun(cmd *cobra.Command, args []string, g *globalFlags, f *migrateNewFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, true)
	if err != nil {
		return err
	}
	if err := checkDir(cmd, dir); err != nil {
		return err
	}
	name := ""
	if len(args) > 0 {
		name = args[0]
	}
	return writeMigration(dir, name, nil)
}

// writeMigration writes a new migration file with the given statements and updates the sum file.
func writeMigration(dir *migrate.Dir, name string, changes []*sqlite.Change) error {
	var b bytes.Buffer
	for _, c := range changes {
		if c.Comment != "" {
			fmt.Fprintf(&b, "-- %s\n", capitalize(c.Comment))
		}
		fmt.Fprintf(&b, "%s;\n", c.Cmd)
	}
	fname := migrate.FileName(migrate.NewVersion(), name)
	if err := dir.WriteFile(fname, b.Bytes()); err != nil {
		return err
	}
	sum, err := dir.Checksum()
	if err != nil {
		return err
	}
	return migrate.WriteSumFile(dir, sum)
}

func capitalize(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func migrateValidateRun(cmd *cobra.Command, g *globalFlags, f *migrateValidateFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	if err := checkDir(cmd, dir); err != nil {
		return err
	}
	if f.devURL == "" {
		return nil
	}
	dev, err := openDriver(f.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	_, err = replayDir(dev, dir, "")
	return err
}

// revisionStore returns the revision store for the connection.
func revisionStore(drv *sqlite.Driver, schema string) *migrate.RevisionStore {
	return &migrate.RevisionStore{DB: drv.DB, Schema: schema, Table: migrate.DefaultRevisionSchema}
}

// checkClean returns a function that verifies the connected database is clean.
func checkClean(drv *sqlite.Driver, revT string) func() error {
	return func() error {
		s, err := drv.InspectSchema("", nil)
		if err != nil {
			return err
		}
		for _, t := range s.Tables {
			if t.Name != revT {
				return &migrate.NotCleanError{Reason: fmt.Sprintf("found table %q", t.Name)}
			}
		}
		return nil
	}
}

func migrateApplyRun(cmd *cobra.Command, args []string, g *globalFlags, f *migrateApplyFlags) error {
	n := 0
	if len(args) > 0 {
		var err error
		n, err = strconv.Atoi(args[0])
		if err != nil {
			return err
		}
		if n < 1 {
			return fmt.Errorf("cannot apply '%d' migration files", n)
		}
	}
	if err := checkDirFormat(""); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	report := &cmdlog.MigrateApply{Env: cmdlog.Env{Driver: "sqlite", URL: cmdlog.NewURL(f.url, drv.URL.Schema), Dir: dirURLWithFormat(f.dirURL, "atlas")}}
	tmpl := cmdlog.MigrateApplyTemplate
	if f.format != "" {
		tmpl, err = cmdlog.ParseFormat(f.format, cmdlog.ApplyTemplateFuncs)
		if err != nil {
			return err
		}
	}
	rrw := revisionStore(drv, f.revisionsSchema)
	ex, err := migrate.NewExecutor(&migrate.ExecOptions{
		DB:              drv.DB,
		Dir:             dir,
		Revisions:       rrw,
		Baseline:        f.baseline,
		AllowDirty:      f.allowDirty,
		TxMode:          f.txMode,
		ExecOrder:       f.execOrder,
		OperatorVersion: operatorVersion,
		DryRun:          f.dryRun,
		CheckClean:      checkClean(drv, migrate.DefaultRevisionSchema),
		Logger:          report,
	})
	if err != nil {
		return err
	}
	pending, err := ex.Pending()
	if err != nil && !migrate.IsNoPending(err) {
		if errors.Is(err, migrate.ErrChecksumMismatch) || errors.Is(err, migrate.ErrChecksumNotFound) || errors.Is(err, migrate.ErrChecksumFormat) {
			cmd.Print(checksumErrorText)
		}
		var nce *migrate.NotCleanError
		if errors.As(err, &nce) {
			return fmt.Errorf("%w. baseline version or allow-dirty is required", err)
		}
		return err
	}
	if n > 0 && n < len(pending) {
		pending = pending[:n]
	}
	if len(pending) == 0 {
		return tmpl.Execute(cmd.OutOrStdout(), report)
	}
	revs, _ := rrw.ReadRevisions()
	current := ""
	if len(revs) > 0 {
		current = revs[len(revs)-1].Version
	}
	report.LogExecution(current, pending[len(pending)-1].Version(), pending)
	execErr := ex.Execute(pending)
	report.LogDone()
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, report); err != nil {
		return err
	}
	cmd.Print(buf.String())
	return execErr
}

func migrateStatusRun(cmd *cobra.Command, g *globalFlags, f *migrateStatusFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	tmpl := cmdlog.MigrateStatusTemplate
	if f.format != "" {
		tmpl, err = cmdlog.ParseFormat(f.format, cmdlog.ApplyTemplateFuncs)
		if err != nil {
			return err
		}
	}
	report, err := statusReport(drv, dir, f.url, f.dirURL, f.revisionsSchema)
	if err != nil {
		if errors.Is(err, migrate.ErrChecksumMismatch) || errors.Is(err, migrate.ErrChecksumNotFound) || errors.Is(err, migrate.ErrChecksumFormat) {
			cmd.Print(checksumErrorText)
		}
		return err
	}
	return tmpl.Execute(cmd.OutOrStdout(), report)
}

func statusReport(drv *sqlite.Driver, dir *migrate.Dir, rawURL, dirURL, revSchema string) (*cmdlog.MigrateStatus, error) {
	rrw := revisionStore(drv, revSchema)
	ex, err := migrate.NewExecutor(&migrate.ExecOptions{DB: drv.DB, Dir: dir, Revisions: rrw, AllowDirty: true, DryRun: true})
	if err != nil {
		return nil, err
	}
	pending, err := ex.Pending()
	if err != nil && !migrate.IsNoPending(err) {
		return nil, err
	}
	files, err := dir.Files()
	if err != nil {
		return nil, err
	}
	revs, err := rrw.ReadRevisions()
	if err != nil {
		return nil, err
	}
	rep := &cmdlog.MigrateStatus{
		Env:       cmdlog.Env{Driver: "sqlite", URL: cmdlog.NewURL(rawURL, drv.URL.Schema), Dir: dirURLWithFormat(dirURL, "atlas")},
		Available: cmdlog.Files(files),
		Pending:   cmdlog.Files(pending),
		Applied:   revs,
	}
	switch len(revs) {
	case 0:
		rep.Current = "No migration applied yet"
	default:
		last := revs[len(revs)-1]
		rep.Current = last.Version
		if !last.Done() {
			rep.Count = last.Applied
			rep.Total = last.Total
			rep.Error = last.Error
			rep.SQL = last.ErrorStmt
		}
	}
	if len(pending) == 0 {
		rep.Status = "OK"
		rep.Next = "Already at latest version"
	} else {
		rep.Status = "PENDING"
		rep.Next = pending[0].Version()
	}
	return rep, nil
}

func migrateSetRun(cmd *cobra.Command, args []string, g *globalFlags, f *migrateSetFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	files, err := dir.Files()
	if err != nil {
		return err
	}
	var version string
	switch {
	case len(args) > 0:
		version = args[0]
	case len(files) > 0:
		version = files[len(files)-1].Version()
	default:
		return errors.New("no migration version to set")
	}
	idx := -1
	for i, mf := range files {
		if mf.Version() == version {
			idx = i
			break
		}
	}
	if idx == -1 {
		return fmt.Errorf("migration with version %q not found", version)
	}
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	rrw := revisionStore(drv, f.revisionsSchema)
	if err := rrw.Init(); err != nil {
		return err
	}
	revs, err := rrw.ReadRevisions()
	if err != nil {
		return err
	}
	applied := map[string]*migrate.Revision{}
	for _, r := range revs {
		applied[r.Version] = r
	}
	sum, _ := migrate.ReadSumFile(dir)
	hashOf := func(name string) string {
		for _, h := range sum {
			if h.N == name {
				return h.H
			}
		}
		return ""
	}
	var set, removed []*migrate.Revision
	for _, mf := range files[:idx+1] {
		if r, ok := applied[mf.Version()]; ok && r.Done() {
			continue
		}
		stmts, _ := mf.Stmts()
		r := &migrate.Revision{
			Version:         mf.Version(),
			Description:     mf.Desc(),
			Type:            migrate.RevisionTypeResolved | migrate.RevisionTypeExecute,
			Applied:         len(stmts),
			Total:           len(stmts),
			ExecutedAt:      nowUTC(),
			Hash:            hashOf(mf.Name),
			OperatorVersion: operatorVersion,
		}
		if err := rrw.WriteRevision(r); err != nil {
			return err
		}
		set = append(set, r)
	}
	for _, r := range revs {
		if r.Version > version {
			if err := rrw.DeleteRevision(r.Version); err != nil {
				return err
			}
			removed = append(removed, r)
		}
	}
	var b strings.Builder
	fmt.Fprintf(&b, "Current version is %s (", version)
	switch {
	case len(set) > 0 && len(removed) > 0:
		fmt.Fprintf(&b, "%d set, %d removed", len(set), len(removed))
	case len(set) > 0:
		fmt.Fprintf(&b, "%d set", len(set))
	default:
		fmt.Fprintf(&b, "%d removed", len(removed))
	}
	b.WriteString("):\n")
	if len(set) > 0 || len(removed) > 0 {
		b.WriteString("\n")
	}
	for _, r := range set {
		fmt.Fprintf(&b, "  + %s", r.Version)
		if r.Description != "" {
			fmt.Fprintf(&b, " (%s)", r.Description)
		}
		b.WriteString("\n")
	}
	for _, r := range removed {
		fmt.Fprintf(&b, "  - %s", r.Version)
		if r.Description != "" {
			fmt.Fprintf(&b, " (%s)", r.Description)
		}
		b.WriteString("\n")
	}
	if len(set) > 0 || len(removed) > 0 {
		b.WriteString("\n")
	}
	cmd.Print(b.String())
	return nil
}

func migrateImportRun(cmd *cobra.Command, g *globalFlags, f *migrateImportFlags) error {
	_, fq, err := dirPath(f.fromURL)
	if err != nil {
		return err
	}
	format := fq.Get("format")
	if format == "" || format == "atlas" {
		return errors.New("cannot import a migration directory already in \"atlas\" format")
	}
	return fmt.Errorf("unknown dir format %q", format)
}

// executeTemplate renders a template to a string.
func executeTemplate(t *template.Template, data interface{}) (string, error) {
	var b bytes.Buffer
	if err := t.Execute(&b, data); err != nil {
		return "", err
	}
	return b.String(), nil
}
