package cmdapi

import (
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"atlas/internal/migrate"
	"atlas/internal/schema"
	"atlas/internal/sqlite"
	"atlas/internal/sqlspec"
)

// stateKind describes the kind of a desired-state URL.
type stateKind int

const (
	stateDB stateKind = iota
	stateHCL
	stateSQL
	stateDir
)

// classifyURL determines the kind of state referenced by the URL.
func classifyURL(raw string) (stateKind, string, url.Values, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return 0, "", nil, err
	}
	switch u.Scheme {
	case "file":
		p := filepath.Join(u.Host, u.Path)
		st, err := os.Stat(p)
		if err != nil {
			return 0, "", nil, err
		}
		if st.IsDir() {
			entries, err := os.ReadDir(p)
			if err != nil {
				return 0, "", nil, err
			}
			var hcls, sqls int
			for _, e := range entries {
				if e.IsDir() {
					continue
				}
				switch {
				case strings.HasSuffix(e.Name(), ".hcl"):
					hcls++
				case strings.HasSuffix(e.Name(), ".sql"):
					sqls++
				case e.Name() == migrate.HashFileName:
					return stateDir, p, u.Query(), nil
				}
			}
			if sqls > 0 && hcls == 0 {
				return stateDir, p, u.Query(), nil
			}
			return stateHCL, p, u.Query(), nil
		}
		switch {
		case strings.HasSuffix(p, ".sql"):
			return stateSQL, p, u.Query(), nil
		default:
			return stateHCL, p, u.Query(), nil
		}
	case "sqlite", "sqlite3":
		return stateDB, raw, u.Query(), nil
	case "":
		return 0, "", nil, fmt.Errorf("missing scheme for url %q", raw)
	default:
		return 0, "", nil, fmt.Errorf("sql/sqlclient: no opener was register with name %q", u.Scheme)
	}
}

// stateOptions control how a desired state is loaded.
type stateOptions struct {
	devURL  string
	schemas []string
	exclude []string
	vars    map[string][]string
	envName string
}

// readState loads the realm described by the given URLs.
func readState(urls []string, opts *stateOptions) (*schema.Realm, stateKind, error) {
	if len(urls) == 0 {
		return nil, 0, errors.New("missing desired state URL")
	}
	kind, _, _, err := classifyURL(urls[0])
	if err != nil {
		return nil, 0, err
	}
	var paths []string
	for _, u := range urls {
		k, p, _, err := classifyURL(u)
		if err != nil {
			return nil, 0, err
		}
		if k != kind {
			return nil, 0, errors.New("got mixed --to url schemes")
		}
		paths = append(paths, p)
	}
	switch kind {
	case stateDB:
		if len(urls) > 1 {
			return nil, 0, errors.New("multiple database URLs are not supported")
		}
		drv, err := openDriver(urls[0])
		if err != nil {
			return nil, 0, err
		}
		defer drv.Close()
		r, err := inspectRealm(drv, opts.schemas, opts.exclude)
		return r, kind, err
	case stateHCL:
		files, err := sqlspec.ParseFiles(paths)
		if err != nil {
			return nil, 0, err
		}
		r, err := sqlspec.UnmarshalRealm(files, &sqlspec.UnmarshalOptions{Vars: opts.vars, EnvName: opts.envName})
		if err != nil {
			return nil, 0, err
		}
		if len(opts.exclude) > 0 {
			excludeRealm(r, opts.exclude)
		}
		return r, kind, nil
	case stateSQL, stateDir:
		if opts.devURL == "" {
			return nil, 0, errors.New("--dev-url cannot be empty")
		}
		dev, err := openDriver(opts.devURL)
		if err != nil {
			return nil, 0, err
		}
		defer dev.Close()
		var r *schema.Realm
		if kind == stateSQL {
			var stmts []string
			for _, p := range paths {
				b, err := os.ReadFile(p)
				if err != nil {
					return nil, 0, err
				}
				ss, err := migrate.ScanStmts(string(b))
				if err != nil {
					return nil, 0, err
				}
				for _, s := range ss {
					stmts = append(stmts, s.Text)
				}
			}
			r, err = replayStmts(dev, stmts, opts.exclude)
		} else {
			_, _, q, _ := classifyURL(urls[0])
			dir, err := migrate.NewDir(paths[0])
			if err != nil {
				return nil, 0, err
			}
			r, err = replayDir(dev, dir, q.Get("version"))
			if err != nil {
				return nil, 0, err
			}
			if len(opts.exclude) > 0 {
				excludeRealm(r, opts.exclude)
			}
		}
		return r, kind, err
	}
	return nil, 0, fmt.Errorf("unsupported state url %q", urls[0])
}

// excludeRealm removes the resources matching the exclude patterns.
func excludeRealm(r *schema.Realm, patterns []string) {
	for _, s := range r.Schemas {
		var tables []*schema.Table
		for _, t := range s.Tables {
			if sqlite.Excluded(patterns, s.Name, t.Name) {
				continue
			}
			tables = append(tables, t)
		}
		s.Tables = tables
	}
}

// replayStmts executes the statements on the dev database and inspects the result.
func replayStmts(dev *sqlite.Driver, stmts []string, exclude []string) (*schema.Realm, error) {
	if err := ensureClean(dev); err != nil {
		return nil, err
	}
	for _, s := range stmts {
		if err := dev.Exec(s); err != nil {
			cleanDev(dev)
			return nil, fmt.Errorf("sql/migrate: execute: executing statement %q: %w", s, err)
		}
	}
	r, err := inspectRealm(dev, nil, exclude)
	cleanDev(dev)
	return r, err
}

// replayDir executes the migration files on the dev database (up to the given
// version, if any) and inspects the result.
func replayDir(dev *sqlite.Driver, dir *migrate.Dir, version string) (*schema.Realm, error) {
	if err := migrate.Validate(dir); err != nil {
		return nil, fmt.Errorf("sql/migrate: validate migration directory: %w", err)
	}
	files, err := dir.Files()
	if err != nil {
		return nil, err
	}
	if err := ensureClean(dev); err != nil {
		return nil, err
	}
	for _, f := range files {
		if version != "" && f.Version() > version {
			break
		}
		stmts, err := f.Stmts()
		if err != nil {
			cleanDev(dev)
			return nil, fmt.Errorf("sql/migrate: scanning statements from %q: %w", f.Name, err)
		}
		for _, s := range stmts {
			if err := dev.Exec(s.Text); err != nil {
				cleanDev(dev)
				return nil, fmt.Errorf("sql/migrate: executing statement %q from version %q: %w", s.Text, f.Version(), err)
			}
		}
	}
	r, err := inspectRealm(dev, nil, nil)
	cleanDev(dev)
	return r, err
}

// ensureClean verifies the dev database has no tables.
func ensureClean(dev *sqlite.Driver) error {
	s, err := dev.InspectSchema("", nil)
	if err != nil {
		return err
	}
	for _, t := range s.Tables {
		return &migrate.NotCleanError{Reason: fmt.Sprintf("found table %q", t.Name)}
	}
	return nil
}

// cleanDev drops all tables of the dev database.
func cleanDev(dev *sqlite.Driver) {
	s, err := dev.InspectSchema("", nil)
	if err != nil {
		return
	}
	_ = dev.Exec("PRAGMA foreign_keys = off")
	for _, t := range s.Tables {
		_ = dev.Exec("DROP TABLE " + sqlite.Quote(t.Name))
	}
	// Views and triggers.
	rows, err := dev.DB.Query("SELECT type, name FROM sqlite_master WHERE type IN ('view', 'trigger')")
	if err == nil {
		for _, row := range rows.Rows {
			_ = dev.Exec(fmt.Sprintf("DROP %s %s", strings.ToUpper(fmt.Sprint(row[0])), sqlite.Quote(fmt.Sprint(row[1]))))
		}
	}
	_ = dev.Exec("PRAGMA foreign_keys = on")
}

// sortedTables returns the table names of a schema sorted.
func sortedTables(s *schema.Schema) []string {
	names := make([]string, 0, len(s.Tables))
	for _, t := range s.Tables {
		names = append(names, t.Name)
	}
	sort.Strings(names)
	return names
}
