package cmdapi

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"atlas/internal/cmdlog"
	"atlas/internal/schema"
	"atlas/internal/sqlite"

	"github.com/spf13/cobra"
)

// planChanges plans the changes with the default formatting used by the commands.
func planChanges(changes []schema.Change, indent string) (*sqlite.Plan, error) {
	return sqlite.PlanChanges(changes, &sqlite.PlanOptions{Indent: indent})
}

// printPlan prints the planned statements.
func printPlan(w io.Writer, plan *sqlite.Plan) {
	for _, c := range plan.Changes {
		if c.Comment != "" {
			fmt.Fprintf(w, "-- %s\n", capitalize(c.Comment))
		}
		fmt.Fprintf(w, "%s;\n", c.Cmd)
	}
}

// applyPlan executes the plan on the database.
func applyPlan(drv *sqlite.Driver, plan *sqlite.Plan, txMode string) error {
	tx := plan.Transactional && txMode != "none"
	if tx {
		if err := drv.Exec("BEGIN"); err != nil {
			return err
		}
	}
	for _, c := range plan.Changes {
		if err := drv.Exec(c.Cmd); err != nil {
			if tx {
				_ = drv.Exec("ROLLBACK")
			}
			return fmt.Errorf("%s: %w", c.Cmd, err)
		}
	}
	if tx {
		return drv.Exec("COMMIT")
	}
	return nil
}

// errAbort is returned when the user aborts the operation.
var errAbort = errors.New("Abort")

// promptApply asks the user for confirmation.
func promptApply(cmd *cobra.Command) (bool, error) {
	out := cmd.OutOrStdout()
	fmt.Fprint(out, "? Are you sure?: \n  ▸ Apply\n    Abort\n")
	in := cmd.InOrStdin()
	r := bufio.NewReader(in)
	line, err := r.ReadString('\n')
	if err != nil && line == "" {
		return false, errors.New("^D")
	}
	ans := strings.TrimSpace(strings.ToLower(line))
	switch ans {
	case "", "apply", "y", "yes":
		fmt.Fprintln(out, "✔ Apply")
		return true, nil
	}
	fmt.Fprintln(out, "✔ Abort")
	return false, nil
}

// diffRealms computes the changes between two realms, considering schema-bound connections.
func diffRealms(from, to *schema.Realm, bound bool) ([]schema.Change, error) {
	if bound && len(from.Schemas) == 1 && len(to.Schemas) == 1 {
		// Compare the single schemas regardless of their names.
		if from.Schemas[0].Name != to.Schemas[0].Name {
			to.Schemas[0].Name = from.Schemas[0].Name
		}
		return sqlite.SchemaDiff(from.Schemas[0], to.Schemas[0], nil)
	}
	return sqlite.RealmDiff(from, to, nil)
}

func schemaApplyRun(cmd *cobra.Command, g *globalFlags, f *schemaApplyFlags) error {
	communityEditionNotice()
	if len(f.toURLs) == 0 {
		return errors.New(`required flag(s) "to" not set`)
	}
	switch f.txMode {
	case "none", "file":
	default:
		return fmt.Errorf("unknown tx-mode %q", f.txMode)
	}
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	schemas := f.schemas
	bound := drv.URL.Schema != "" && len(schemas) == 0
	if bound {
		schemas = []string{drv.URL.Schema}
	}
	from, err := drv.InspectRealm(&sqlite.InspectOptions{Schemas: schemas, Exclude: f.exclude})
	if err != nil {
		return err
	}
	to, kind, err := readState(f.toURLs, &stateOptions{devURL: f.devURL, schemas: schemas, exclude: f.exclude, vars: g.Vars, envName: g.Env})
	if err != nil {
		return err
	}
	if kind == stateHCL && bound {
		switch {
		case len(to.Schemas) != 1:
			return fmt.Errorf("the connection is bound to schema %q but the HCL schema defines %d schemas", drv.URL.Schema, len(to.Schemas))
		case to.Schemas[0].Name != drv.URL.Schema:
			return fmt.Errorf("mismatched HCL and database schemas: %q <> %q", drv.URL.Schema, to.Schemas[0].Name)
		}
	}
	changes, err := diffRealms(from, to, bound)
	if err != nil {
		return err
	}
	if len(changes) == 0 {
		cmd.Println("Schema is synced, no changes to be made")
		return nil
	}
	plan, err := planChanges(changes, "  ")
	if err != nil {
		return err
	}
	out := cmd.OutOrStdout()
	if f.format != "" {
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.ApplyTemplateFuncs)
		if err != nil {
			return err
		}
		report := &cmdlog.SchemaApply{Env: cmdlog.Env{Driver: "sqlite", URL: cmdlog.NewURL(f.url, drv.URL.Schema)}}
		for _, c := range plan.Changes {
			report.Changes.Pending = append(report.Changes.Pending, c.Cmd)
		}
		if f.dryRun {
			return tmpl.Execute(out, report)
		}
		if !f.autoApprove {
			ok, err := promptApply(cmd)
			if err != nil {
				return err
			}
			if !ok {
				return nil
			}
		}
		if err := applyPlan(drv, plan, f.txMode); err != nil {
			report.Error = err.Error()
			_ = tmpl.Execute(out, report)
			return err
		}
		report.Changes.Applied, report.Changes.Pending = report.Changes.Pending, nil
		return tmpl.Execute(out, report)
	}
	fmt.Fprintln(out, "-- Planned Changes:")
	printPlan(out, plan)
	if f.dryRun {
		return nil
	}
	if !f.autoApprove {
		ok, err := promptApply(cmd)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyPlan(drv, plan, f.txMode)
}

func schemaDiffRun(cmd *cobra.Command, g *globalFlags, f *schemaDiffFlags) error {
	communityEditionNotice()
	needDev := false
	for _, u := range append(append([]string{}, f.fromURLs...), f.toURLs...) {
		if strings.HasPrefix(u, "file://") {
			needDev = true
		}
	}
	if needDev && f.devURL == "" {
		return errors.New("--dev-url cannot be empty")
	}
	opts := &stateOptions{devURL: f.devURL, schemas: f.schemas, exclude: f.exclude, vars: g.Vars, envName: g.Env}
	from, _, err := readState(f.fromURLs, opts)
	if err != nil {
		return err
	}
	to, _, err := readState(f.toURLs, opts)
	if err != nil {
		return err
	}
	bound := len(from.Schemas) == 1 && len(to.Schemas) == 1
	changes, err := diffRealms(from, to, bound)
	if err != nil {
		return err
	}
	out := cmd.OutOrStdout()
	if f.format != "" {
		plan, err := planChanges(changes, "")
		if err != nil {
			return err
		}
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.SchemaDiffFuncs)
		if err != nil {
			return err
		}
		return tmpl.Execute(out, &cmdlog.SchemaDiff{Changes: plan.Changes})
	}
	if len(changes) == 0 {
		fmt.Fprintln(out, "Schemas are synced, no changes to be made.")
		return nil
	}
	plan, err := planChanges(changes, "")
	if err != nil {
		return err
	}
	printPlan(out, plan)
	return nil
}

func schemaCleanRun(cmd *cobra.Command, g *globalFlags, f *schemaCleanFlags) error {
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	var changes []schema.Change
	if drv.URL.Schema != "" {
		s, err := drv.InspectSchema(drv.URL.Schema, nil)
		if err != nil {
			return err
		}
		for _, t := range s.Tables {
			changes = append(changes, &schema.DropTable{T: t})
		}
	} else {
		r, err := drv.InspectRealm(nil)
		if err != nil {
			return err
		}
		for _, s := range r.Schemas {
			for _, t := range s.Tables {
				changes = append(changes, &schema.DropTable{T: t})
			}
		}
	}
	out := cmd.OutOrStdout()
	if len(changes) == 0 {
		fmt.Fprintln(out, "Nothing to drop")
		return nil
	}
	plan, err := planChanges(changes, "")
	if err != nil {
		return err
	}
	fmt.Fprintln(out, "-- Planned Changes:")
	printPlan(out, plan)
	if f.dryRun {
		return nil
	}
	if !f.autoApprove {
		ok, err := promptApply(cmd)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyPlan(drv, plan, "file")
}

func migrateDiffRun(cmd *cobra.Command, args []string, g *globalFlags, f *migrateDiffFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, true)
	if err != nil {
		return err
	}
	if err := checkDir(cmd, dir); err != nil {
		return err
	}
	dev, err := openDriver(f.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	current, err := replayDir(dev, dir, "")
	if err != nil {
		return err
	}
	desired, kind, err := readState(f.toURLs, &stateOptions{devURL: f.devURL, schemas: f.schemas, vars: g.Vars, envName: g.Env})
	if err != nil {
		return err
	}
	if kind == stateHCL && dev.URL.Schema != "" && len(desired.Schemas) == 1 && desired.Schemas[0].Name != dev.URL.Schema {
		return fmt.Errorf("mismatched HCL and database schemas: %q <> %q", dev.URL.Schema, desired.Schemas[0].Name)
	}
	changes, err := diffRealms(current, desired, true)
	if err != nil {
		return err
	}
	if len(changes) == 0 {
		cmd.Println("The migration directory is synced with the desired state, no changes to be made")
		return nil
	}
	plan, err := planChanges(changes, "")
	if err != nil {
		return err
	}
	if f.format != "" {
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.SchemaDiffFuncs)
		if err != nil {
			return err
		}
		if err := tmpl.Execute(cmd.OutOrStdout(), &cmdlog.SchemaDiff{Changes: plan.Changes}); err != nil {
			return err
		}
	}
	name := ""
	if len(args) > 0 {
		name = args[0]
	}
	return writeMigration(dir, name, plan.Changes)
}

func migrateLintRun(cmd *cobra.Command, g *globalFlags, f *migrateLintFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	if err := checkDir(cmd, dir); err != nil {
		return err
	}
	files, err := dir.Files()
	if err != nil {
		return err
	}
	if f.latest == 0 && f.gitBase == "" {
		return errors.New("--latest or --git-base must be set")
	}
	n := int(f.latest)
	if n > len(files) {
		n = len(files)
	}
	base, changed := files[:len(files)-n], files[len(files)-n:]
	if len(changed) == 0 {
		return nil
	}
	dev, err := openDriver(f.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	if err := ensureClean(dev); err != nil {
		return err
	}
	defer cleanDev(dev)
	exec := func(fs []*cmdlog.LintFile) error { return nil }
	_ = exec
	out := cmd.OutOrStdout()
	if len(base) > 0 {
		fmt.Fprintf(out, "Analyzing changes from version %s to %s (%d migration%s in total):\n", base[len(base)-1].Version(), changed[len(changed)-1].Version(), len(changed), plural(len(changed)))
	} else {
		fmt.Fprintf(out, "Analyzing changes until version %s (%d migration%s in total):\n", changed[len(changed)-1].Version(), len(changed), plural(len(changed)))
	}
	for _, bf := range base {
		stmts, err := bf.Stmts()
		if err != nil {
			return err
		}
		for _, s := range stmts {
			if err := dev.Exec(s.Text); err != nil {
				return fmt.Errorf("sql/migrate: executing statement %q from version %q: %w", s.Text, bf.Version(), err)
			}
		}
	}
	var report cmdlog.LintReport
	for _, cf := range changed {
		stmts, err := cf.Stmts()
		if err != nil {
			return err
		}
		lf := &cmdlog.LintFile{Name: cf.Name, Version: cf.Version()}
		before, _ := dev.InspectSchema("", nil)
		for _, s := range stmts {
			if err := dev.Exec(s.Text); err != nil {
				lf.Error = fmt.Sprintf("executing statement: %v", err)
				break
			}
		}
		after, _ := dev.InspectSchema("", nil)
		if before != nil && after != nil {
			changes, _ := sqlite.SchemaDiff(before, after, nil)
			lf.Changes = len(changes)
			for _, c := range changes {
				switch c := c.(type) {
				case *schema.DropTable:
					lf.Reports = append(lf.Reports, cmdlog.LintDiagnostic{Text: fmt.Sprintf("Dropping table %q", c.T.Name), Code: "DS102"})
				case *schema.ModifyTable:
					for _, mc := range c.Changes {
						if dc, ok := mc.(*schema.DropColumn); ok {
							lf.Reports = append(lf.Reports, cmdlog.LintDiagnostic{Text: fmt.Sprintf("Dropping non-virtual column %q", dc.C.Name), Code: "DS103"})
						}
					}
				}
			}
		}
		report.Files = append(report.Files, lf)
	}
	if f.format != "" {
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.ApplyTemplateFuncs)
		if err != nil {
			return err
		}
		return tmpl.Execute(out, &report)
	}
	hasErr := false
	for _, lf := range report.Files {
		fmt.Fprintf(out, "\n  -- analyzing version %s\n", lf.Version)
		switch {
		case lf.Error != "":
			fmt.Fprintf(out, "    -- %s\n", lf.Error)
			hasErr = true
		case len(lf.Reports) == 0:
