)

// planChanges plans the changes with the default formatting used by the commands.
func planChanges(changes []schema.Change, indent string) (*sqlite.Plan, error) {
	return sqlite.PlanChanges(changes, &sqlite.PlanOptions{Indent: indent})
}

// printPlan prints the planned statements.
func printPlan(w io.Writer, plan *sqlite.Plan) {
	for _, c := range plan.Changes {
		if c.Comment != "" {
			fmt.Fprintf(w, "-- %s\n", capitalize(c.Comment))
		}
		fmt.Fprintf(w, "%s;\n", c.Cmd)
	}
}

// applyPlan executes the plan on the database.
func applyPlan(drv *sqlite.Driver, plan *sqlite.Plan, txMode string) error {
	tx := plan.Transactional && txMode != "none"
	if tx {
		if err := drv.Exec("BEGIN"); err != nil {
			return err
		}
	}
	for _, c := range plan.Changes {
		if err := drv.Exec(c.Cmd); err != nil {
			if tx {
				_ = drv.Exec("ROLLBACK")
			}
			return fmt.Errorf("%s: %w", c.Cmd, err)
		}
	}
	if tx {
		return drv.Exec("COMMIT")
	}
	return nil
}

// errAbort is returned when the user aborts the operation.
var errAbort = errors.New("Abort")

// promptApply asks the user for confirmation.
func promptApply(cmd *cobra.Command) (bool, error) {
	out := cmd.OutOrStdout()
	fmt.Fprint(out, "? Are you sure?: \n  ▸ Apply\n    Abort\n")
	in := cmd.InOrStdin()
	r := bufio.NewReader(in)
	line, err := r.ReadString('\n')
	if err != nil && line == "" {
		return false, errors.New("^D")
	}
	ans := strings.TrimSpace(strings.ToLower(line))
	switch ans {
	case "", "apply", "y", "yes":
		fmt.Fprintln(out, "✔ Apply")
		return true, nil
	}
	fmt.Fprintln(out, "✔ Abort")
	return false, nil
}

// diffRealms computes the changes between two realms, considering schema-bound connections.
func diffRealms(from, to *schema.Realm, bound bool) ([]schema.Change, error) {
	if bound && len(from.Schemas) == 1 && len(to.Schemas) == 1 {
		// Compare the single schemas regardless of their names.
		if from.Schemas[0].Name != to.Schemas[0].Name {
			to.Schemas[0].Name = from.Schemas[0].Name
		}
		return sqlite.SchemaDiff(from.Schemas[0], to.Schemas[0], nil)
	}
	return sqlite.RealmDiff(from, to, nil)
}

func schemaApplyRun(cmd *cobra.Command, g *globalFlags, f *schemaApplyFlags) error {
	communityEditionNotice()
	if len(f.toURLs) == 0 {
		return errors.New(`required flag(s) "to" not set`)
	}
	switch f.txMode {
	case "none", "file":
	default:
		return fmt.Errorf("unknown tx-mode %q", f.txMode)
	}
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	schemas := f.schemas
	bound := drv.URL.Schema != "" && len(schemas) == 0
	if bound {
		schemas = []string{drv.URL.Schema}
	}
	from, err := drv.InspectRealm(&sqlite.InspectOptions{Schemas: schemas, Exclude: f.exclude})
	if err != nil {
		return err
	}
	to, kind, err := readState(f.toURLs, &stateOptions{devURL: f.devURL, schemas: schemas, exclude: f.exclude, vars: g.Vars, envName: g.Env})
	if err != nil {
		return err
	}
	if kind == stateHCL && bound {
		switch {
		case len(to.Schemas) != 1:
			return fmt.Errorf("the connection is bound to schema %q but the HCL schema defines %d schemas", drv.URL.Schema, len(to.Schemas))
		case to.Schemas[0].Name != drv.URL.Schema:
			return fmt.Errorf("mismatched HCL and database schemas: %q <> %q", drv.URL.Schema, to.Schemas[0].Name)
		}
	}
	changes, err := diffRealms(from, to, bound)
	if err != nil {
		return err
	}
	if len(changes) == 0 {
		cmd.Println("Schema is synced, no changes to be made")
		return nil
	}
	plan, err := planChanges(changes, "  ")
	if err != nil {
		return err
	}
	out := cmd.OutOrStdout()
	if f.format != "" {
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.ApplyTemplateFuncs)
		if err != nil {
			return err
		}
		report := &cmdlog.SchemaApply{Env: cmdlog.Env{Driver: "sqlite", URL: cmdlog.NewURL(f.url, drv.URL.Schema)}}
		for _, c := range plan.Changes {
			report.Changes.Pending = append(report.Changes.Pending, c.Cmd)
		}
		if f.dryRun {
			return tmpl.Execute(out, report)
		}
		if !f.autoApprove {
			ok, err := promptApply(cmd)
			if err != nil {
				return err
			}
			if !ok {
				return nil
			}
		}
		if err := applyPlan(drv, plan, f.txMode); err != nil {
			report.Error = err.Error()
			_ = tmpl.Execute(out, report)
			return err
		}
		report.Changes.Applied, report.Changes.Pending = report.Changes.Pending, nil
		return tmpl.Execute(out, report)
	}
	fmt.Fprintln(out, "-- Planned Changes:")
	printPlan(out, plan)
	if f.dryRun {
		return nil
	}
	if !f.autoApprove {
		ok, err := promptApply(cmd)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyPlan(drv, plan, f.txMode)
}

func schemaDiffRun(cmd *cobra.Command, g *globalFlags, f *schemaDiffFlags) error {
	communityEditionNotice()
	needDev := false
	for _, u := range append(append([]string{}, f.fromURLs...), f.toURLs...) {
		if strings.HasPrefix(u, "file://") {
			needDev = true
		}
	}
	if needDev && f.devURL == "" {
		return errors.New("--dev-url cannot be empty")
	}
	opts := &stateOptions{devURL: f.devURL, schemas: f.schemas, exclude: f.exclude, vars: g.Vars, envName: g.Env}
	from, _, err := readState(f.fromURLs, opts)
	if err != nil {
		return err
	}
	to, _, err := readState(f.toURLs, opts)
	if err != nil {
		return err
	}
	bound := len(from.Schemas) == 1 && len(to.Schemas) == 1
	changes, err := diffRealms(from, to, bound)
	if err != nil {
		return err
	}
	out := cmd.OutOrStdout()
	if f.format != "" {
		plan, err := planChanges(changes, "")
		if err != nil {
			return err
		}
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.SchemaDiffFuncs)
		if err != nil {
			return err
		}
		return tmpl.Execute(out, &cmdlog.SchemaDiff{Changes: plan.Changes})
	}
	if len(changes) == 0 {
		fmt.Fprintln(out, "Schemas are synced, no changes to be made.")
		return nil
	}
	plan, err := planChanges(changes, "")
	if err != nil {
		return err
	}
	printPlan(out, plan)
	return nil
}

func schemaCleanRun(cmd *cobra.Command, g *globalFlags, f *schemaCleanFlags) error {
	drv, err := openDriver(f.url)
	if err != nil {
		return err
	}
	defer drv.Close()
	var changes []schema.Change
	if drv.URL.Schema != "" {
		s, err := drv.InspectSchema(drv.URL.Schema, nil)
		if err != nil {
			return err
		}
		for _, t := range s.Tables {
			changes = append(changes, &schema.DropTable{T: t})
		}
	} else {
		r, err := drv.InspectRealm(nil)
		if err != nil {
			return err
		}
		for _, s := range r.Schemas {
			for _, t := range s.Tables {
				changes = append(changes, &schema.DropTable{T: t})
			}
		}
	}
	out := cmd.OutOrStdout()
	if len(changes) == 0 {
		fmt.Fprintln(out, "Nothing to drop")
		return nil
	}
	plan, err := planChanges(changes, "")
	if err != nil {
		return err
	}
	fmt.Fprintln(out, "-- Planned Changes:")
	printPlan(out, plan)
	if f.dryRun {
		return nil
	}
	if !f.autoApprove {
		ok, err := promptApply(cmd)
		if err != nil {
			return err
		}
		if !ok {
			return nil
		}
	}
	return applyPlan(drv, plan, "file")
}

func migrateDiffRun(cmd *cobra.Command, args []string, g *globalFlags, f *migrateDiffFlags) error {
