		return err
	}
	dev, err := openDriver(f.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	current, err := replayDir(dev, dir, "")
	if err != nil {
		return err
	}
	desired, kind, err := readState(f.toURLs, &stateOptions{devURL: f.devURL, schemas: f.schemas, vars: g.Vars, envName: g.Env})
	if err != nil {
		return err
	}
	if kind == stateHCL && dev.URL.Schema != "" && len(desired.Schemas) == 1 && desired.Schemas[0].Name != dev.URL.Schema {
		return fmt.Errorf("mismatched HCL and database schemas: %q <> %q", dev.URL.Schema, desired.Schemas[0].Name)
	}
	changes, err := diffRealms(current, desired, true)
	if err != nil {
		return err
	}
	if len(changes) == 0 {
		cmd.Println("The migration directory is synced with the desired state, no changes to be made")
		return nil
	}
	plan, err := planChanges(changes, "")
	if err != nil {
		return err
	}
	if f.format != "" {
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.SchemaDiffFuncs)
		if err != nil {
			return err
		}
