			return err
		}
	}
	name := ""
	if len(args) > 0 {
		name = args[0]
	}
	return writeMigration(dir, name, plan.Changes)
}

func migrateLintRun(cmd *cobra.Command, g *globalFlags, f *migrateLintFlags) error {
	if err := checkDirFormat(f.dirFormat); err != nil {
		return err
	}
	dir, err := openDir(f.dirURL, false)
	if err != nil {
		return err
	}
	if err := checkDir(cmd, dir); err != nil {
		return err
	}
	files, err := dir.Files()
	if err != nil {
		return err
	}
	if f.latest == 0 && f.gitBase == "" {
		return errors.New("--latest or --git-base must be set")
	}
	n := int(f.latest)
	if n > len(files) {
		n = len(files)
	}
	base, changed := files[:len(files)-n], files[len(files)-n:]
	if len(changed) == 0 {
		return nil
	}
	dev, err := openDriver(f.devURL)
	if err != nil {
		return err
	}
	defer dev.Close()
	if err := ensureClean(dev); err != nil {
		return err
	}
	defer cleanDev(dev)
	exec := func(fs []*cmdlog.LintFile) error { return nil }
	_ = exec
	out := cmd.OutOrStdout()
	if len(base) > 0 {
		fmt.Fprintf(out, "Analyzing changes from version %s to %s (%d migration%s in total):\n", base[len(base)-1].Version(), changed[len(changed)-1].Version(), len(changed), plural(len(changed)))
	} else {
		fmt.Fprintf(out, "Analyzing changes until version %s (%d migration%s in total):\n", changed[len(changed)-1].Version(), len(changed), plural(len(changed)))
	}
	for _, bf := range base {
		stmts, err := bf.Stmts()
		if err != nil {
			return err
		}
		for _, s := range stmts {
			if err := dev.Exec(s.Text); err != nil {
				return fmt.Errorf("sql/migrate: executing statement %q from version %q: %w", s.Text, bf.Version(), err)
			}
		}
	}
	var report cmdlog.LintReport
	for _, cf := range changed {
		stmts, err := cf.Stmts()
		if err != nil {
			return err
		}
		lf := &cmdlog.LintFile{Name: cf.Name, Version: cf.Version()}
		before, _ := dev.InspectSchema("", nil)
		for _, s := range stmts {
			if err := dev.Exec(s.Text); err != nil {
				lf.Error = fmt.Sprintf("executing statement: %v", err)
				break
			}
		}
		after, _ := dev.InspectSchema("", nil)
		if before != nil && after != nil {
			changes, _ := sqlite.SchemaDiff(before, after, nil)
			lf.Changes = len(changes)
			for _, c := range changes {
				switch c := c.(type) {
				case *schema.DropTable:
					lf.Reports = append(lf.Reports, cmdlog.LintDiagnostic{Text: fmt.Sprintf("Dropping table %q", c.T.Name), Code: "DS102"})
				case *schema.ModifyTable:
					for _, mc := range c.Changes {
						if dc, ok := mc.(*schema.DropColumn); ok {
							lf.Reports = append(lf.Reports, cmdlog.LintDiagnostic{Text: fmt.Sprintf("Dropping non-virtual column %q", dc.C.Name), Code: "DS103"})
						}
					}
				}
			}
		}
		report.Files = append(report.Files, lf)
	}
	if f.format != "" {
		tmpl, err := cmdlog.ParseFormat(f.format, cmdlog.ApplyTemplateFuncs)
		if err != nil {
			return err
		}
		return tmpl.Execute(out, &report)
	}
	hasErr := false
	for _, lf := range report.Files {
		fmt.Fprintf(out, "\n  -- analyzing version %s\n", lf.Version)
		switch {
		case lf.Error != "":
			fmt.Fprintf(out, "    -- %s\n", lf.Error)
			hasErr = true
		case len(lf.Reports) == 0:
			fmt.Fprintln(out, "    -- no diagnostics found")
		default:
			fmt.Fprintln(out, "    -- destructive changes detected:")
			for _, r := range lf.Reports {
				fmt.Fprintf(out, "      -- L1: %s https://atlasgo.io/lint/analyzers#%s\n", r.Text, r.Code)
			}
		}
		fmt.Fprintln(out, "  -- ok")
	}
	fmt.Fprintln(out, "\n  -------------------------")
	fmt.Fprintf(out, "  -- %d version%s ok\n", len(report.Files), plural(len(report.Files)))
	if hasErr {
		return errors.New("lint failed")
	}
	return nil
}

