{"command":"cat > /workspace/internal/sqlite/sortchanges.go <<'EOF'
package sqlite

import (
	"errors"
	"sort"

	"atlas/internal/schema"
)

var errCycle = errors.New("cycle detected")

// detachCycles reorders the top-level changes such that tables referenced by
// foreign keys are created before (and dropped after) the referencing tables.
// In case of a circular reference the changes are returned as is.
func detachCycles(changes []schema.Change) []schema.Change {
	sorted, err := sortMap(changes)
	if err != nil {
		return changes
	}
	planned := make([]schema.Change, len(changes))
	copy(planned, changes)
	sort.SliceStable(planned, func(i, j int) bool {
		ti, oki := changeTable(planned[i])
		tj, okj := changeTable(planned[j])
		if !oki || !okj {
			return false
		}
		return sorted[ti] < sorted[tj]
	})
	return planned
}

func changeTable(c schema.Change) (string, bool) {
	switch c := c.(type) {
	case *schema.AddTable:
		return c.T.Name, true
	case *schema.DropTable:
		return c.T.Name, true
	case *schema.ModifyTable:
		return c.T.Name, true
	case *schema.RenameTable:
		return c.To.Name, true
	}
	return "", false
}

// sortMap returns the position of each table in a topological order based on
// its references.
func sortMap(changes []schema.Change) (map[string]int, error) {
	deps := map[string][]string{}
	var order []string
	add := func(name string) {
		if _, ok := deps[name]; !ok {
			deps[name] = nil
			order = append(order, name)
		}
	}
	for _, c := range changes {
		switch c := c.(type) {
		case *schema.AddTable:
			add(c.T.Name)
			for _, fk := range c.T.ForeignKeys {
				if fk.RefTable == nil || fk.RefTable.Name == c.T.Name {
					continue
				}
				deps[c.T.Name] = append(deps[c.T.Name], fk.RefTable.Name)
			}
		case *schema.DropTable:
			add(c.T.Name)
			for _, fk := range c.T.ForeignKeys {
				if fk.RefTable == nil || fk.RefTable.Name == c.T.Name {
					continue
				}
				// The referenced table must be dropped after the referencing one.
				add(fk.RefTable.Name)
				deps[fk.RefTable.Name] = append(deps[fk.RefTable.Name], c.T.Name)
			}
		case *schema.ModifyTable:
			add(c.T.Name)
			for _, mc := range c.Changes {
				if afk, ok := mc.(*schema.AddForeignKey); ok && afk.F.RefTable != nil && afk.F.RefTable.Name != c.T.Name {
					deps[c.T.Name] = append(deps[c.T.Name], afk.F.RefTable.Name)
				}
			}
		case *schema.RenameTable:
			add(c.To.Name)
		}
	}
	sorted := map[string]int{}
	progress := map[string]bool{}
	var visit func(string) bool
	visit = func(name string) bool {
		if _, done := sorted[name]; done {
			return false
		}
		if progress[name] {
			return true
		}
		progress[name] = true
		for _, ref := range deps[name] {
			if _, known := deps[ref]; !known {
				continue
			}
			if visit(ref) {
				return true
			}
		}
		delete(progress, name)
		sorted[name] = len(sorted)
		return false
	}
	for _, node := range order {
		if visit(node) {
			return nil, errCycle
		}
	}
	return sorted, nil
}
