type LintDiagnostic struct {
	Line int    `json:"Line,omitempty"`
	Text string `json:"Text"`
	Code string `json:"Code,omitempty"`
}

// LintReportGroup groups the diagnostics of an analyzer.
type LintReportGroup struct {
	Text        string           `json:"Text"`
	Diagnostics []LintDiagnostic `json:"Diagnostics,omitempty"`
}

// LintFile is the lint report of a single file.
type LintFile struct {
	Name    string            `json:"Name"`
	Version string            `json:"Version,omitempty"`
	Error   string            `json:"Error,omitempty"`
	Reports []LintReportGroup `json:"Reports,omitempty"`
	Changes int               `json:"-"`
	Start   time.Time         `json:"-"`
	End     time.Time         `json:"-"`
}

// DiagnosticsCount returns the number of diagnostics of the file.
func (f *LintFile) DiagnosticsCount() int {
	n := 0
	for _, r := range f.Reports {
		n += len(r.Diagnostics)
	}
	return n
}

// LintReport is the report of the migrate lint command.
type LintReport struct {
	FromV string      `json:"-"`
	ToV   string      `json:"-"`
	Files []*LintFile `json:"Files"`
	Start time.Time   `json:"-"`
	End   time.Time   `json:"-"`
}

// TotalChanges returns the number of schema changes.
func (r *LintReport) TotalChanges() int {
	n := 0
	for _, f := range r.Files {
		n += f.Changes
	}
	return n
}

// DiagnosticsCount returns the total number of diagnostics.
func (r *LintReport) DiagnosticsCount() int {
	n := 0
	for _, f := range r.Files {
		n += f.DiagnosticsCount()
	}
	return n
}

// Status returns "ok", "with warnings" or "with errors".
func (r *LintReport) Status() string {
	for _, f := range r.Files {
		if f.Error != "" {
			return "with errors"
		}
	}
	if r.DiagnosticsCount() > 0 {
		return "with warnings"
	}
	return "ok"
}

